insert into public.mushroom_lookalikes (edible_slug,lookalike_slug,confusion_risk,key_differences,visual_differences,smell_differences,habitat_differences,spore_print_differences,pro_tip,source) values
('agaricus_augustus','agaricus_moelleri','mittel','{"Riesen-Champignon (Schiefknolliger Anis-Egerling) riecht angenehm nach Anis/Bittermandel; Perlhuhn-Champignon nach Karbol/Tinte","Stielbasis des Perlhuhn-Champignons laeuft sofort kraeftig chromgelb an; Riesen-Champignon gilbt nur schwach/aussen","Riesen-Champignon mit braeunlich-schuppigem (nicht graufleckigem) Hut, der auf Druck angenehm gilbt; Perlhuhn-Champignon graubraun perlhuhnartig gefleckt","Beim Erhitzen Anis-Duft (essbar) vs Tinten-/Karbolgeruch (giftig)","Riesen-Champignon wird sehr gross (Hut oft 10-25 cm); auffaellige Groesse allein ist aber KEIN Sicherheitsbeweis - Geruch + Stielbasis bleiben Pflicht"}','Riesen-Champignon mit braeunlich-schuppigem, auf Druck gilbendem Hut, gross; Perlhuhn-Champignon graubraun gefleckt, perlhuhnartig, kleiner.','Riesen-Champignon: Anis/Bittermandel. Perlhuhn-Champignon: Karbol/Tinte, beim Kochen widerlich. Geruch ist das zentrale Trennmerkmal.','Riesen-Champignon an Wegraendern, im Nadelwald, auf Kompost; Perlhuhn-Champignon Parks/Gaerten/Waldrand. Ueberlappung in Siedlungsnaehe moeglich.','Beide schokoladenbraun - KEIN Unterscheidungsmerkmal.','Karbolgeruch und chromgelbe Stielbasis sind das untruegliche Zeichen fuer den Giftpilz - im Zweifel den gesamten Fund wegwerfen, nicht auf die Groesse verlassen.','123pilze, pilzbuch-pilzwelten.de, DGfM, pilzkurse.com (Schweiz)'),
('agaricus_augustus','agaricus_xanthodermus','hoch','{"Riesen-Champignon: Anis-/Mandelgeruch, schwaches Gilben","Karbol-Champignon: Karbol-/Tintengeruch (verstärkt beim Erhitzen), chromgelbe Stielbasis"}','Geruch + Verfärbung an der Stielbasis (anis vs. karbol; schwach gelb vs. chromgelb).','Anis (essbar) vs. Karbol/Tinte (giftig) — wichtigstes Kriterium','beide Wald/Park/Garten','beide schokoladenbraun','Stielbasis anschneiden: kräftig chromgelb + Karbolgeruch = Karbol-Champignon (giftig). Bei weissen Egerlingen zudem Volva (Knollenblätterpilz) ausschliessen.','pilzbuch-pilzwelten.de / pilzkurse.com (CH)'),
('agaricus_campestris','agaricus_moelleri','mittel','{"Perlhuhn-/Karbol-Champignon riecht unangenehm nach Karbol/Tinte/Jod (Apotheke, Krankenhaus), beim Erhitzen widerlich verstaerkt; Wiesen-Champignon riecht angenehm pilzig-mild","Stielbasis des Perlhuhn-Champignons verfaerbt sich beim Kratzen/Anschneiden sofort kraeftig chromgelb (besonders im Knollenbereich); Wiesen-Champignon hoechstens schwach roetlich/braeunlich","Wiesen-Champignon hat von Anfang an rosa, spaeter schokobraune Lamellen (nie reinweiss); reinweisse Lamellen bei jungem Champignon = Warnsignal Richtung Gift-Champignon","Hutoberflaeche des Perlhuhn-Champignons graubraun gefleckt/schuppig (perlhuhnartig genattert); Wiesen-Champignon reinweiss bis cremefarben, glatt bis schuppig","Karbolgeruch UND chromgelbe Stielbasis treten zusammen auf und schliessen jeden Speise-Champignon sicher aus"}','Perlhuhn-Champignon mit graubraun geflecktem, perlhuhnartig genattertem Hut; Wiesen-Champignon reinweiss bis creme, glatt. Achtung: beide klein-mittelgross, im Feld leicht verwechselbar.','Giftpilz: Karbol/Tinte/Jod, beim Kochen widerlich verstaerkt. Wiesen-Champignon: angenehm pilzig-mild. Geruch ist hier ein zuverlaessiges Trennmerkmal.','Perlhuhn-Champignon eher in Parks, Gaerten, an Waldraendern und in Siedlungsnaehe; Wiesen-Champignon auf gemaehten Wiesen und Weiden. Habitat-Ueberlappung moeglich, daher nicht allein verlassen.','Beide schokoladenbraunes Sporenpulver - KEIN Unterscheidungsmerkmal.','Bei JEDEM Champignon Stielbasis anschneiden UND riechen: chromgelbes Anlaufen plus Karbol-/Tintengeruch (auch beim kurzen Anbraten testen) = Gift-Champignon, kompletter Korb-Inhalt verwerfen, nicht nur das Einzelexemplar.','123pilze, pilzkurse.com (Schweiz/VAPKO-nah), DGfM, Wikipedia Karbol-Champignon, pilzbuch-pilzwelten.de'),
('agaricus_campestris','amanita_phalloides','sehr_hoch_lebensgefahr','{"Champignon NIE Knolle in Hülle, Knollenblätter immer","Champignon-Lamellen werden rosa schokoladenbraun, Knollenblätter weiss"}','Champignon: weiss-beige Hut rosa Lamellen werden braun. Knollenblätter: olivgrüner Hut weisse Lamellen bleiben weiss.','Champignon: angenehm pilzig. Knollenblätter: schwach süsslich.','Champignon: Wiesen Weiden. Knollenblätter: Laubwald Eichen.','Champignon: dunkelbraun. Knollenblätter: weiss.','IMMER Stielbasis prüfen — Knolle in häutiger Hülle = NIEMALS essen!','VAPKO Schweiz'),
('agaricus_campestris','fliegenpilz_var_alba','mittel','{"Der Wiesen-Champignon hat jung rosa, später schwarzbraune freie Lamellen und braunes Sporenpulver; der weisse Fliegenpilz behält weisse Lamellen und hat weisses Sporenpulver","Champignons haben keine Scheide und keine warzig-gegürtelte Knolle — der weisse Fliegenpilz zeigt Velumwarzen und eine gerandete, geriefte Knollenbasis","Standort: Wiesen-Champignon auf offenen, gedüngten Wiesen/Weiden; weisser Fliegenpilz im Wald bei Birke/Nadelbaum","Jeden vermeintlichen Champignon mit weissen Lamellen sofort verwerfen — weisse Lamellen deuten auf Amanita hin"}','Wiesen-Champignon: rosa-braune Lamellen, ringtragender Stiel ohne Knollenscheide; weisser Fliegenpilz: weisse Lamellen, gegürtelte warzige Knolle.','Wiesen-Champignon angenehm pilzig; weisser Fliegenpilz unauffällig.','Wiesen-Champignon auf offenem Grasland; Fliegenpilz var. alba im/am Wald mykorrhizisch.','Wiesen-Champignon braunes Sporenpulver vs. weisses Sporenpulver beim Fliegenpilz.','Goldene Champignon-Regel: nie einen ''Champignon'' mit weiss bleibenden Lamellen essen — Sporenpulver-Abdruck (braun vs. weiss) macht den Unterschied.','pilzbuch-pilzwelten.de (Wiesenchampignon), steinpilz-wismar.de'),
('agaricus_silvicola','agaricus_moelleri','mittel','{"Duennfleischiger Anis-Egerling riecht deutlich nach Anis/Bittermandel (angenehm); Perlhuhn-Champignon nach Karbol/Tinte/Jod (unangenehm)","Stielbasis des Anis-Egerlings laeuft beim Schneiden hoechstens schwach gelblich an; die des Perlhuhn-Champignons sofort kraeftig chromgelb","Beim Erhitzen wird der Anis-Duft angenehm suesslich, der Perlhuhn-Champignon stinkt verstaerkt nach Tinte/Karbol","Anis-Egerling hat reinweissen, seidigen Hut (gilbt auf Druck leicht gelb); Perlhuhn-Champignon graubraun gefleckt/schuppig","Beide haben jung helle Lamellen - daher NIE an der Lamellenfarbe allein entscheiden, sondern Geruch + Stielbasis-Reaktion kombinieren"}','Anis-Egerling reinweiss seidig (gilbt schwach); Perlhuhn-Champignon graubraun gefleckt mit perlhuhnartiger Hutnatterung. Cave: weisslicher Habitus aehnlich.','Anis-Egerling: angenehm nach Anis/Bittermandel. Giftpilz: Karbol/Tinte/Jod, beim Kochen widerlich. Geruch ist das wichtigste Trennmerkmal.','Anis-Egerling im Nadel-/Mischwald; Perlhuhn-Champignon in Parks, Gaerten, an Waldraendern. Habitat hilft, ist aber nicht absolut trennscharf.','Beide schokoladenbraun - KEIN Unterscheidungsmerkmal.','Riech- und Kratzprobe an der Stielbasis ist Pflicht: Karbolgeruch plus chromgelbe Basis = giftig, nie essen. Anis-Geruch ohne chromgelbe Basis spricht fuer den Anis-Egerling - im Zweifel Sporenbild und Fachperson hinzuziehen.','123pilze, pilzkurse.com (Schweiz), pilzbuch-pilzwelten.de, DGfM'),
('agaricus_silvicola','fliegenpilz_var_alba','mittel','{"Der Anis-Egerling hat freie Lamellen, die jung rosa und später schokoladenbraun werden, und braunes Sporenpulver; der weisse Fliegenpilz hat dauerhaft WEISSE Lamellen und weisses Sporenpulver","Egerlinge besitzen KEINE Scheide/Volva und keine warzige, gegürtelte Knollenbasis — der weisse Fliegenpilz hat warzige Velumreste und eine gerandet-geriefte Knolle","Anis-Egerling riecht deutlich nach Anis/Marzipan; der weisse Fliegenpilz ist geruchlich unauffällig","Junge weisse Fliegenpilz-Knollen sehen champignonartig aus — daher immer Stielbasis ausgraben und Lamellenfarbe + Sporenpulver prüfen"}','Egerling: rosa bis braune Lamellen, glatter Stiel mit Ring, ohne Knollenscheide; weisser Fliegenpilz: weisse Lamellen, warzige gegürtelte Knolle.','Anis-Egerling nach Anis/Marzipan; weisser Fliegenpilz unauffällig.','Anis-Egerling in Wäldern; weisser Fliegenpilz mykorrhizisch bei Birke/Nadelbaum.','Anis-Egerling braunes Sporenpulver vs. weisses Sporenpulver beim Fliegenpilz — entscheidendes Trennmerkmal.','Sporenpulver-Probe und Lamellenfarbe sind der Lebensretter: weisse Lamellen + weisses Sporenpulver + Knollenscheide = niemals als Egerling essen.','pilzbuch-pilzwelten.de (Anis-Egerling/Schafchampignon), Wikipedia Fliegenpilz'),
('amanita_caesarea','amanita_muscaria','hoch','{"Fliegenpilz hat REINWEISSE Lamellen, weissen Stiel und weissen Ring - Kaiserling hat GELBE Lamellen, gelben Stiel und gelben Ring","Fliegenpilz hat eine warzige Knolle mit Warzenguerteln; Kaiserling eine dickhaeutige, sackartige, lappige weisse Volva (Eierschalen-Scheide)","Fliegenpilzhut traegt weisse, abwaschbare Flocken (Velumreste); Kaiserlinghut ist glatt orangerot ohne Flockenmuster","GEFAHR: vom Regen ausgewaschener oder verblasster Fliegenpilz verliert die weissen Flocken und kann orange wirken - dann allein Lamellen-/Stiel-/Ring-Farbe (weiss!) und die warzige Knolle entscheiden","Kaiserling in der Schweiz ausgesprochene Raritaet (nur warme Suedlagen, v.a. Tessin) - ein orangeroter Amanita ausserhalb solcher Lagen ist mit hoher Wahrscheinlichkeit Fliegenpilz"}','Kaiserling durchgehend gelb (Lamellen/Stiel/Ring) mit sackartiger weisser Volva und glattem orangerotem Hut; Fliegenpilz weiss (Lamellen/Stiel/Ring) mit warziger Knolle und (ggf. ausgewaschenen) Huthautflocken.','Beide unauffaellig-mild - Geruch ist KEIN Unterscheidungsmerkmal.','Kaiserling waermeliebend, in der Schweiz nur in Suedlagen (Tessin) extrem selten; Fliegenpilz haeufig bei Birke/Fichte im ganzen Land.','Beide weisses Sporenpulver - KEIN Unterscheidungsmerkmal.','Niemals einen orangeroten Pilz essen, ohne Lamellen, Stiel UND Ring zu pruefen: alles weiss = Fliegenpilz (giftig). Nur durchgehend GELBE Lamellen/Stiel/Ring plus sackartige weisse Volva sprechen fuer den Kaiserling - im Zweifel Fachperson/Pilzkontrolle (VAPKO).','awl.ch, pilzkurse.com (Schweiz), Wikipedia Fliegenpilz, fungiversum.de'),
('amanita_crocea','amanita_gemmata','hoch','{"Narzissengelber Wulstling hat eine zwiebelartige Knolle mit gerandeter, vergaenglicher Scheide UND einen (oft fluechtigen) Ring - Scheidenstreiflinge (inkl. Orangegelber Scheidenstreifling) haben NIE einen Ring","Scheidenstreifling besitzt eine hohe, hautige, freie Scheide (Volva) am Stielgrund, keine Knolle; Hutrand deutlich gerieft/gefurcht","Hut des Giftpilzes traegt weisse, eckige Velumreste (Hautflocken) und ist satt- bis blassgelb (kann bei Trockenheit ausbleichen); Scheidenstreifling-Hut orangegelb, flockenfrei, mit gerieftem Rand","Stiel des Scheidenstreiflings ohne haengende Ringmanschette; jeder geringelte gelbe Amanita ist verdaechtig","Wichtig: ausgeblichene gemmata-Huete koennen blasser/aehnlicher wirken - daher IMMER auf Ring + Knollenform achten, nicht nur auf Hutfarbe"}','Giftpilz: gelblicher Hut mit weissen Flockenresten, (fluechtiger) Ring am Stiel, zwiebelartige Knolle mit gerandeter Scheide. Scheidenstreifling: orangegelber, gerieft-randiger, flockenfreier Hut, KEIN Ring, hohe freie Scheide.','Beide unauffaellig - Geruch ist KEIN Unterscheidungsmerkmal.','Beide bei Laub-/Nadelbaeumen auf eher saurem Boden; Habitat trennt nicht zuverlaessig.','Beide weisses Sporenpulver - KEIN Unterscheidungsmerkmal.','Scheidenstreiflinge haben NIE einen Ring und nie eine gerandete Knolle - jeder gelbe Amanita MIT Ringmanschette und/oder Knolle ist verdaechtig (Narzissengelber Wulstling enthaelt Ibotensaeure/Muscimol und Muscarin) und gehoert nicht in den Korb.','123pilze, pilzbuch-pilzwelten.de, tintling.com, DGfM, ultimate-mushroom.com'),
('amanita_fulva','amanita_gemmata','hoch','{"Rotbrauner Scheidenstreifling ist RINGLOS - Narzissengelber Wulstling hat einen (oft fluechtigen) haengenden Ring","Scheidenstreifling mit hoher, freier, rotbraun gefleckter Scheide (Volva) am Stielgrund statt zwiebelartiger Knolle mit gerandeter Scheide","Hut des Scheidenstreiflings rotbraun bis fuchsig, glatt, stark gerieft am Rand, ohne Velumflocken; Giftpilz gelb (bei Trockenheit ausgeblichen) mit weissen Hautflocken","Stiel des Scheidenstreiflings ohne genatterte Ringzone und ohne Manschette","Rotbrauner Scheidenstreifling sollte ohnehin nur gut durchgegart gegessen werden - roh sind Streiflinge unvertraeglich"}','Scheidenstreifling rotbraun, gerieft, flockenfrei, ringlos, mit hoher Scheide; Giftpilz gelblich, flockig, mit (fluechtigem) Ring und gerandeter Knolle.','Beide unauffaellig - KEIN Unterscheidungsmerkmal.','Beide bei Laub-/Nadelbaeumen auf eher saurem Boden; Habitat trennt nicht.','Beide weisses Sporenpulver - KEIN Unterscheidungsmerkmal.','Auf Ring und Knolle achten: Scheidenstreiflinge sind immer ringlos mit hoher freier Scheide; ein gelber Amanita mit Ring oder gerandeter Knolle ist der giftige Narzissengelbe Wulstling - im Zweifel stehen lassen.','123pilze, pilzbuch-pilzwelten.de, tintling.com, first-nature.com'),
('amanita_rubescens','amanita_franchetii','mittel','{"Perlpilz (rubescens): Fleisch und Druckstellen RÖTEN deutlich (weinrötlich), oft rötliche Madengänge – Gelbflockiger/Rauer Wulstling (franchetii): Fleisch rötet NICHT.","franchetii hat gelbe bis schwefelgelbe Velumflocken auf dem Hut, gelb gerandeten Ring und gelbliche Flockengürtel an der Stielbasis – rubescens hat schmutzig-graue bis rötliche, NICHT gelbe Velumreste.","franchetii ist giftig/unverträglich (roh stark giftig); rubescens nur roh giftig, durcherhitzt essbar – im Zweifel gilt: kein Röten + gelbe Flocken = nicht essen.","franchetii wirkt wie ein ''kleiner Perlpilz ohne Rot'' – genau die fehlende Rötung plus die gelben Flocken ist der Warnhinweis."}','rubescens rötet an Fleisch/Druckstellen und hat graurosa Velum; franchetii rötet nicht und zeigt schwefelgelbe Velumflocken plus gelb gerandeten Ring und gelbe Flockengürtel an der Stielbasis.','Beide unauffällig-pilzig; kein verlässliches Geruchsmerkmal.','Beide in warmen Laubwäldern; franchetii deutlich wärmeliebender und seltener.','Beide weisses Sporenpulver – kein Unterscheidungsmerkmal.','Drucktest: Perlpilz rötet IMMER (Fleisch anschneiden/quetschen, einige Minuten warten). Bleibt es weiss-gelblich und sind die Flocken gelb, ist es franchetii – stehen lassen. Beachte: auch Pantherpilz (tödlich) gehört in diese Verwechslungsgruppe – Anfänger zur Pilzkontrolle.','123pilzsuche.de (Gelbflockiger/Rauer Wulstling, Amanita franchetii), tintling.com (Amanita franchetii), pilzbuch-pilzwelten.de (Perlpilz)'),
('amanita_rubescens','amanita_gemmata','hoch','{"Perlpilz roetet bei Verletzung/Madenfrass deutlich weinrot/fleischrosa - Narzissengelber Wulstling roetet NIE, sein Fleisch bleibt weiss-gelblich (zuverlaessigstes Trennmerkmal)","Perlpilz hat einen kraeftigen, oberseits gerieften (gerillten) Ring; der Ring des Giftpilzes ist duenn und vergaenglich (oft fehlend)","Hutfarbe Perlpilz sehr variabel (weisslich, braungelblich, fleischrosa bis rotbraun) - daher NICHT allein auf Farbe verlassen; Giftpilz meist satt zitronen-/ockergelb, bei Trockenheit ausbleichend","Knolle des Perlpilzes rundlich mit Velumguerteln (ohne gerandete Scheide); Giftpilz mit zwiebeliger Knolle und gerandeter Restscheide","Stielbasis/Fraßstellen des Perlpilzes oft rosa/weinrot angelaufen, beim Giftpilz nicht"}','Perlpilz mit rosa Roetung an Druck-/Fraßstellen und kraeftig gerieftem Ring (Hutfarbe variabel); Giftpilz meist leuchtend gelb, nicht roetend, mit fluechtigem Ring.','Beide unauffaellig-mild - KEIN verlaessliches Unterscheidungsmerkmal.','Beide im Laub-/Nadelwald; Habitat trennt nicht.','Beide weisses Sporenpulver - KEIN Unterscheidungsmerkmal.','Der Perlpilz MUSS roeten und ist nur gut durchgegart geniessbar - ein gelber, NICHT roetender Wulstling gehoert nie in den Korb (Narzissengelber Wulstling: Ibotensaeure/Muscimol und Muscarin). Roh ist auch der Perlpilz giftig.','123pilze, pilzbuch-pilzwelten.de, DGfM, fungiversum.de'),
('amanita_rubescens','amanita_pantherina','sehr_hoch_lebensgefahr','{"Perlpilz: Fleisch rötet (v.a. Stielbasis/Madengänge), geriefter Ring, graue Velumflocken","Pantherpilz: Fleisch rötet NIE, glatter Ring, reinweisse Flocken, gerandet-knollige Basis, Gifte hitzestabil"}','Rötungsprobe + Ring (gerieft vs. glatt) + Knolle entscheiden.','kaum unterscheidbar','beide alle Waldtypen','beide weiss','Perlpilz nur für Erfahrene. Alle Merkmale ZUSAMMEN prüfen (Rötung + geriefter Ring + Knolle ohne gerandete Scheide).','awl.ch / de.wikipedia.org'),
('amanita_rubescens','amanita_porphyria','mittel','{"Porphyrbrauner Wulstling (porphyria): scharf abgesetzte, gerandet-knollige Stielbasis und kupfrig violett-graubrauner (porphyrfarbener) Hutton, Fleisch rötet NICHT – Perlpilz (rubescens): keulig verdickte, NICHT gerandete Knolle, Fleisch und Druckstellen RÖTEN deutlich.","porphyria riecht charakteristisch dumpf nach rohen Kartoffeln/Kartoffelkeimen (Rettich-/Kartoffelnote) – rubescens unauffällig-pilzig.","porphyria enthält Bufotenin plus hitzestabile Magen-Darm-Gifte und ist als giftig eingestuft – nicht essen; rubescens nur roh giftig, durcherhitzt essbar.","Fehlendes Röten + Kartoffel-/Rettichgeruch + scharf gerandete Knolle = porphyria, nicht Perlpilz."}','porphyria graubraun mit kupfrig-violettem Porphyr-Ton, grauen Velumresten und scharf gerandeter Knolle, kein Röten; rubescens fleischbraun-rötlich mit keuliger, nicht gerandeter Knolle und deutlichem Röten.','porphyria deutlich dumpf nach rohen Kartoffeln/Kartoffelkeimen; rubescens neutral-pilzig.','porphyria vorwiegend in Nadelwäldern auf saurem Boden; rubescens in Laub- und Nadelwäldern breiter verbreitet.','Beide weisses Sporenpulver (porphyria amyloid) – mikroskopisch, im Feld kein Trennmerkmal.','Knolle und Drucktest entscheiden: scharf gerandete Knolle + Kartoffel-/Rettichgeruch + kein Röten = porphyria stehen lassen. Perlpilz rötet immer. Im Zweifel zur Pilzkontrolle.','de.wikipedia Porphyrbrauner Wulstling (Bufotenin, Kartoffelkeim-Geruch, gerandete Knolle), tintling.com (Amanita porphyria), pilzbuch-pilzwelten.de (Perlpilz)'),
('amanita_rubescens','fliegenpilz-roetlich','hoch','{"Perlpilz (essbar) rötet bei Verletzung, Druck und Madenfrass deutlich fleisch- bis weinrot/rosa — der braune Königsfliegenpilz (Amanita regalis) tut das NIE.","Königsfliegenpilz: weisses Fleisch, aber direkt unter der Huthaut eine charakteristische gelbe bis gelbbraune Zone (im Längs-/Querschnitt sichtbar) — beim Perlpilz fehlt diese gelbe Schicht.","Hutfarbe Königsfliegenpilz: leder- bis dunkel-graubraun mit gelblichen bis grauweissen, abwischbaren Velumflocken; Perlpilz: rötlich-braun bis fleischbräunlich mit grauen bis rötlich überhauchten Hautresten.","Königsfliegenpilz wächst als Fichten-Symbiont fast nur im sauren Nadelwald (eher Bergland/höhere Lagen) — Perlpilz bevorzugt Laub- und Mischwald, auch tieferlagig und breit verbreitet.","Königsfliegenpilz enthält Ibotensäure/Muscimol wie der rote Fliegenpilz (Pantherina-Syndrom: Verwirrung, Halluzinationen, Krämpfe, in grösseren Mengen Kreislaufversagen/Atemlähmung) — kein Speisepilz, auch nicht gekocht."}','Königsfliegenpilz hat einen leder- bis dunkel-graubraunen Hut mit gelblich-grauen Velumflocken und eine gelbe bis gelbbraune Zone unter der Huthaut; der Perlpilz rötet an Frass- und Druckstellen rosa bis weinrot und zeigt diese gelbe Subkutiszone nicht.','Beide riechen unauffällig pilzig — der Geruch hilft hier NICHT zur Unterscheidung, daher sind die Rötung und die gelbe Schicht unter der Huthaut die entscheidenden Merkmale.','Königsfliegenpilz nur im sauren Nadelwald als Fichten-Symbiont (eher Bergland); Perlpilz in Laub-, Nadel- und Mischwald breit verbreitet, auch in tieferen Lagen.','Beides Weisssporer — das Sporenpulver trennt die beiden nicht; entscheidend sind Rötung und gelbe Subkutiszone unter der Huthaut.','Bei braunhütigen Wulstlingen IMMER das Fleisch anschneiden und 10-15 Min beobachten: rötet es rosa/weinrot = Perlpilz; bleibt es weiss mit gelber Schicht direkt unter der Huthaut = giftiger Königsfliegenpilz, stehen lassen. Im Zweifel bei lamelligen Wulstlingen generell verzichten.','DGfM (Pilz des Jahres 2000), 123pilze (Königsfliegenpilz/Brauner Fliegenpilz), Wikipedia Perlpilz, Stadt Wien Konsumentenschutz'),
('amanita_strobiliformis','amanita_echinocephala','mittel','{"Igel-Wulstling (echinocephala): spitze, pyramidenförmig-stachelige, NICHT abwischbare Velumreste auf dem Hut – Fransiger Wulstling (strobiliformis): fransig-zerfetzte, weiche, abwischbare Velumflocken, KEINE harten Pyramidenstacheln.","echinocephala riecht unbedeutend bis schwach unangenehm und verfärbt sich an Stielbasis und Lamellen oft schmutzig grünlich-grau – strobiliformis riecht neutral mit schwacher Rettichkomponente, Lamellen rein weiss bis creme.","echinocephala ist als (schwach) giftig / Magen-Darm-unverträglich eingestuft – sicherheitshalber NIE als Speisepilz nehmen.","Beide weisslich, gross, warzig und auf Kalkboden – allein die Velum-Form (harte Stacheln vs. weiche Fransen) trennt sie sicher."}','echinocephala trägt feste, spitz-pyramidale, nicht abwischbare Velumstacheln und neigt zu schmutzig grünlich-grauer Verfärbung; strobiliformis weiche, fransig-zerfetzte, abwischbare Velumflocken auf weiss-graubräunlichem Hut, ohne Grünton.','echinocephala unbedeutend bis schwach unangenehm; strobiliformis neutral mit leichter Rettichnote – Geruch allein ist KEIN sicheres Trennmerkmal.','Beide thermophil auf kalkreichem Boden im Laubwald – Habitat trennt nicht, nur das Velum.','Beide weisses Sporenpulver – kein Unterscheidungsmerkmal.','Bei jedem weissen, warzigen Grosswulstling auf Kalk: Velumreste prüfen – harte, nicht abwischbare Pyramidenstacheln = Finger weg. Velum-Form kann witterungsbedingt verwaschen sein – im Zweifel IMMER zur Pilzkontrolle (VAPKO).','pilzbuch-pilzwelten.de (Amanita echinocephala / strobiliformis), de.wikipedia Fransiger Wulstling, mushroom-toxin.de (Igel-Wulstling: schwach giftig)'),
('amanita_strobiliformis','amanita_ovoidea','mittel','{"Eier-Wulstling (ovoidea): jung rein eiförmig-weiss, glatt bis mehlig-flockig, mit dicker, sackartiger, gelblich bis hellorange getönter Volva an der Basis und bald zerfallendem, häutigem Ring – Fransiger Wulstling (strobiliformis): fransig-zerfetzte Velumflocken auf dem Hut, rübenförmige Knolle mit vergänglicher Scheide.","ovoidea-Velum hinterlässt mehlig-glatte Reste, Ring zerbröckelt früh – strobiliformis mit deutlich fransigem, zerfetztem Velum.","ovoidea im Alter mit aasartig-unangenehmem Geruch; strobiliformis neutral mit schwacher Rettichnote.","ACHTUNG: ovoidea selbst gilt zwar als essbar, ist aber wegen Verwechslung mit dem nierengiftigen Ockerscheidigen Eier-Wulstling (A. proxima, gelb-ocker bleibende Volva) und tödlichen Knollenblätterpilzen NIE für Anfänger geeignet.","Beide gross, weiss und kalkliebend – die Velumstruktur (fransig vs. mehlig-glatt mit Sackvolva) ist das Haupttrennmerkmal."}','ovoidea glatt-mehliger weisser Eier-Pilz mit dicker, gelblich bis hellorange getönter Sackvolva und bald zerfallendem Ring; strobiliformis mit fransig-zerfetzten Velumflocken und rübenförmiger Knolle.','ovoidea im Alter aasartig-unangenehm; strobiliformis neutral mit leichter Rettichnote.','Beide thermophil auf Kalk – Habitat trennt nicht, eher Velum und Volvaform.','Beide weisses Sporenpulver – kein Unterscheidungsmerkmal.','Weisse Grosswulstlinge auf Kalk niemals als Anfänger essen – die Gruppe um Eier-/Fransiger Wulstling grenzt an den nierengiftigen A. proxima und tödliche Knollenblätterpilze. Immer Pilzkontrolle (VAPKO).','de.wikipedia Echter Eier-Wulstling (essbar, aasartig im Alter, Verwechslung A. proxima + Knollenblätterpilze), pilzbuch-pilzwelten.de (strobiliformis)'),
('amanita_strobiliformis','fliegenpilz_var_alba','mittel','{"Der Fransige Wulstling trägt weiche, mehlig-watteartige, leicht abwischbare Velumflocken und KEINEN gerieften Knollenrand; der weisse Fliegenpilz hat warzig-gegürtelte Velumreste und eine deutlich gerandet-geriefte Knollenbasis","Beim weissen Fliegenpilz ist der Ring häutig-hängend mit gezähneltem Rand und die Stielbasis zeigt konzentrische Velum-Gürtelringe; beim Fransigen Wulstling fehlen diese Gürtelzonen","Standortprüfung: weisser Fliegenpilz bei Birke/Kiefer/Fichte (Mykorrhiza, saure Böden); Fransiger Wulstling auf kalkreichen, warmen Laubwaldböden","Im Zweifel beide stehen lassen — eine rein weisse Amanita ohne sichere Bestimmung NIE verzehren (Phalloides-/Virosa-Gruppe ist tödlich)"}','Fransiger Wulstling: grosse, weiche, abwischbar-mehlige Hutflocken, ungeriefter Knollenrand; weisser Fliegenpilz: warzige Gürtelflocken auf Hut und gerieft-gerandeter Knolle.','Fransiger Wulstling jung angenehm, alt unangenehm; weisser Fliegenpilz unauffällig — Geruch trennt nicht sicher.','Fliegenpilz var. alba bei Birke/Nadelbaum auf saurem Boden; Amanita strobiliformis auf kalkreichem Laubwaldboden.','Beide weisses Sporenpulver — kein Trennmerkmal.','Bei JEDER weissen Amanita die Stielbasis vollständig ausgraben und Knolle, Velum-Gürtel und Riefung prüfen — weisse Wulstlinge nur mit absoluter Bestimmungssicherheit essen.','steinpilz-wismar.de (Wulstlinge/Amanita), Wikipedia Fliegenpilz, pilzfinder.de'),
('amanita_vaginata','amanita_porphyria','mittel','{"Grauer Scheidenstreifling (vaginata): OHNE Ring/Manschette und mit häutiger Scheide (Volva) an der ungeknollten Basis, Hutrand deutlich gerieft – Porphyrbrauner Wulstling (porphyria): mit hängendem Ring und scharf gerandeter, zwiebelförmiger Knolle (KEINE freie Scheide).","porphyria graubraun mit kupfrig-violett-porphyrfarbenem Ton und Kartoffel-/Rettichgeruch – vaginata schlicht grau, mild und ohne auffälligen Geruch.","vaginata-Stiel ringlos und schlank; porphyria-Stiel mit Ringzone und abgesetzter Knolle.","porphyria ist bufoteninhaltig und giftig; vaginata gut durcherhitzt essbar (roh giftig) – das Vorhandensein von Ring + Knolle weist auf porphyria.","Faustregel: Ring + gerandete Knolle = kein Scheidenstreifling, sondern ein Knollen-Wulstling (hier giftiger porphyria)."}','vaginata ringlos mit Volva-Scheide und stark gerieftem Hutrand; porphyria mit Ring und gerandeter Zwiebelknolle, kupfrig violett-graubraunem Hut.','porphyria nach rohen Kartoffeln/Rettich; vaginata geruchlos bis mild.','porphyria bevorzugt saure Nadelwälder; vaginata in Laub- und Nadelwäldern.','Beide weisses Sporenpulver – kein Feld-Unterscheidungsmerkmal.','Scheidenstreiflinge haben NIE einen Ring. Findest du Ring plus gerandete Knolle, ist es ein Knollen-Wulstling – bei Violett-Ton und Kartoffelgeruch der giftige porphyria. Wichtiger: ringlose graue Streiflinge können mit tödlichen jungen Knollenblätterpilzen verwechselt werden – Volva und Knolle immer ausgraben, im Zweifel Pilzkontrolle.','de.wikipedia Porphyrbrauner Wulstling + Grauer Scheidenstreifling, pilzbuch-pilzwelten.de (Amanita porphyria)'),
('austernpilz','galerina_marginata','gering','{"Sporenpulver: Austernseitling weiss bis lila-grau; Gifthaeubling rost-/zimtbraun (Sporenabwurf auf dunklem + hellem Papier ist das sicherste Trennmerkmal).","Stiel: Austernseitling hat einen seitlichen/exzentrischen, kurzen oder fast fehlenden Stiel und KEINEN Ring; Gifthaeubling hat einen zentralen, schlanken Stiel mit haeutigem Ringzonen-Rest im oberen Drittel.","Wuchsform: Austernseitling waechst dachziegelig in dicken, fleischigen Buescheln/Konsolen direkt am Holz; Gifthaeubling waechst klein, einzeln bis gebuendelt mit duenn-fleischigem, gewoelbtem Hutchen auf Totholz.","Lamellen: Austernseitling mit breiten, weisslichen, am (seitlichen) Stiel herablaufenden Lamellen; Gifthaeubling mit schmalen, jung blass-ockerfarbenen, im Alter zimtbraun verfaerbenden Lamellen (durch braunes Sporenpulver).","Groesse/Konsistenz: Austernseitling gross (Hut 5-25 cm), zaeh-fleischig; Gifthaeubling klein (Hut meist 1-4 cm), zerbrechlich, mit deutlichem Stiel wie ein normaler Lamellenpilz."}','Austernseitling: muschel-/faecherfoermiger Hut 5-25 cm, weiss/grau/braun, dachziegelige Buschel; seitlicher oder fehlender Stiel; breite weissliche herablaufende Lamellen. Gifthaeubling: kleines gewoelbtes ocker- bis zimtbraunes Hutchen 1-4 cm mit zentralem schlankem braeunlichem Stiel, Ringzone im oberen Stieldrittel, im Alter zimtbraune Lamellen.','Austernseitling: mild, angenehm pilzig-anisartig. Gifthaeubling: schwach mehlartig bis unauffaellig - Geruch ist KEIN sicheres Trennmerkmal, daher nicht darauf verlassen.','Beide auf Holz, aber: Austernseitling bevorzugt Laubholz (Buche/Pappel), buschelig-konsolenartig, oft hoch am Stamm; Gifthaeubling auf morschem Totholz (haeufig Nadelholz, aber auch Laubholz), klein, einzeln bis gebuendelt, eher bodennah/auf liegenden Staemmen.','Austernseitling: WEISS bis blass lila-grau. Gifthaeubling: ROST-/ZIMTBRAUN. Dies ist das zuverlaessigste Einzelmerkmal - der Sporenabwurf trennt die beiden sicher.','Goldene Regel: Ein echter Austernseitling sitzt seitlich/stiellos als dicke fleischige Konsole am Holz und gibt einen WEISSEN bis lila-grauen Sporenabwurf. Sobald ein zentraler Stiel mit Ringrest vorhanden ist ODER der Sporenabwurf braun ausfaellt, ist es KEIN Austernseitling - dann Hände weg (Gifthaeubling enthaelt toedliche Amatoxine, gleiches Gift wie der Knollenblaetterpilz). Im Zweifel immer einen Sporenabwurf machen, bevor gegessen wird.','https://en.wikipedia.org/wiki/Pleurotus_ostreatus · https://www.pilzfinder.de/pilz/gifthaeub.html · https://de.wikipedia.org/wiki/Gift-H%C3%A4ubling · https://oyster-mushroom.com/oyster-mushroom-identification-and-poisonous-lookalikes/ · https://www.mushroomexpert.com/pleurotus_ostreatus.html'),
('butterpilz','tricholoma_ustale','gering','{"Butterpilz (essbar) ist ein Roehrling mit ROEHREN unter dem Hut und meist einem Ring am Stiel; der Brandige Ritterling hat LAMELLEN und keinen Ring.","Aehnlichkeit nur ueber den braunen, schleimig-schmierigen Hut aus der Distanz - der ustale-Hut kann von oben an einen Butterpilz erinnern.","Butterpilz-Huthaut laesst sich leicht abziehen, Roehren gelblich; ustale-Lamellen werden rostfleckig.","Butterpilz waechst in Mykorrhiza bei Kiefer, ustale im Laubwald.","Geschmack: Butterpilz mild, ustale bitterlich."}','Butterpilz mit Roehren und Stielring; ustale mit rostfleckig werdenden Lamellen ohne Ring.','beide unauffaellig/mild bis schwach mehlig - kein verlaessliches Trennmerkmal.','Butterpilz bei Kiefer, ustale im Laubwald bei Buche/Eiche.','Butterpilz olivbraunes Sporenpulver (Roehrling), ustale weiss (Blaetterpilz).','Hutunterseite checken: Roehren = Butterpilz/Roehrling, Lamellen = Ritterling. Lamellenpilz mit braunem Schmierhut nie als Butterpilz mitnehmen.','123pilze, pilzbuch-pilzwelten.de, SwissFungi'),
('butyriboletus_appendiculatus','caloboletus_calopus','mittel','{"Schoenfuss-Roehrling schmeckt stark BITTER (bleibt auch gekocht bitter) - Anhaengselroehrling schmeckt mild und angenehm","Hut des Anhaengselroehrlings warm braun bis ledergelb; Schoenfuss-Roehrling lehmgrau/graubraun","Anhaengselroehrling blaut nur schwach/langsam; Schoenfuss-Roehrling blaut rasch und kraeftig blaugruen","Anhaengselroehrling-Stiel gelb mit feinem gelbem Netz und wurzelndem Fortsatz; Schoenfuss-Roehrling-Stiel unten kraeftig rot genetzt","Fleisch des Anhaengselroehrlings goldgelb und mild; beim Schoenfuss bitter"}','Anhaengselroehrling: brauner Hut, gelber Stiel mit gelbem Netz, schwaches Blauen. Schoenfuss-Roehrling: grauer Hut, rot-gelber Netzstiel, kraeftiges Blauen.','Beide unauffaellig - der bittere Geschmack ist das entscheidende Trennmerkmal.','Beide waermeliebend im Laub-/Mischwald (Eiche/Buche); Habitat trennt nicht.','Beide olivbraunes Sporenpulver - KEIN Unterscheidungsmerkmal.','Geschmacksprobe (winziges Stueck, ausspucken): jeder bittere Roehrling fliegt aus dem Korb - der milde Anhaengselroehrling ist nie bitter. Bei rotem Stielnetz plus kraeftigem Blauen besonders kritisch pruefen.','pilzkurse.com (Schweiz), pilzbuch-pilzwelten.de, awl.ch'),
('butyriboletus_appendiculatus','roehrling_flockenstielig','mittel','{"Schönfuß-Röhrling (Caloboletus calopus) schmeckt deutlich BITTER — Kostprobe (Zungenspitze, ausspucken) ist das sichere Trennkriterium; Anhängselröhrling schmeckt mild-nussig","Schönfuß hat einen blass lehmgrauen/graubraunen Hut; Anhängselröhrling hat einen warm ocker- bis kastanienbraunen Hut","Schönfuß-Stiel mit kräftig rotem Bereich und Netz im unteren Stielteil; Anhängselröhrling-Stiel überwiegend gelb mit feinem gelblichem Netz und nur rötlicher Basis","Beide blauen bei Druck/Anschnitt (Poren/Fleisch) — das Blauen allein trennt NICHT; entscheidend sind Bittergeschmack und Stielfarbe","Schönfuß bevorzugt sauren, mageren Boden (gern Nadel-/Bergwald); Anhängselröhrling wärmeliebend in Laubwald auf kalkhaltigem Boden"}','Lehmgrau-graubrauner Hut + roter unterer Stielteil beim Schönfuß vs. ocker-/kastanienbrauner Hut + überwiegend gelber Stiel beim Anhängselröhrling.','Beide unauffällig pilzig — Geruch trennt nicht; der Geschmackstest (bitter vs. mild) ist entscheidend.','Schönfuß auf saurem, magerem Boden/Nadel-/Bergwald; Anhängselröhrling wärmeliebend im Laubwald auf Kalk.','Beide olivbraunes Sporenpulver — kein Unterscheidungsmerkmal.','Bei jedem Röhrling mit Stielnetz die Bitter-Kostprobe machen: bitter = wegwerfen. Netz am Stiel + bitterer Geschmack = Schönfuß, ungeniessbar. Der Anhängselröhrling ist zudem geschützt/selten — im Zweifel stehen lassen.','123pilze, AWL.ch, Wikipedia (Schönfuß-Röhrling), tintling.com'),
('butyriboletus_appendiculatus','rubroboletus_legaliae','hoch','{"Le Gals hat ROTE bis orangerote/blutrote Poren; Anhängselröhrling hat GELBE Poren — rote Poren bei Röhrlingen sind ein generelles Warnsignal","Le Gals hat einen blassen weiss-/graurosa bis altrosa Hut; Anhängselröhrling einen warm ocker- bis kastanienbraunen Hut","Le Gals riecht nach Sellerie/Liebstöckel und ist auch gekocht giftig/unverträglich; Anhängselröhrling riecht mild pilzig und ist mild-essbar","Le Gals-Stiel mit rotem Netz auf rötlich-orangem Grund; Anhängselröhrling-Stiel überwiegend gelb mit feinem gelblichem Netz","Beide können blauen — das Blauen allein reicht NICHT; entscheidend ist die Porenfarbe (rot vs. gelb) plus Selleriegeruch"}','Rote Poren + blass-/graurosa Hut beim Le Gals vs. gelbe Poren + ocker-/kastanienbrauner Hut beim Anhängselröhrling.','Le Gals nach Sellerie/Liebstöckel; Anhängselröhrling mild pilzig.','Beide wärmeliebend im Laubwald (Eiche/Buche) auf Kalk — Standort überlappt, trennt nicht.','Beide olivbraun — kein Trennmerkmal.','Goldene Röhrlingsregel: rote Poren = nicht in den Korb ohne sichere Bestimmung. Nur gelbe Poren + mildes Fleisch + fehlender Selleriegeruch beim Anhängselröhrling sind unbedenklich (der zudem geschützt/selten ist).','123pilze, Wikipedia (Rubroboletus legaliae / Butyriboletus), AWL.ch, DGfM'),
('butyriboletus_appendiculatus','rubroboletus_satanas','hoch','{"Anhaengselroehrling (Dickfussroehrling) hat GELBE Poren, der Satansroehrling rote bis orange Poren.","Anhaengselroehrling blaut nur schwach im gelben Fleisch und hat keinen Aasgeruch; Satansroehrling riecht im Alter widerlich nach Aas.","Anhaengselroehrling hat braunen, samtigen Hut; Satansroehrling jung hellen, kalkweiss bis weisslich-graugruenen Hut.","Anhaengselroehrling-Stiel ist gelb mit feinem gelbem Netz, oft mit wurzelndem Anhaengsel; Satansroehrling-Stiel rotgenetzt und knollig.","Beide wachsen auf Kalk im warmen Laubwald - die rote Porenfarbe ist das Sicherheitskriterium."}','Anhaengselroehrling hat gelbe Poren und gelben Stiel, Satansroehrling rote Poren und rotgenetzten Stiel.','Satansroehrling riecht alt nach Aas, der Anhaengselroehrling angenehm pilzig.','Beide kalkliebend in warmen Eichen-/Buchenwaeldern - kein Trennmerkmal.','Beide olivbraunes Sporenpulver - nicht trennend.','Bei roten oder orangen Poren immer stehen lassen - gelbporige Dickfussroehrlinge sind essbar, rotporige sind tabu.','123pilze, AWL.ch (Vergleich rotporige Roehrlinge), pilzbuch-pilzwelten.de'),
('calocybe_gambosa','hebeloma_crustuliniforme','mittel','{"Der Maipilz riecht stark mehlig-gurkig; der Tränende Fälbling riecht rettichartig — Rettichgeruch ist ein Warnsignal","Maipilz hat WEISSES Sporenpulver; Hebeloma crustuliniforme hat rost- bis braunolives Sporenpulver","Beim Tränenden Fälbling hängen jung wässrige Tröpfchen an den Lamellenschneiden, die braune Sporenflecken hinterlassen — beim Maipilz fehlen diese tränenden Lamellen","Maipilz hat jung dichtgedrängte, weisse, gerade angewachsene Lamellen; Fälbling-Lamellen sind hell graubraun und verfärben rostbraun"}','Maipilz creme-weiss mit dicht gedrängten weissen Lamellen; Tränender Fälbling tongrau-blass mit tränenden, später rostbraunen Lamellen.','Maipilz mehlig-gurkig (Speisepilz-Marker); Fälbling rettichartig (Giftpilz-Hinweis).','Beide können im Frühjahr erscheinen — Maipilz klassisch um Georgstag (Ende April/Mai) in Hexenringen auf Wiesen/Waldrändern.','Maipilz weisses Sporenpulver vs. rostbraun-oliv beim Tränenden Fälbling — sicherstes Trennmerkmal.','Immer einen Sporenabdruck machen: weiss = möglicher Maipilz, rost-/braun = Fälbling und verwerfen; zusätzlich Mehlgeruch (gut) vs. Rettichgeruch (Warnung) prüfen.','pilze.ch (Gattung Hebeloma), 123pilze (Tonblasser Fälbling/Mairitterling), passion-pilze-sammeln.com'),
('calocybe_gambosa','hebeloma_sinapizans','mittel','{"Der Maipilz riecht mehlig-gurkig; der Rettich-Fälbling riecht stark nach Rettich und schmeckt bitter — Rettichgeruch ist ein Warnsignal","Maipilz hat WEISSES Sporenpulver; Hebeloma sinapizans hat rostbraunes Sporenpulver","Maipilz-Lamellen jung weiss und dichtgedrängt; Rettich-Fälbling-Lamellen graubraun, ausgerandet angewachsen, NICHT tränend, oft mit zapfenartigem Fortsatz im Stiel (Längsschnitt)","Rettich-Fälbling ist gedrungen-fleischig auf kalkreichen Böden bei Buche, Hauptwachstum erst spät im Jahr"}','Maipilz creme-weiss, kompakt, weisse Lamellen; Rettich-Fälbling tonbraun mit graubraunen Lamellen und knolliger Basis.','Maipilz mehlig-gurkig; Rettich-Fälbling kräftig rettichartig.','Maipilz erscheint im Frühjahr (Mai) in Hexenringen; Hebeloma sinapizans vorwiegend August–Oktober im Laubwald (Buche, Kalk).','Maipilz weisses Sporenpulver vs. rostbraun beim Rettich-Fälbling — sicherstes Trennmerkmal.','Sporenabdruck + Geruch entscheiden: weisses Pulver und Mehlgeruch = möglicher Maipilz; rostbraunes Pulver und Rettichgeruch = Fälbling und unbedingt verwerfen.','pilze.ch (Gattung Hebeloma), 123pilze (Grosser Rettichfälbling/Mairitterling), tintling.com'),
('calocybe_gambosa','inocybe_erubescens','sehr_hoch_lebensgefahr','{"Maipilz: weisse Lamellen in jedem Alter + Mehlgeruch, Fleisch rötet NICHT","Risspilz: Fleisch rötet, graubraune Lamellen, braunes Sporenpulver, hoher Muscarin-Gehalt"}','Beide Frühling, hell; Risspilz radialfaserig/rissig und rötend, Maipilz glatt-fleischig.','Maipilz stark mehlig-gurkig; Risspilz süsslich-spermatisch','beide Wiesen/Wald-Ränder, kalkhaltig, gleiche Saison','Maipilz weiss, Risspilz braun','TÖDLICH (Muscarin). Weisse Lamellen + Mehlgeruch + keine Rötung sind Pflicht — sonst Finger weg.','Tox Info Suisse / pilzbuch-pilzwelten.de'),
('calocybe_gambosa','inocybe_rimosa','hoch','{"Maipilz riecht stark mehlig-gurkig; Kegeliger Risspilz riecht spermatisch/erdig-unangenehm","Maipilz-Hut weisslich bis cremefarben, glatt, am Rand eingerollt; Risspilz-Hut ocker-/strohbraun, kegelig-gebuckelt und radial AUFGERISSEN (rissige Hutoberfläche)","Maipilz-Lamellen weiss bis creme, dicht; Risspilz-Lamellen jung blass, bald tonig-graubraun","Risspilze enthalten Muscarin (Schweissausbruch, Speichelfluss, Sehstörung 15-120 Min) - der nah verwandte Ziegelrote Risspilz (Inocybe erubescens) am selben Standort hat sogar Todesfälle verursacht; Maipilz ungiftig","Beide erscheinen im Frühling (April/Mai) am selben Standort - Verwechslung gerade deshalb gefährlich"}','Der radial eingerissene, kegelig-gebuckelte ocker-braune Risspilz-Hut steht im klaren Kontrast zum glatten, weisslichen, gewölbten Maipilz-Hut.','Maipilz: ausgeprägt mehlig-gurkig (Frischmehl); Risspilz: spermatisch/säuerlich-erdig - der Mehlgeruch ist das wichtigste Bestätigungsmerkmal für den Maipilz.','Beide an Wiesen, Hecken, Weg- und Waldrändern im Frühjahr; Habitat und Jahreszeit überschneiden sich, deshalb nur über Geruch und Sporenfarbe trennbar.','Maipilz: WEISSES Sporenpulver; Kegeliger Risspilz: tabak-/graubraunes Sporenpulver - eindeutiges Trennmerkmal.','Mai-Pilze nur ernten, wenn sie klar mehlig-gurkig riechen UND weisses Sporenpulver geben; jeder kegelige, radial aufgerissene Hut mit braunem Sporenstaub und unangenehmem Geruch ist ein Risspilz - sofort verwerfen.','123pilze, VAPKO, DGfM, GiftnotrufZentrale, Pilzmuseum.at'),
('calvatia_gigantea','amanita_phalloides','sehr_hoch_lebensgefahr','{"SCHNITTTEST (entscheidend): Riesenbovist hat komplett homogene, reinweisse Fruchtmasse ohne Innenstruktur. Beim jungen Knollenblätterpilz im Ei-Stadium sind im Längsschnitt bereits angelegte Lamellen, Stiel und Knolle als Schattenriss/''Embryo'' erkennbar = tödlich, sofort wegwerfen.","Innenfarbe: junger Bovist innen rein weiss und homogen. Jede gelbliche/grünliche Verfärbung oder ein dunklerer Pilz-Umriss im Schnitt = kein Bovist.","Aussenhülle: Bovist hat glatte, lederartig-geschlossene Aussenhaut ohne Volva. Knollenblätterpilz-Ei sitzt in einer häutigen Gesamthülle (Velum universale), aus der sich Volva und Stielbasis bilden.","Reifer Riesenbovist (>10 cm bis 50 cm) ist unverwechselbar — Verwechslung nur bei kleinen, kugeligen Jung-Exemplaren möglich. Faustregel: keinen ''Bovist'' kleiner als eine Handfläche ohne Schnittkontrolle essen."}','Riesenbovist: glatte, weisse bis cremefarbene, geschlossene Aussenhaut, kugelig, ohne Stiel/Hülle/Volva. Junger A. phalloides im Ei: weisse bis olivlich getönte häutige Gesamthülle, kugelig-eiförmig — äusserlich täuschend ähnlich, daher zählt nur der Schnitt.','Junger Bovist: angenehm pilzig-mild. A. phalloides reif: süsslich-honigartig bis unangenehm; im Ei-Stadium kaum riechbar, daher KEIN verlässliches Merkmal — niemals den Geruch als Freigabe werten.','Riesenbovist: Wiesen, Weiden, Gärten, Wegränder, nährstoffreiche Böden (kein Mykorrhizapilz). A. phalloides: Mykorrhizapilz im Laub-/Mischwald, v.a. bei Eiche und Buche. Überlappung an Waldrändern/Parks möglich — Standort allein schützt nicht.','Beim Bovist nicht relevant (keine Lamellen). A. phalloides: weisses Sporenpulver. Im Ei-Stadium beide nicht aussagekräftig — Unterscheidung allein über den Längsschnitt.','JEDEN kleinen, kugeligen ''Bovist'' VOR der Verwendung längs (oben nach unten) komplett durchschneiden. Nur wenn die Fläche durchgehend reinweiss und homogen ist — ohne jeden Stiel-/Lamellen-/Hut-Umriss — ist es ein Bovist. Bei kleinster Innenstruktur: tödlicher Knollenblätterpilz, ganzen Korb verwerfen.','https://de.wikipedia.org/wiki/Riesenbovist · https://de.wikipedia.org/wiki/Gr%C3%BCner_Knollenbl%C3%A4tterpilz · https://www.nps.gov/articles/species-spotlight-puffballs.htm · https://123pilzsuche.de/daten/details/Riesenbovist.htm'),
('calvatia_gigantea','amanita_verna','sehr_hoch_lebensgefahr','{"Junges A.-verna-Ei ist reinweiss und kugelig wie ein junger Bovist — Verwechslung dadurch real, v.a. weil verna auch in offeneren, wärmeren Lagen wächst.","SCHNITTTEST: homogene weisse Bovist-Masse vs. im Inneren bereits erkennbarer Stiel + Lamellen-Anlage + Knolle beim Amanita = tödlich.","A. verna besitzt häutige Volva und Stielbasis-Knolle; Bovist hat keine Volva, keinen Stiel.","Nur junges Kugelstadium verwechselbar; reifer Amanita mit Hut/Stiel/Ring ist eindeutig."}','Bovist: glatte weisse, geschlossene, strukturlose Aussenhaut, kugelig. A. verna jung: reinweisses Velum-Ei; reif komplett weiss mit häutiger Volva und Ring. Ei-Stadien äusserlich nahezu identisch.','A. verna: unauffällig bis leicht unangenehm. Junger Bovist: mild-pilzig. Kein verlässliches Trennmerkmal im Jungstadium.','A. verna: Mykorrhiza in (oft kalkigen) wärmebegünstigten Laub-/Mischwäldern bei Eiche/Edelkastanie, erscheint v.a. Frühjahr/Frühsommer, mediterran getönt (Südlagen). Riesenbovist: Grasland/Weiden, eher Spätsommer/Herbst. Saison- und Standortunterschiede vorhanden, ersetzen den Schnitttest aber nicht.','Bovist nicht relevant. A. verna: weisses Sporenpulver. Im Ei-Stadium für die Unterscheidung wertlos — Schnitt entscheidet.','Längsschnitt durch jeden kleinen weissen Kugelpilz: zeigt sich im weissen Fleisch der Schattenriss eines Pilzchens (Stiel + Hutanlage), ist es der tödliche Frühlings-Knollenblätterpilz — nicht der Bovist.','http://tintling.com/pilzbuch/arten/a/Amanita_verna.html · https://www.pilz-sammler.de/fungus/fruehlings-knollenblaetterpilz-amanita-verna-portraet/ · https://de.wikipedia.org/wiki/Riesenbovist · https://www.oekologie-seite.de/index.php?id=24&pid=5243'),
('calvatia_gigantea','gemeiner-fliegenpilz-var-alba','sehr_hoch_lebensgefahr','{"Junges A.-virosa-Ei ist REINWEISS und kugelig — optisch praktisch identisch mit einem jungen weissen Bovist. Genau deshalb ist der Schnitttest hier am wichtigsten.","SCHNITTTEST: Bovist = durchgehend homogene weisse Masse; A. virosa zeigt im Längsschnitt bereits angelegte Lamellen, Stiel und Knolle (Pilz-Umriss im Inneren) = tödlich.","A. virosa hat häutige, sackartige Volva an der Stielbasis und (später) einen Ring; der Bovist hat weder Volva noch Stiel noch Ring.","Verwechslung nur im jungen, kugeligen Stadium — sobald sich beim Amanita Hut/Stiel zeigen, ist die Unterscheidung trivial."}','Bovist: glatte geschlossene weisse Haut, rundlich, kein Stiel. A. virosa jung: reinweisses Ei in häutiger Hülle; ausgewachsen rein weiss mit spitz-kegeligem Hut, Ring und häutiger Volva. Im Ei-Stadium äusserlich kaum vom Bovist trennbar.','A. virosa reif: unangenehm, süsslich-widerlich (alte Fundstücke). Junger Bovist: mild-pilzig. Geruch im Jung-/Ei-Stadium unzuverlässig — nicht als Freigabe werten.','A. virosa: Mykorrhiza in saurem Nadel-/Mischwald, oft bei Fichte/Birke, eher kältere/montane Bergregionen. Riesenbovist: offenes Grasland, Weiden, Gärten. Geringere Standort-Überlappung als bei phalloides, aber Schnitttest bleibt Pflicht.','Bovist: keine Lamellen/kein Abwurf relevant. A. virosa: weisses Sporenpulver. Im verwechselbaren Ei-Stadium nicht nutzbar — nur Schnitt zählt.','Bei jedem kleinen weissen Kugelpilz Längsschnitt machen: ein im Schnitt sichtbarer weisser Pilz-''Embryo'' (Stiel + angelegter Hut) entlarvt den weissen Knollenblätterpilz. Nur strukturlos-weisse Masse = Bovist.','https://de.wikipedia.org/wiki/Riesenbovist · https://123pilzsuche.de/daten/details/KegelhuetigerKnollenblaetterpilz.htm · http://www.tintling.com/pilzbuch/arten/a/Amanita_virosa.html · https://biologie-seite.de/Biologie/Kegelh%C3%BCtiger_Knollenbl%C3%A4tterpilz'),
('calvatia_gigantea','scleroderma_citrinum','mittel','{"Verwechslung praktisch nur bei JUNGEN/kleinen Exemplaren: ausgewachsene Riesenboviste (15-50 cm) sind unverwechselbar, kleine junge aber kugelig und weisslich wie ein Bovist.","Riesenbovist im Schnitt jung gleichmaessig schneeweiss-watteartig weich; Kartoffelbovist im Schnitt schon jung dunkel/graustichig marmoriert.","Kartoffelbovist hat eine harte, dicke, zaehe Schale; Riesenbovist eine duenne, weiche, lederartige Huelle.","Kartoffelbovist riecht metallisch-unangenehm; junger Riesenbovist mild-pilzig."}','Riesenbovist gross, weiss, glatt und weichschalig; Kartoffelbovist klein (3-10 cm), gelbbraun, hart und grob-felderig schorfig.','Kartoffelbovist unangenehm metallisch; junger Riesenbovist mild-angenehm.','Riesenbovist auf naehrstoffreichen, gedüngten Wiesen, Weiden, Gaerten und Brennnessel-Saeumen; Kartoffelbovist auf saurem Waldboden mykorrhizal bei Baeumen.','Kartoffelbovist im Schnitt frueh braunschwarz-sporig; Riesenbovist jung innen rein weiss ohne dunkle Sporenmasse - nur in diesem Zustand essbar.','Nur gross-weisse Boviste essen, die im Laengsschnitt KOMPLETT schneeweiss und homogen sind. Jede dunkle Marmorierung, gelbliche Verfaerbung oder harte Schale bedeutet entweder ueberreif (ungeniessbar) oder Kartoffelbovist (giftig).','123pilze, DGfM, VAPKO, GiftnotrufZentrale'),
('champignon-de-paris','agaricus_xanthodermus','hoch','{"Stielbasis verfaerbt sich beim Anschneiden/Quetschen sofort intensiv chromgelb (leuchtend gelb) – essbare Champignons verfaerben hoechstens schwach gelblich am Hutrand, NIE kraeftig gelb am Stielgrund.","Riecht unangenehm nach Karbol/Phenol bzw. Tinte (am besten an der geriebenen Stielbasis oder beim Erhitzen wahrnehmbar) – essbare Champignons riechen pilzig, nussig oder nach Anis/Mandel.","Stielbasis zwiebelig verdickt OHNE lappige Haut/Volva; junger Hut oft mit grau-metallischem Schimmer in der Mitte; Lamellen jung rosa, im Alter dunkel schokoladenbraun.","Wuchsort identisch (Wiesen, Weiden, Parks, Waldraender, naehrstoffreiche Boeden), daher haeufige reale Verwechslung – der Standort hilft NICHT bei der Unterscheidung."}','Karbol-Champignon: Stielbasis verfaerbt sich beim Schnitt sofort chromgelb, Hutmitte oft graulich-metallisch, Stielgrund zwiebelig ohne lappige Haut. Kulturchampignon/Wiesenchampignon: Schnittflaeche bleibt weisslich bis leicht roetlich, kein gelber Stielgrund.','Karbol-Champignon riecht stechend nach Karbol/Phenol/Tinte (verstaerkt beim Erhitzen und beim Reiben der Stielbasis). Essbare Champignons riechen angenehm pilzig, nussig oder nach Anis.','Beide auf naehrstoffreichen Wiesen, Weiden, in Parks und an Waldraendern, Sommer bis Herbst – Standort hilft NICHT bei der Unterscheidung.','Beide schokoladenbraun – Sporenpulverfarbe ist hier KEIN Unterscheidungsmerkmal; auf Gelbverfaerbung und Geruch achten.','Stielbasis laengs anschneiden: kraeftig chromgelbes Verfaerben am Stielgrund + Karbol-/Tintengeruch = giftig, Pilz wegwerfen. Nicht oral testen. Folgen sind heftige Magen-Darm-Beschwerden (Uebelkeit, Erbrechen, Durchfall), in der Regel nicht lebensbedrohlich.','https://de.wikipedia.org/wiki/Karbol-Champignon · https://www.pilzkurse.com/karbol-champignon/ · https://www.awl.ch/pilze/vergleiche/champignon_vergleich/index.htm'),
('champignon-de-paris','amanita_phalloides','sehr_hoch_lebensgefahr','{"Lamellen stets rein weiss (auch beim Altpilz) – Champignon-Lamellen sind jung rosa, alt braun/schwarzbraun.","Stielgrund mit knolliger, von einer haeutigen lappigen weissen Scheide (Volva) umgebener Basis – beim Champignon fehlt die Volva voellig.","Sporenpulver weiss (Champignon braun).","Junge Exemplare gleichen einem weissen ''Ei'' und werden besonders leicht mit jungen geschlossenen Champignons verwechselt – immer aufschneiden, im Schnitt zeigt sich die angelegte weisse Lamellen-/Volvastruktur (innen einheitlich weiss-gruen, nie rosa)."}','Amanita phalloides: weiss bleibende Lamellen, haeutige weisse Volva am knolligen Stielgrund, Hut oliv-gruen bis (var. alba/jung) weiss. Champignon: rosa-braune Lamellen, keine Volva, Stielbasis ohne Scheide.','Amanita phalloides jung unauffaellig, alt modrig-suesslich nach Kunsthonig bis unangenehm. Champignon angenehm pilzig/nussig/anisartig.','Amanita phalloides als Mykorrhiza-Pilz im Laubwald (v.a. bei Eiche, Buche); Champignons auf offenem Kulturland, Wiesen und Weiden.','Amanita phalloides weiss, Champignon braun – weisser Sporenabdruck ist ein klares Warnsignal.','Verdaechtigen weissen Knopf/Ei laengs halbieren: Anlage von weissen Lamellen + Volva-Huelle am Grund = Knollenblaetterpilz, toedlich. Schon ca. 20 g sind lebensgefaehrlich – im Zweifel VAPKO-Pilzkontrolle / Tox Info Suisse 145.','https://de.wikipedia.org/wiki/Gr%C3%BCner_Knollenbl%C3%A4tterpilz · https://www.toxinfo.ch/customer/files/930/MB-Amanita-D-2024.pdf · https://www.awl.ch/pilze/vergleiche/champignon_vergleich/index.htm'),
('champignon-de-paris','gemeiner-fliegenpilz-var-alba','sehr_hoch_lebensgefahr','{"Lamellen bleiben in JEDEM Alter rein weiss – Champignon-Lamellen sind jung rosa und werden alt schokoladenbraun bis schwarzbraun (nie dauerhaft weiss).","Am Stielgrund eine knollig verdickte Basis mit haeutiger, lappiger weisser Scheide (Volva/Eihuelle) – Champignons haben NIE eine Volva.","Sporenpulver weiss; Champignon-Sporenpulver ist braun.","Wuchs meist im (Nadel-)Wald, oft bei Fichten – Champignons bevorzugen Wiesen, Weiden und Kulturland."}','Amanita virosa: rein weisser, oft kegeliger Hut, Lamellen bleiben weiss, knollige Stielbasis mit lappiger weisser Volva. Champignon: Lamellen rosa bis braun, keine Volva, Stielbasis nicht in haeutiger Scheide.','Amanita virosa unauffaellig bis suesslich-widerlich (verrottendes Fleisch). Champignon angenehm pilzig/nussig/anisartig.','Amanita virosa im Wald (oft Fichten/Nadelwald, saure Boeden); Champignons auf Wiesen, Weiden, Komposten, Kulturland.','Amanita virosa weiss, Champignon braun – Sporenabdruck ist ein zuverlaessiges Trennkriterium (weiss = Gefahr).','Pilz immer komplett samt Stielbasis aus dem Boden drehen und auf eine Volva (haeutige Scheide) am Knollengrund pruefen – Volva + weiss bleibende Lamellen + weisses Sporenpulver = toedlich, Finger weg. Bei Verdacht Tox Info Suisse 145 / VAPKO-Pilzkontrolle.','https://123pilzsuche.de/daten/details/KegelhuetigerKnollenblaetterpilz.htm · https://de.wikipedia.org/wiki/Kegelh%C3%BCtiger_Knollenbl%C3%A4tterpilz · https://www.toxinfo.ch/customer/files/930/MB-Amanita-D-2024.pdf · https://vapko.ch/phocadownload/public/TOUS/Giftpilzliste-Listedeschampignonstoxiques-plusmortels-2022.pdf'),
('chlorophyllum_rhacodes','lepiota_brunneoincarnata','sehr_hoch_lebensgefahr','{"Safran-Riesenschirmling ist gross: Hut 8-20 cm; Fleischrötlicher Schirmling klein: nur 2-5 cm","Safran-Riesenschirmling: Fleisch verfärbt sich beim Anschneiden/Reiben SAFRAN-/orangerot; Giftschirmling verfärbt sich nicht safranrot","Safran-Riesenschirmling: dicker verschiebbarer Ring, Stiel glatt (NICHT genattert); Giftschirmling: nur flüchtige faserige Ringzone, fleischbraun beschuppter Stiel","Fleischrötlicher Schirmling enthält tödliche Amatoxine; Safran-Riesenschirmling ist essbar (kann roh/ungenügend gegart Magen-Darm-Beschwerden machen)"}','Das beim Schnitt safran-/orangerot anlaufende Fleisch ist typisch für den essbaren Safran-Riesenschirmling und fehlt dem kleinen, fleischrosa-braunen Giftschirmling.','Safran-Riesenschirmling mild-pilzig; Giftschirmling süsslich-obstartig - Geruch ist kein sicheres Kriterium.','Safran-Riesenschirmling an nährstoffreichen Stellen, Komposten, Nadelwald, Gärten; Giftschirmling an sandig-grasigen, parkartigen Plätzen - Überschneidung möglich.','Beide mit weisslichem Sporenpulver - kein Trennmerkmal, deshalb Grösse, Safranreaktion des Fleischs und Ring prüfen.','Riesenschirmling nur ernten, wenn der Hut gross ist (über 8 cm) UND das Fleisch beim Reiben/Schneiden safran-orangerot anläuft - kleine Schirmlinge unter 8 cm grundsätzlich stehen lassen.','123pilze, VAPKO, DGfM, Wikipedia (Gemeiner Safranschirmling)'),
('clavariadelphus_truncatus','ramaria_formosa','gering','{"Abgestutzte Herkuleskeule: einfache, unverzweigte keulenfoermige Fruchtkoerper mit flach abgestutztem, oft eingedelltem Scheitel; Schoene Koralle reich verzweigt wie ein Strauch.","Herkuleskeule meist gelb-ocker bis orangebraun, einzeln/keulig; Schoene Koralle orange-lachs mit vielen gelben Astspitzen.","Herkuleskeule schmeckt mild bis suesslich; Schoene Koralle bitter und Magen-Darm-giftig.","Herkuleskeule waechst typisch in kalkholdem Nadelwald (oft Fichte/Tanne); Schoene Koralle eher im Laubwald.","Die unverzweigte Keulenform der Herkuleskeule schliesst eine Verwechslung bei genauem Hinsehen aus — eine Verwechslung passiert nur fluechtig bei jungen, koralligen Stadien."}','Herkuleskeule ist eine einzelne, oben abgestutzte Keule; die Schoene Koralle ist vielfach verzweigt — die Verzweigung ist das Schluesselmerkmal.','Beide unauffaellig bis schwach pilzig; Geruch nicht trennend.','Herkuleskeule vorwiegend in kalkreichem Nadelwald; Schoene Koralle eher im Laubwald — Standortunterschied, aber nicht absolut verlaesslich.','Herkuleskeule ockergelbliches Sporenpulver, Schoene Koralle ebenfalls ockerlich — kein praktisches Trennmerkmal.','Nur unverzweigte, oben abgestutzte Keulen ernten — sobald ein Pilz strauchig verzweigt und/oder bitter schmeckt, droht die giftige Schoene Koralle.','123pilze, DGfM, VAPKO, Wikipedia'),
('clavulina_coralloides','ramaria_formosa','gering','{"Kammkoralle (Clavulina coralloides/cristata): zierlich, weiss bis cremefarben, mit fein gezaehnten/kammartigen Astspitzen; Schoene Koralle deutlich groesser, fleischig und orange-lachsfarben.","Kammkoralle bleibt weisslich und verfaerbt sich nicht weinroetlich; Schoene Koralle verfaerbt bei Druck roetlich-braeunlich.","Kammkoralle mild und klein (wenige cm); Schoene Koralle bitter und massiger.","Schoene Koralle hat orange Aeste mit gelben Spitzen — die Farbe schliesst die weisse Kammkoralle aus.","Schoene Koralle ist Magen-Darm-giftig/abfuehrend; Verwechslung praktisch nur im juvenilen Stadium denkbar."}','Kammkoralle weisslich-zart mit kammartig gezaehnten Spitzen; Schoene Koralle gross, orange-lachsfarben mit gelben Astspitzen.','Beide mild-pilzig, kein trennender Geruch.','Beide am Waldboden; die Kammkoralle haeufig an Wegraendern und in Laub-/Nadelwald, die Schoene Koralle bevorzugt Laubwald — Habitat trennt nicht zuverlaessig.','Kammkoralle weisses Sporenpulver, Schoene Koralle ockergelbliches — Sporenfarbe trennt zuverlaessig.','Farbige (orange/gelbe) Korallen grundsaetzlich meiden; nur kleine, weisse, mild schmeckende Korallen sind anfaengertauglich — bitterer Geschmack oder roetliche Verfaerbung = giftig.','123pilze, DGfM, VAPKO, MykoWeb'),
('clitocybe_nebularis','ampulloclitocybe_clavipes','mittel','{"Beide haben eine keulig verdickte Stielbasis - das Schluesselmerkmal liegt im Habitus und der Hutfarbe: Nebelkappe deutlich groesser und fleischiger (Hut bis 20 cm), grau bereift; clavipes kleiner mit weissgrau-graubraunem Hut und dunklerer Mitte.","Nebelkappe mit elastischem Fleisch und Lamellen, die sich wie bei Roetelritterlingen leicht vom Hutfleisch abschieben lassen; clavipes-Lamellen weisslich und weit herablaufend.","Geruch trennt: Nebelkappe stark, eigenartig parfuemiert-suesslich; clavipes nur schwach obstartig-pilzig.","clavipes verursacht mit Alkohol ein Coprin-Syndrom; die Nebelkappe ist nur eingeschraenkt vertraeglich und fuer viele unbekoemmlich (gut durchgaren, nicht roh)."}','Grosse, grau bereifte, fleischige Nebelkappe vs. kleinerer, weissgrau-graubrauner clavipes; beide mit keuliger Basis.','Nebelkappe stark eigenartig-parfuemiert; clavipes schwach obstartig.','Nebelkappe oft in Hexenringen in Nadel-/Laubwald im Spaetherbst; clavipes aehnliche Standorte, kein sicheres Trennmerkmal.','Nebelkappe blass cremefarbenes Sporenpulver, clavipes weiss.','Kleine, weiche Trichterlinge mit keuliger, schwammiger Basis nicht mit Alkohol kombinieren; bei der Nebelkappe immer gut durchgaren.','pilzfinder.de, pilzbuch-pilzwelten.de, de.wikipedia.org'),
('clitocybe_nebularis','entoloma_sinuatum','hoch','{"Sporenpulver (SICHERSTES Merkmal): Riesenrötling fleischrosa bis rosabraun (Rötling-Gattung) — Nebelkappe weiss bis blass cremegelblich. Sporenabwurf auf weisses Papier trennt beide eindeutig.","Lamellen-Farbe im Alter: Riesenrötling-Lamellen jung weisslich/gelblich, im Alter durch die Sporen deutlich fleisch-ROSA — Nebelkappe-Lamellen bleiben weiss bis cremegelblich, NIE rosa.","Lamellenansatz: Nebelkappe-Lamellen laufen am Stiel kurz HERAB (trichterlingstypisch), gedrängt; Riesenrötling-Lamellen sind ausgebuchtet (sinuat) angewachsen, kurz, starr und stehen wenig gedrängt — NICHT herablaufend.","Geruch: Nebelkappe aufdringlich süsslich-würzig; Riesenrötling mehlig-ranzig mit unangenehm säuerlich-rettichartiger Note."}','Riesenrötling: kompakter, fleischiger, hellgrau bis lehmgelblich/elfenbeinfarbener Hut; Lamellen jung weisslich-gelblich, alt fleischrosa, kurz und ausgebuchtet (sinuat) angewachsen, nicht herablaufend. Nebelkappe: grosser (10-25 cm) nebelgrauer Hut mit weisslich-cremefarbenen, gedrängten und am Stiel kurz herablaufenden Lamellen.','Nebelkappe: aufdringlich süsslich-würzig (von vielen als unangenehm empfunden). Riesenrötling: mehlig-ranzig mit säuerlich-rettichartiger, unangenehmer Note.','Riesenrötling: kalkliebend, in Laub- und Mischwäldern (v.a. Buche, Eiche, Hainbuche) auf kalkhaltigem/lehmigem Boden, eher selten, Mai-November; wächst einzeln, in Gruppen ODER in Hexenringen. Nebelkappe: häufig und oft massenhaft, Laub- und Nadelwald, Spätherbst (Okt-Nov), bildet ebenfalls Reihen und Hexenringe. ACHTUNG: Hexenring-Wuchs taugt NICHT zur Unterscheidung — beide Arten zeigen ihn.','ENTSCHEIDEND: Riesenrötling fleischrosa bis rosabraun (Entoloma-Gattungsmerkmal). Nebelkappe weiss bis blass cremegelblich. Ein einfacher Sporenabwurf auf weisses Papier trennt die beiden sicher — das ist das zuverlässigste Merkmal.','Sporenabwurf ist Pflicht: rosa/fleischrosa Pulver = Rötling = NICHT essen. Nebelkappe wirft weisses bis blass-cremefarbenes Pulver ab und hat kurz herablaufende, gedrängte Lamellen. Verlass dich NICHT auf die Wuchsform — BEIDE Arten können Reihen und Hexenringe bilden, das ist KEIN Unterscheidungsmerkmal.','https://gizbonn.de/giftzentrale-bonn/pilze/giftige-pilze-und-ihre-doppelgaenger/nebelkappe-clitocybe-nebularis · https://de.wikipedia.org/wiki/Riesen-R%C3%B6tling · https://en.wikipedia.org/wiki/Entoloma_sinuatum · https://en.wikipedia.org/wiki/Clitocybe_nebularis · https://www.awl.ch/pilze/vergleiche/nebelkappe_vergleich/index.htm · http://tintling.com/pilzbuch/arten/e/Entoloma_sinuatum.html · https://fundkorb.de/pilze/entoloma-sinuatum-riesenr%C3%B6tling'),
('clitocybe_odora','clitocybe_fragrans','mittel','{"Gruener Anis-Trichterling ist deutlich blaugruen bis graugruen gefaerbt, kraeftiger im Habitus; fragrans ist blass graubraun/waessrig hell und kleiner, ohne Blau-/Gruentoene.","fragrans enthaelt Muscarin (Schwitzen, Speichel-/Traenenfluss, Pupillenverengung, Magen-Darm); der Gruene Anis-Trichterling ist gegart (als Wuerzpilz, in kleinen Mengen) essbar - roh giftig.","Beide riechen nach Anis; der Gruene riecht meist intensiver/anhaltender, bei fragrans verfliegt der Anisgeruch beim Trocknen rasch.","fragrans-Hut blass mit oft durchscheinend gerieftem Rand und dunklerer Mitte; odora gleichmaessiger blaugruen gefaerbt."}','Blaugruene Faerbung des Gruenen Anis-Trichterlings vs. blass waessrig-grauer, kleiner fragrans.','Beide nach Anis; odora kraeftiger/dauerhafter, fragrans schwaecher und fluechtiger.','Beide in Laub-/Nadel-/Mischwald; kein zuverlaessiges Trennmerkmal ueber das Habitat.','Beide weisses bis blass cremefarbenes Sporenpulver; nicht trennend.','Anisgeruch allein schuetzt nicht - kleine, blasse, waessrige Anis-Trichterlinge wegen Muscarin nie sammeln.','de.wikipedia.org (Gruener Anis-Trichterling; Langstieliger Duft-Trichterling), pilzbuch-pilzwelten.de'),
('clitopilus_prunulus','clitocybe_fragrans','mittel','{"Entscheidend ist das Sporenpulver: Mehlraesling rosa/lachsrosa, fragrans rein weiss - Sporenabwurf macht den Unterschied eindeutig.","Geruch trennt zusaetzlich: Mehlraesling stark nach frischem Mehl/Gurke, fragrans nach Anis.","Mehlraesling-Lamellen werden mit der Reife durch die Sporen rosa angehaucht und sind auffaellig weich; fragrans-Lamellen bleiben weisslich.","fragrans enthaelt Muscarin (Schwitzen, Speichelfluss, Miosis); der Mehlraesling ist ein guter Speisepilz - die Hauptgefahr ist jedoch die Verwechslung mit hochgiftigen weissen Trichterlingen."}','Mehlraesling cremeweiss mit spaeter rosa ueberhauchten, weichen Lamellen; fragrans blass grau, Lamellen bleiben weiss.','Mehlraesling intensiv mehlig-gurkig; fragrans nach Anis - klar unterschiedlich.','Beide im Wald und an Waldraendern; kein zuverlaessiges Trennmerkmal ueber das Habitat.','Mehlraesling rosa/lachsrosa, fragrans weiss - das sicherste Unterscheidungsmerkmal.','Immer Sporenabwurf machen UND Geruch separat pruefen: weissporige, nicht-mehlige Trichterlinge sind potenziell hochgiftig - im Zweifel komplett stehen lassen.','de.wikipedia.org (Mehl-Raesling), fundkorb.de, mycopedia.ch'),
('clitopilus_prunulus','clitocybe_phyllophila','hoch','{"Mehlräsling riecht stark und eindeutig nach frischem Mehl/Gurke; Bleiweißer Trichterling riecht muffig-süßlich bis parfümiert — der Geruch ist ein wichtiges Bestätigungsmerkmal.","Sporenpulver des Mehlräslings rosa (Lamellen im Alter rosa-rötlich überlaufend); beim Bleiweißen Trichterling weiß bis cremefarben — das Sporenpulver ist das SICHERSTE Trennmerkmal.","Lamellen des Mehlräslings deutlich herablaufend und leicht ablösbar; beim Bleiweißen Trichterling nur schwach/dezent herablaufend.","Der Bleiweiße Trichterling wird als muscarinverdächtig/giftig geführt (Schweiß-/Speichel-/Tränenfluss-Syndrom; Toxingehalt in der Literatur umstritten, daher konservativ als giftig behandeln) — der Mehlräsling ist gefahrlos essbar.","Hut des Bleiweißen Trichterlings glasig-firnisartig weiß bereift; Mehlräsling matt grauweiß, oft etwas verbogen."}','Beide klein und weiß; der Trichterling wirkt glasig/firnisartig bereift, der Mehlräsling matt-wildledrig — sicher trennt aber erst das Sporenpulver (rosa vs. weiß).','Mehlräsling = klarer Mehl-/Gurkengeruch; Bleiweißer Trichterling = muffig-süßlich/parfümiert. Der Mehlgeruch ist das wichtigste Bestätigungsmerkmal — allein aber nicht beweisend.','Beide in Laub-/Nadelwald; der Bleiweiße Trichterling oft truppweise in der Laub-/Nadelstreu, an Wegrändern und in Gärten.','Mehlräsling rosa, Bleiweißer Trichterling weiß/creme — der Sporenabwurf ist das sicherste Trennmerkmal. Bei Unsicherheit IMMER Sporenabwurf machen.','Mehlräsling nur bei eindeutigem Mehlgeruch UND rosa Sporenpulver verzehren — jeder weiß-sporige, parfümiert/muffig riechende weiße Trichterling ist muscarinverdächtig und bleibt stehen.','123pilze, pilzbuch-pilzwelten.de, mycopedia.ch, VAPKO, René Flammer (Giftpilze 2014)'),
('clitopilus_prunulus','hebeloma_crustuliniforme','mittel','{"Der Mehlräsling hat deutlich am Stiel herablaufende Lamellen und ROSA Sporenpulver; der Tränende Fälbling hat ausgerandet angewachsene Lamellen und rost-/braunolives Sporenpulver","Mehlräsling riecht intensiv mehlig (besonders an den Lamellen); Hebeloma crustuliniforme riecht rettichartig","Tränende Lamellen mit Tröpfchen und brauner Fleckung sind typisch für den Fälbling und fehlen beim Mehlräsling","Mehlräsling-Hut weiss-grau, oft etwas unregelmässig/verbogen; Fälbling-Hut tongrau-blass mit dunklerer Hutmitte"}','Mehlräsling: weiss-grau, herablaufende Lamellen; Fälbling: tongrau-blass, ausgerandete, tränende Lamellen.','Mehlräsling stark mehlig; Tränender Fälbling rettichartig.',NULL,'Mehlräsling rosa Sporenpulver vs. rost-/braunoliv beim Tränenden Fälbling — entscheidendes Merkmal.','Sporenpulver-Farbe sichert die Bestimmung: rosa + herablaufende Lamellen + Mehlgeruch = Mehlräsling, rostbraun + Rettichgeruch + tränende Lamellen = Giftpilz.','123pilze (Mehlräsling), fungiversum.de (Clitopilus prunulus), pilze.ch (Hebeloma)'),
('coprinopsis_atramentaria','coprinopsis_picacea','mittel','{"Junge Spechttintlinge koennen mit dem Faltentintling verwechselt werden: Spechttintling traegt weisse, abwischbare Velumschuppen auf dunklem Grund (schwarz-weisses Muster); Faltentintling ist einheitlich grau bis graubraun mit laengsfaltigem/gefurchtem Hut ohne weisse Flecken.","Spechttintling riecht muffig-teerig und ist ungeniessbar; Faltentintling ist (nur ohne Alkohol) bedingt essbar.","Spechttintling schlanker und hoeher mit zerbrechlichem Stiel; Faltentintling gedrungener und meist bueschelig wachsend.","Achtung: Der Faltentintling enthaelt Coprin und ist mit Alkohol selbst giftig - kein ''sicherer'' Speisepilz."}','Schwarz-weiss gefleckter Spechttintling vs. einheitlich grauer, laengsfaltiger Faltentintling ohne weisse Velumflecken.','Spechttintling muffig-teerig; Faltentintling unauffaellig pilzig.','Spechttintling einzeln in humus-/kalkreichen Buchen-/Laubwaeldern; Faltentintling bueschelig an Stuempfen, Wegraendern und in Gaerten.','Beide schwarzes, zerfliessendes Sporenpulver; nicht trennend.','Weisse, abwischbare Velumflecken auf dunklem Hut kennzeichnen den ungeniessbaren Spechttintling; und Faltentintlinge nie mit Alkohol verzehren.','pilzbuch-pilzwelten.de (Spechttintling / Faltentintling), awl.ch'),
('cortinarius_praestans','cortinarius_traganus','hoch','{"C. praestans ist gross und kräftig mit runzelig-violettbraunem Hut, weisslichen Schleierschuppen und blass tonfarbenen, später rostbraunen Lamellen; C. traganus ist durchgehend lila gefärbt und schlanker.","Geruch: C. praestans mild/angenehm; C. traganus böckig-ziegenartig unangenehm.","C. traganus hat safran-ocker bis lila Fleischtöne und keulig verdickten Stiel; C. praestans festes weissliches Fleisch.","Beide sind Cortinarien mit rostbraunem Sporenpulver – die Bestimmung essbarer Cortinarien ist NUR Experten erlaubt."}','C. praestans gross, runzelig-violettbrauner Hut mit weisslichem Schleier und Schuppen; C. traganus kleiner, durchgehend lila mit keuligem Stiel.','C. praestans mild; C. traganus widerlich böckig – der Geruch warnt vor traganus.','C. praestans in kalkreichem Laubwald (Buche/Eiche); C. traganus eher in saurem Nadelwald.','Beide rostbraun – das Sporenpulver trennt hier NICHT; nur Habitus, Geruch und Lamellenfarbe unterscheiden.','Cortinarien generell nur durch erfahrene Pilzkontrolleure (VAPKO) freigeben lassen – die Gattung enthält tödliche Arten; als Anfänger ALLE Schleierlinge stehen lassen.','VAPKO, 123pilze, pilzbuch-pilzwelten.de, pilzkurse.com – Cortinarius praestans / traganus'),
('cuphophyllus_pratensis','hygrocybe_conica','gering','{"Kegeliger Saftling: spitzkegeliger, lebhaft gelb-orange-roter Hut, der bei Berührung/Alter SCHWARZ anläuft (ganzer Fruchtkörper schwärzend) – charakteristisches Schwärzen","Wiesen-Ellerling: stumpf-gewölbter bis verflachender, blass ocker-orange/aprikosenfarbener Hut, schwärzt NICHT","Wiesen-Ellerling mit weit herablaufenden, entfernten, dicklichen wachsartigen Lamellen; Kegeliger Saftling mit eher freien/angehefteten Lamellen","Kegeliger Saftling gilt als schwach giftig/magen-darm-verdächtig – Wiesen-Ellerling ist guter Speisepilz"}','Das namensgebende Schwärzen (Hut/Stiel werden bei Druck oder Alter tintenschwarz) kennzeichnet den Kegeligen Saftling; der Wiesen-Ellerling bleibt blass aprikosenfarben und schwärzt nie.','Beide weitgehend geruchlos – kein Trennmerkmal.','Beide auf ungedüngten Wiesen/Magerrasen – Habitat trennt nicht; daher auf Form und Schwärzen achten.','Beide mit weissem Sporenpulver – kein Trennmerkmal.','Drucktest: schwärzt der Fruchtkörper an Berührungsstellen oder ist der Hut spitzkegelig und feuerfarben, liegen lassen (Kegeliger Saftling). Nur stumpfe, blass-orange, nicht schwärzende Ellerlinge mit herablaufenden Wachslamellen sammeln.','123pilze.de (Kegeliger Saftling/Wiesen-Ellerling), fundkorb.de (Hygrocybe conica), DGfM'),
('cuphophyllus_virgineus','hygrocybe_conica','gering','{"Kegeliger Saftling: spitzkegeliger, kräftig gelb/orange/rot gefärbter Hut, schwärzt bei Berührung und im Alter komplett","Jungfern-Ellerling: kleiner, weisslich-elfenbeinfarbener, stumpf gewölbter Hut, schwärzt NICHT","Jungfern-Ellerling mit weit herablaufenden, entfernten, weissen Wachslamellen; Kegeliger Saftling lebhaft farbig und schwärzend","Kegeliger Saftling schwach giftig/magen-darm-verdächtig – Jungfern-Ellerling milder Speisepilz"}','Der Jungfern-Ellerling ist klein, weiss und schwärzt nicht; der Kegelige Saftling ist spitzkegelig, feuerfarben und läuft schwarz an.','Beide nahezu geruchlos – kein Trennmerkmal.','Beide auf mageren Wiesen/Rasen – Standort trennt nicht; Farbe und Schwärzen sind ausschlaggebend.','Beide mit weissem Sporenpulver – kein Trennmerkmal.','Schwärzen + spitzkegelige Feuerfarbe = Kegeliger Saftling (liegen lassen). Nur weisse, nicht schwärzende Ellerlinge mit herablaufenden Lamellen verwenden.','123pilze.de (Kegeliger Saftling/Jungfern-Ellerling), fundkorb.de (Hygrocybe conica), DGfM'),
('cyclocybe_aegerita','gymnopilus_junonius','mittel','{"Sporenpulver: Pioppino tabak-/olivbraun, G. junonius rein rostbraun; Geschmack des Pioppino mild, G. junonius extrem bitter.","Hutfarbe: Pioppino hell ocker- bis dunkelbraun, oft rissig-felderig; G. junonius leuchtend orange-rostgelb.","Stiel: Pioppino zäh-faserig, hell mit häutigem Ring; G. junonius dicker, faserig, orange-tönig.","Pioppino wächst meist an Laubholz (v.a. Pappel); G. junonius häufiger an Nadel- und Laubholz-Stümpfen sowie Stammbasen."}','Pioppino hat einen helleren, oft rissig gefelderten braunen Hut und blassere Lamellen; G. junonius ist gleichmässig leuchtend orange mit rostbraunen Lamellen.','Pioppino angenehm würzig; G. junonius mehlig-ranzig mit stark bitterem Geschmack.','Pioppino bevorzugt Laubholz (v.a. Pappel, oft kultiviert); G. junonius an Stümpfen und Stammbasen von Laub- und Nadelholz.','Pioppino: tabakbraunes Sporenpulver. G. junonius: rostbraunes Sporenpulver – ähnlich, daher zusätzlich Bitterkeit/Hutfarbe prüfen.','Geschmacksprobe (ausspucken): stark bitter = Flämmling = nicht essen. Pioppino ist mild und meist an Laubholz.','123pilze, mycopedia.ch, Wikipedia – Cyclocybe aegerita / Gymnopilus junonius'),
('disciotis_venosa','gyromitra_gigas','hoch','{"Aderbecherling: schüssel-/becherförmig, flach ausgebreitet, Innenseite braun mit aderig-runzeliger Oberfläche, kurzer/fehlender Stiel, charakteristischer Chlorgeruch","Riesenlorchel: aufrechter, knollig-gehirnartig gewundener Hut auf deutlichem dickem Stiel, kein becherförmiger Bau","Aderbecherling nur gut gegart essbar (roh unverträglich); Riesenlorchel selbst kaum gyromitrinhaltig, aber von tödlichen Lorchel-Arten kaum zu trennen – daher meiden","Aderbecherling-Oberfläche aderig-gerippt aber flach; Lorchel-Oberfläche stark dreidimensional aufgewölbt"}','Aderbecherling ist eine flache, am Boden aufliegende braune Schüssel mit aderiger Innenseite; die Riesenlorchel ein aufrechter gehirnförmiger Hut.','Aderbecherling riecht deutlich nach Chlor (typisch, besonders an Bruchstellen); die Riesenlorchel riecht unspezifisch pilzig.','Aderbecherling im Frühling auf feuchten, kalkreichen Böden/Auwald; Riesenlorchel als Holzsaprobiont – Erscheinungszeit überschneidet sich.','Beide Schlauchpilze mit hellem Sporenpulver – kein Trennmerkmal.','Der Chlorgeruch und die flach-becherige Form kennzeichnen den Aderbecherling. Alles aufrecht Gehirnförmige stehen lassen (Lorchel-Verwechslungsgefahr) und beide Arten nur durchgegart verzehren.','123pilze.de (Aderbecherling/Riesenlorchel), de.wikipedia.org/wiki/Aderiger_Morchelbecherling, DGfM'),
('eierschwamm','cortinarius_orellanus','sehr_hoch_lebensgefahr','{"Pfifferling hat LEISTEN, Raukopf hat ECHTE Lamellen","Pfifferling ist eigelb-aprikose, Raukopf orange-rotbraun"}','Pfifferling: dottergelb mit Trichterform und Leisten. Raukopf: rotbraun-orange mit echten Lamellen.','Pfifferling: aprikose-fruchtig. Raukopf: rettich-artig.','Pfifferling: Mai-Okt Nadelwald. Raukopf: Sep-Nov Laubwald.','Pfifferling: blassgelb. Raukopf: rostbraun.','GOLDREGEL: Hut umdrehen — ECHTE Lamellen oder LEISTEN? Bei Zweifel VAPKO!','VAPKO Schweiz'),
('eierschwamm','hygrophoropsis_aurantiaca','mittel','{"Echter Pfifferling: stumpfe, fest verwachsene Leisten, fest-fleischig","Falscher Pfifferling: echte dünne, stark gegabelte, leicht ablösbare Lamellen, weich"}','Leisten (Pfifferling) vs. echte Lamellen (falscher); Konsistenz fest vs. weich.','Pfifferling fruchtig (Aprikose); falscher unspezifisch/moderig','Pfifferling Laub-/Nadelwald; falscher v.a. Nadelstreu/Totholz','beide blass','Falscher Pfifferling ist schwach giftig (Magen-Darm). Stumpfe Leisten vs. scharfe ablösbare Lamellen prüfen. Bei kräftig orangerot zusätzlich Ölbaumpilz (giftig) ausschliessen.','123pilze.de / pilzbuch-pilzwelten.de'),
('eierschwamm','omphalotus_olearius','hoch','{"Oelbaumtrichterling hat echte, scharfkantige, gedraengte Lamellen; der Pfifferling hat KEINE echten Lamellen, sondern nur stumpfe, gabelige, dicke Leisten (verdickte Aderfalten), die weit am Stiel herablaufen","Oelbaumtrichterling waechst bueschelig direkt an/auf Holz und Wurzeln (Eiche, Olive, Edelkastanie, Stuempfe); echter Pfifferling waechst einzeln bis verstreut aus dem Waldboden (Mykorrhiza), nie bueschelig an Holz","Farbe Oelbaumtrichterling kraeftig orange bis orangerot/braunorange; Pfifferling blass dotter- bis eigelb, gleichmaessig","Lamellen des frischen Oelbaumtrichterlings leuchten im Dunkeln schwach gruenlich (Biolumineszenz) - der Pfifferling nie","Pfifferling-Fleisch ist faserig-zaeh, durchgehend blassgelb und reisst faserig; Oelbaumtrichterling-Fleisch weicher, gegen die Basis orange-braun"}','Oelbaumtrichterling kraeftig orange mit echten, duennen, gedraengten Lamellen und trichterig vertieftem Hut, bueschelig an Holz; Pfifferling blassgelb mit dicklichen, gabeligen, herablaufenden Leisten, einzeln am Boden.','Pfifferling riecht angenehm fruchtig nach Aprikose; der Oelbaumtrichterling riecht unauffaellig bis leicht unangenehm, ohne Aprikosennote.','Oelbaumtrichterling bueschelig an Laubholz/Stuempfen/Wurzeln (waermeliebend, in der Schweiz selten und nur in milden Lagen); Pfifferling einzeln aus dem Boden im Nadel- und Laubwald, in der Schweiz haeufig.','Beide weisslich bis blass cremefarben - das Sporenpulver trennt sie NICHT. Entscheidend sind echte Lamellen vs. dicke Leisten und Wuchsform (Holz vs. Boden).','Echte, scharfkantige Lamellen + buescheliges Wachstum direkt an Holz = NIEMALS ein Pfifferling, egal wie gelb. Ein Pfifferling hat nur dicke, gabelige, herablaufende Leisten und steht einzeln aus dem Boden.','123pilze (Oelbaumtrichterling), AWL.ch (Pfifferling), Wikipedia (Dunkler Oelbaumtrichterling), DGfM'),
('flockenstieliger_hexenpilz','rubroboletus_satanas','hoch','{"Flockenstieliger Hexenroehrling hat KEIN Stielnetz, sondern rote Floeckchen/Punkte auf gelbem Stiel; Satansroehrling hat ein deutliches rotes Stielnetz - das ist das wichtigste Trennmerkmal.","Flockenstieliger Hexenroehrling blaut sofort und intensiv schwarzblau; Satansroehrling nur schwach.","Flockenstieliger Hexenroehrling hat braunen bis dunkelbraun-ziegelroten Hut; Satansroehrling jung hellen, kalkweiss-graugruenen Hut.","Satansroehrling riecht alt nach Aas; der Flockenstielige riecht angenehm pilzig.","Beide haben rote Poren - der Flockenstielige ist nur gut durcherhitzt essbar (roh giftig), der Satansroehrling bleibt giftig."}','Stiel mit roten Floeckchen (KEIN Netz) und sofort intensives Schwarzblauen beim Flockenstieligen vs. rotes Stielnetz und schwaches Blauen beim Satansroehrling.','Satansroehrling alt nach Aas, Flockenstieliger angenehm pilzig.','Flockenstieliger waechst auch in sauren Nadelwaeldern; Satansroehrling streng auf warmen Kalk-Laubwald beschraenkt.','Beide olivbraun - nicht trennend.','Flockiger Stiel ohne Netz spricht fuer den essbaren Hexenroehrling; ein rotes Netz am Stiel ist ein Warnsignal Richtung Satansroehrling - im Zweifel verwerfen und durcherhitzen ist Pflicht.','123pilze, AWL.ch (Vergleich rotporige Roehrlinge), Wikipedia (Flockenstieliger Hexen-Roehrling), DGfM'),
('gymnopus_dryophilus','gymnopus_peronatus','gering','{"Brennender Rübling: Geschmack scharf-brennend pfeffrig (Geschmacksprobe brennt nach kurzer Zeit), Stielbasis striegelig-filzig weissfilzig, Fleisch zäh-lederig","Waldfreund-Rübling: Geschmack mild, Stiel kahl/glatt ohne striegelige Basis, Stiel oft gelblich-rötlich","Brennender Rübling oft truppweise in dichter Laubstreu, erscheint länger in den Herbst hinein; Waldfreund-Rübling Hut hygrophan rotbraun verblassend","Brennender Rübling gilt als ungeniessbar bis schwach giftig (scharf, magenreizend, Hinweise auf Blausäureverbindungen) – Waldfreund-Rübling ist mild essbar"}','Brennender Rübling wirkt zäher, lederbraun-gelbbraun, mit deutlich striegelig-filziger Stielbasis; der Waldfreund-Rübling ist zarter mit kahlem Stiel.','Beide eher unspezifisch pilzig; der Brennende Rübling riecht beim Reiben oft essigartig-säuerlich und schmeckt brennend scharf – der scharfe Geschmack (Kostprobe, ausspucken) ist das entscheidende Trennmerkmal.','Beide in Laub-/Nadelwald-Streu, oft truppweise – Habitat trennt nicht; der Brennende Rübling bevorzugt trockenere Streulagen und erscheint länger in den Herbst hinein.','Beide mit weissem bis cremefarbenem Sporenpulver – kein Trennmerkmal.','Kleine Geschmacksprobe (kauen, NICHT schlucken, ausspucken): brennt es nach kurzer Zeit pfeffrig-scharf, ist es der giftverdächtige Brennende Rübling. Kleine braune Streupilze nur sammeln, wenn man sie eindeutig kennt.','123pilze.de (Brennender Rübling/Waldfreund-Rübling), de.wikipedia.org, tintling.com, DGfM'),
('hallimasch','cortinarius_orellanus','hoch','{"Hallimasch hat Ring + parasitär an Baum Raukopf einzeln","Sporenpulver: Hallimasch weiss Raukopf rostbraun"}','Hallimasch: honiggelb mit Ring Büschelweise. Raukopf: orange-rotbraun einzeln.','Hallimasch: säuerlich. Raukopf: rettich-artig.','Hallimasch: Baumstümpfe Wurzeln. Raukopf: Boden Laubwald.','Hallimasch: weiss. Raukopf: rostbraun.','Bei jungen Pilzen besonders aufpassen. Sporenabwurf machen.','VAPKO Schweiz'),
('hallimasch','gymnopilus_junonius','mittel','{"Sporenpulver: Hallimasch WEISS bis cremefarben, G. junonius rostbraun – Sporenabwurf trennt sicher.","Lamellen: Hallimasch weisslich bis blass fleischrosa, am Stiel herablaufend; G. junonius jung gelb, später rostbraun.","Geschmack: G. junonius extrem bitter; Hallimasch (roh giftig!) mild bis leicht herb, muss durchgegart werden.","Hallimasch hat oft dunkle Schüppchen auf hellem Hut und einen weissen Ring; G. junonius gleichmässig orange-rostgelb."}','Hallimasch honig- bis braunhütig mit dunklen Schüppchen und weissem Ring; G. junonius leuchtend orange-rostgelb mit rostbraunen Lamellen.','Hallimasch mild-pilzig; G. junonius mehlig-ranzig und sehr bitter im Geschmack.','Beide büschelig an/um Holz und Wurzeln; Hallimasch parasitisch an lebenden Bäumen und Stümpfen, G. junonius an Stümpfen und Stammbasen.','Hallimasch: weisses Sporenpulver. G. junonius: rostbraunes Sporenpulver – das ist das entscheidende Trennmerkmal.','Sporenabwurf machen: weiss = mögliche essbare Art (Hallimasch nur gut durchgegart, roh giftig!), rostbraun = Flämmling = wegwerfen. Zusätzlich Geschmacksprobe: bitter = giftig.','Wikipedia – Beringter Flämmling (weisses Hallimasch-Sporenpulver als Unterscheidung), 123pilze'),
('hallimasch','hypholoma_fasciculare','mittel','{"Hallimasch: Lamellen weisslich bis hell fleischbräunlich, im Alter hell-rostbraun; Schwefelkopf: Lamellen schwefelgelb-grünlich bis grünschwärzlich","Hallimasch: deutlicher weisslicher, flockig-watteiger Ring am Stiel; Schwefelkopf: nur flüchtige Ringzone, kein echter Ring","Hallimasch: Hut mit feinen dunklen, meist abwischbaren Schüppchen; Schwefelkopf: Hut glatt, schwefel- bis ockergelb","Hallimasch: roh giftig, aber gut durchgegart essbar und mild (Kochwasser wegschütten); Schwefelkopf: roh wie gegart bitter und giftig"}','Der schwefelgelb-grünliche Lamellenton des Schwefelkopfs unterscheidet ihn klar vom hell-fleischfarben lamelligen, fein schuppig-behuteten Hallimasch mit echtem weisslichem Ring.','Geschmacksprobe trennt nur Schwefelkopf ab: Hallimasch mild, Schwefelkopf intensiv bitter (Kostprobe nur kauen, nie schlucken).','Beide büschelig an Holz/Stümpfen; Habitat trennt sie nicht, daher zwingend Lamellenfarbe, Ring und Sporenpulverfarbe prüfen.','Hallimasch: WEISSES Sporenpulver; Grünblättriger Schwefelkopf: dunkel violett-/purpurbraunes Sporenpulver - eindeutiges, sicheres Trennmerkmal.','Hallimasch hat einen echten weisslichen Ring und WEISSES Sporenpulver - fehlt der echte Ring oder ist das Sporenpulver dunkel violettbraun und der Geschmack bitter, ist es der Schwefelkopf. Hallimasch immer gut durchgaren, Kochwasser wegschütten.','123pilze, GiftnotrufZentrale (GIZ Bonn), DGfM, Stadt Wien Konsumentenschutz, AWL.ch'),
('hallimasch','pholiota_squarrosa','mittel','{"Sparriger Schüppling: trockene, abstehende (sparrige), grobe braune Schuppen auf Hut UND Stiel; Hallimasch hat nur feine, vergängliche, anliegende Flöckchen auf dem Hut","Sporenpulver: Schüppling rostbraun → Lamellen verfärben braun; Hallimasch weiss → Lamellen bleiben hell/cremeweiss","Hallimasch hat einen dicken, häutigen weissen Ring; der Ring des Schüpplings ist sparrig-faserig/wollig und undeutlich","Sparriger Schüppling riecht aufdringlich würzig-rettich-/lauchartig, Hallimasch eher pilzig-mild","Geschmack des Schüpplings bitter/unangenehm (Kostprobe ausspucken, nie roh schlucken)"}','Grobe abstehende sparrige Schuppen auf Hut und Stiel beim Schüppling statt der feinen, abwischbaren, vergänglichen Flöckchen des Hallimasch.','Sparriger Schüppling riecht aufdringlich rettich-/lauchartig, Hallimasch mild pilzig.','Beide büschelig an Laub-/Nadelholz und Stümpfen, gleiche Saison Herbst — Standort taugt NICHT zur Unterscheidung.','Sparriger Schüppling rostbraunes Sporenpulver, Hallimasch weisses — Lamellenfarbe im Alter beachten (Sporenabwurf machen).','Sporenpulverfarbe entscheidet: rostbraun = niemals Hallimasch, Finger weg. Büschelpilze an Holz immer einzeln durchprüfen, nie pauschal als Hallimasch ernten. Hallimasch zudem nur gut durchgegart geniessbar.','123pilze, AWL.ch, Wikipedia (Sparriger Schüppling), Toxinfo'),
('hypholoma_capnoides','hypholoma_lateritium','mittel','{"Graublättriger Schwefelkopf (essbar) hat graue bis graublaue Lamellen; der Ziegelrote hat olivgraue bis oliv-graubraune Lamellen (NICHT grünlich-gelb — das wäre der tödlich-giftige Grünblättrige Schwefelkopf, Hypholoma fasciculare)","Hutfarbe des essbaren heller honiggelb bis ockerbraun, beim Ziegelroten ziegelrot mit hellerem Rand","Geschmack des essbaren mild, der Ziegelrote bitter","Graublättriger wächst auf Nadelholz (Fichte/Kiefer), Ziegelroter bevorzugt Laubholz (Buche/Eiche)","Sporenpulver bei beiden purpurbraun — kein Unterscheidungsmerkmal; daher auf Lamellen-Farbton, Substrat und Geschmack achten"}','Essbarer Graublättriger mit grau/graublauen Lamellen und honig-ockerfarbenem Hut; Ziegelroter mit olivgrau bis oliv-graubraunen Lamellen und ziegelrotem Hutzentrum. Achtung: grünlich-gelbe Lamellen bedeuten den tödlichen Grünblättrigen Schwefelkopf, nicht den Ziegelroten.','Beide pilzig-mild im Geruch; der Ziegelrote schmeckt jedoch deutlich bitter (Kostprobe ausspucken).','Graublättriger an Nadelholzstümpfen, Ziegelroter überwiegend an Laubholz (Buche, Eiche).','Bei beiden purpurbraun bis violettbraun — als Trennmerkmal ungeeignet.','Schwefelköpfe nie ohne Geschmacksprobe (ausspucken) bestimmen: bitter = stehen lassen. Nadelholz-Substrat + milder Geschmack sprechen für den essbaren Graublättrigen. Bei grünlich-gelben Lamellen handelt es sich um den tödlichen Grünblättrigen Schwefelkopf.','123pilze, DGfM, VAPKO'),
('infundibulicybe_geotropa','ampulloclitocybe_clavipes','mittel','{"Moenchskopf ist viel groesser und kraeftiger (Hut bis ca. 20 cm) mit fest-zaehem, trockenem Fleisch und festem, NICHT schwammigem Stiel; clavipes klein mit weicher, waessrig-schwammiger keuliger Stielbasis.","Moenchskopf hat einen typisch zentralen flachen Buckel im sonst vertieften Hut und cremeweiss-ockerliche Faerbung; clavipes weissgrau-graubraun mit dunklerer Mitte.","Moenchskopf waechst meist in grossen Hexenringen/Reihen an Waldraendern und grasigen Standorten; clavipes eher zerstreut im Wald.","clavipes mit Alkohol giftig (Coprin-Syndrom); der Moenchskopf ist gegart ein guter Speisepilz."}','Grosser, cremeweiss-ockerlicher Moenchskopf mit zentralem Buckel und festem Stiel vs. kleiner weissgrau-graubrauner clavipes mit weicher Keulenbasis.','Moenchskopf angenehm wuerzig-suesslich; clavipes schwach obstartig.','Moenchskopf in Hexenringen auf grasigen Standorten/Waldraendern; clavipes im Misch- und Nadelwald.','Beide weisses bis cremefarbenes Sporenpulver; nicht trennend.','Bei kleinen, weichen Trichterlingen mit schwammig-keuligem Stiel grundsaetzlich Finger weg und nie mit Alkohol kombinieren.','123pilze, pilzbuch-pilzwelten.de'),
('infundibulicybe_geotropa','clitocybe_dealbata','hoch','{"Grösse/Fleisch: Feldtrichterling nur 2-5 cm Hut, dünnfleischig (wenige mm); Mönchskopf 12-25 cm, dick-fleischig und mit deutlich fühlbarem zentralem Buckel/Warze in der Hutmitte (Fingertest) - der Buckel fehlt dem Feldtrichterling immer.","Beide weiss/cremefarben & trichterig mit herablaufenden Lamellen und WEISSEM Sporenpulver - die Hutfarbe und das Sporenpulver helfen NICHT, nur Grösse + Fleischdicke + Buckel + Standort trennen sicher.","Standort/Saison: Feldtrichterling auf Wiesen, Weiden, Wegrändern, Rasen, Parks (Frühsommer-Spätherbst, oft in Hexenringen); Mönchskopf in Laub-/Nadelwald, an Waldrändern und auf Waldwiesen auf feuchtem Kalkboden (Spätsommer-Herbst, ebenfalls Hexenringe - Standort allein reicht NICHT).","Stiel: Mönchskopf hat kräftigen, oft keulig verdickten Stiel (2-4 cm dick, 8-15 cm lang); Feldtrichterling zierlich und dünn."}','Mönchskopf: 12-25 cm, creme/lederfarben bis rötlich-ocker im Alter, zentraler fühlbarer Buckel, kräftig-keuliger Stiel. Feldtrichterling: nur 2-5 cm, kreideweiss bereift, niedergedrückt/eben ohne Buckel, dünner zierlicher Stiel.','Mönchskopf riecht aromatisch süsslich mit deutlicher Bittermandel-Note; Feldtrichterling unbedeutend bis schwach mehlig. Achtung: Geruch ist ein UNTERSTÜTZENDES Merkmal, niemals das alleinige Sicherheitskriterium - immer mit Grösse/Buckel/Fleischdicke kombinieren.','Feldtrichterling: offenes Grasland, Wiesen, Weiden, Rasen, Wegränder, Parks. Mönchskopf: Laub- und Nadelwald, Waldränder, Waldwiesen auf feuchtem Kalkboden. Beide können Hexenringe bilden - der Standort-Typ (Wald vs. offenes Gras) ist relevanter als das Ringe-Wachstum.','Beide WEISS - das Sporenpulver hilft hier NICHT zur Unterscheidung. Trennung erfolgt über Grösse, Fleischdicke, Hutbuckel und Stieldicke.','Goldene Regel: KLEINE weisse Trichterlinge (unter ca. 6 cm, dünnfleischig, ohne fühlbaren Hutbuckel) NIE essen - sie enthalten Muscarin und sind als Gruppe lebensgefährlich verwechselbar. Nur den grossen (12-25 cm), dick-fleischigen Mönchskopf mit eindeutig fühlbarem zentralem Hutbuckel und kräftigem Stiel nehmen. Hexenringe und weisses Sporenpulver haben BEIDE - sie taugen NICHT zur Unterscheidung.','https://de.wikipedia.org/wiki/M%C3%B6nchskopf · https://de.wikipedia.org/wiki/Feldtrichterling · https://www.pilzfinder.de/pilz/moenchskopf.html · https://naturlexikon-bayern.de/lexikon/pflanzen/pilze/moenchskopf/ · https://123pilzsuche.de/daten/details/MoenchskopfEssbar1004.htm'),
('infundibulicybe_geotropa','clitocybe_rivulosa','hoch','{"Grösse: Rinnigbereifter Trichterling nur bis ca. 4-5 cm Hut, kreideweiss bereift, niedergedrückt/eingedellt ohne Buckel; Mönchskopf 12-25 cm, dick-fleischig, mit deutlich fühlbarem zentralem Buckel.","Beide weisslich-trichterig mit herablaufenden Lamellen und WEISSEM Sporenpulver - nur Grösse, Fleischdicke und Hutbuckel trennen sie sicher, Farbe und Sporenpulver NICHT.","Hochgiftig durch Muscarin (Muscarin-Syndrom: starker Speichel-/Schweiss-/Tränenfluss innert 15-30 Min, bei schweren Fällen Kreislaufkollaps), oft auf denselben Wiesen-/Wegrand-/Dünen-Standorten in Trupps oder Hexenringen.","Stiel zierlich/dünn beim Gifttrichterling vs. kräftig-keulig (2-4 cm dick) beim Mönchskopf."}','Rinnigbereifter Trichterling: bis 4-5 cm, kreideweiss bereift, niedergedrückt ohne Buckel, dünner Stiel. Mönchskopf: 12-25 cm, creme/lederbraun, mit zentralem Buckel, dicker keuliger Stiel.','Mönchskopf aromatisch süsslich mit Bittermandel-Note; Rinnigbereifter Trichterling unauffällig bis schwach. Geruch nur als Zusatzmerkmal verwenden, nie allein.','Rinnigbereifter Trichterling: Rasen, Wiesen, Wegränder, Dünen, Böschungen, Parks (im Gras, in Trupps/Hexenringen). Mönchskopf: Laub-/Nadelwald auf Kalkboden, Waldränder, Waldwiesen. Wald vs. offenes Grasland ist das relevante Standort-Kriterium.','Beide WEISS - keine Unterscheidung über die Sporenfarbe möglich; Grösse + Fleischdicke + Standort + Buckel entscheiden.','Jeder kleine, kreideweiss bereifte Trichterling im Gras/Rasen ist Muscarin-verdächtig - bei Verdacht stehen lassen. Der Mönchskopf ist gross (12-25 cm), dickfleischig, waldgebunden und hat einen fühlbaren zentralen Buckel - nicht der zierliche kleine weisse Wiesenpilz. Weisses Sporenpulver schliesst den Gifttrichterling NICHT aus, da auch er weiss aussport.','https://de.wikipedia.org/wiki/M%C3%B6nchskopf · https://123pilzsuche.de/daten/details/Rinnigertrichterling.htm · https://www.mycopedia.ch/pilze/9975.htm · https://www.pilzfinder.de/pilz/moenchskopf.html'),
('infundibulicybe_geotropa','entoloma_sinuatum','hoch','{"SPORENPULVER: Riesenrötling hat FLEISCH-ROSA (fleischrötliches) Sporenpulver; Mönchskopf hat WEISSES Sporenpulver - das sicherste Trennmerkmal per Sporenabwurf.","LAMELLEN: Riesenrötling-Lamellen jung weisslich, dann gelblich, schliesslich durch die Sporen fleischrosa, am Stiel ausgebuchtet/gerade angewachsen (NICHT herablaufend); Mönchskopf-Lamellen bleiben weiss/cremefarben und laufen deutlich am Stiel herab.","HUTFORM: Riesenrötling gewölbt mit eingerolltem, später welligem Rand, OHNE zentralen Buckel und ohne ausgeprägte Trichterform; Mönchskopf trichterförmig mit fühlbarem zentralem Buckel.","GERUCH: Riesenrötling mehlartig mit unangenehm säuerlich-rettichartiger Note; Mönchskopf aromatisch süsslich mit Bittermandel-Note."}','Riesenrötling: 5-20 cm, elfenbein/hell graubraun bis blass lilagrau, gewölbt mit welligem Rand ohne Buckel, dicke starre Lamellen die rosa anlaufen. Mönchskopf: trichterförmig mit zentralem Buckel, weisse herablaufende Lamellen, creme/lederfarben.','Riesenrötling mehlartig mit unangenehm säuerlich-rettichartiger Beigeruch; Mönchskopf aromatisch süsslich mit Bittermandelaroma. Geruch nur als Zusatzmerkmal, der Sporenabwurf ist entscheidend.','Riesenrötling: lichter Laubwald (oft Buche/Eiche-Hainbuche) auf frischem bis feuchtem, kalkreichem Boden, Sommer-Herbst, mykorrhizal. Mönchskopf: Laub-/Nadelwald, Waldränder, Waldwiesen auf feuchtem Kalkboden, Spätsommer-Herbst - Standorte überlappen, daher Sporenabwurf- und Lamellen-Check zwingend.','Entscheidend: Riesenrötling FLEISCHROSA/fleischrötliches Sporenpulver vs. Mönchskopf WEISS. Dies ist das sicherste Trennmerkmal zwischen diesen beiden.','Sporenabwurf machen: Rosa/fleischfarbenes Pulver = Riesenrötling = stehen lassen. Zusätzlich prüfen, ob die Lamellen herablaufen (Mönchskopf) oder nur ausgebuchtet/gerade angewachsen sind und mit der Reife rosa anlaufen (Riesenrötling). Fehlt der zentrale Buckel und ist der Hut nicht echt trichterig, ist Vorsicht geboten.','https://en.wikipedia.org/wiki/Infundibulicybe_geotropa · https://de.wikipedia.org/wiki/Riesen-R%C3%B6tling · https://de.wikipedia.org/wiki/M%C3%B6nchskopf · https://forum.dgfm-ev.de/thread/2035-dieses-jahr-haeufig-entoloma-sinuatum-riesenroetling/'),
('infundibulicybe_gibba','ampulloclitocybe_clavipes','mittel','{"Ockerbrauner Trichterling: Stielbasis NICHT keulig verdickt, gleichmaessig schlank/zylindrisch; clavipes hat eine auffaellig keulig-aufgeblasene, schwammig-waessrige Stielbasis.","Hut des Ockerbraunen ist warm ocker-/fleischbraun mit kleinem zentralem Buckel/Papille; clavipes weissgraeulich bis graubraun mit deutlich dunklerer Hutmitte und hellem, lange eingerolltem Rand.","Fleisch des Ockerbraunen ist duenn, zaeh-elastisch und trocken; clavipes-Fleisch weich, schwammig, bei Naesse stark wassergetraenkt.","clavipes verursacht in Verbindung mit Alkohol ein Coprin-/Acetaldehyd-Syndrom; der Ockerbraune ist alkoholvertraeglich essbar."}','Keulige, geschwollene Stielbasis ist das Schluesselmerkmal von clavipes; der Ockerbraune Trichterling hat einen schlanken, gleichmaessigen Stiel mit zentralem Hutbuckel.','Ockerbrauner Trichterling fast geruchlos bis leicht suesslich; clavipes pilzig-angenehm mit schwach obstartigem Ton.','Beide in Laub-/Nadel-/Mischwald (Sommer bis Spaetherbst); kein zuverlaessiges Trennmerkmal ueber das Habitat.','Beide weisses Sporenpulver; nicht trennend.','Jeden weisslich-grauen Trichterling mit dick-keuliger, schwammiger Stielbasis aussortieren und nie zusammen mit Alkohol verzehren.','123pilze (Keulenfuessiger Trichterling), de.wikipedia.org (Keulenfuss-Trichterling), pilzbuch-pilzwelten.de'),
('infundibulicybe_gibba','clitocybe_fragrans','mittel','{"Ockerbrauner Trichterling ist warm ocker-/fleischbraun, groesser, mit tief trichterigem Hut und kleinem zentralem Spitzchen; fragrans ist klein, blass graubraun und waessrig hell.","fragrans riecht deutlich nach Anis und enthaelt Muscarin; der Ockerbraune Trichterling ist nahezu geruchsneutral und essbar.","Hutrand bei fragrans durchscheinend gerieft; beim Ockerbraunen ungerieft.","Ockerbrauner mit zaeh-elastischem, duennem Fleisch; fragrans-Fleisch zerbrechlich und duenn."}','Warm ockerbrauner, tief trichteriger gibba mit Spitzchen vs. blass grauer, kleiner fragrans mit gerieftem Rand.','fragrans nach Anis; Ockerbrauner Trichterling nahezu geruchlos - ein klares Trennmerkmal.','Beide in Waeldern weit verbreitet; kein zuverlaessiges Trennmerkmal ueber das Habitat.','Beide weisses Sporenpulver; nicht trennend.','Geruchsneutral spricht gegen fragrans, aber kleine Anis-riechende Trichterlinge generell stehen lassen (Muscarin).','pilzbuch-pilzwelten.de, 123pilze'),
('kuehneromyces_mutabilis','conocybe_filaris','sehr_hoch_lebensgefahr','{"Stockschwämmchen: Stiel unter dem Ring deutlich braun, abstehend-schuppig/genattert — Nadelholz-Häubling (Conocybe filaris/Pholiotina rugosa): Stiel glatt bis silbrig-längsfaserig, ohne Schuppen. Das Stiel-Merkmal ist der wichtigste Trennfaktor.","Der Häubling enthält Amatoxine (dasselbe Gift wie der Knollenblätterpilz) — bereits wenige Hüte können tödliches Leberversagen auslösen, mit 6-24h symptomfreier Latenz vor dem Organschaden.","Der Häubling wächst meist terrestrisch auf Rasen, Wiesen, Holzhäcksel, Komposterde und Nadelstreu am Boden — das Stockschwämmchen büschelig direkt auf morschem Laub-/Nadelholz (Stümpfe, liegende Stämme).","Stockschwämmchen wächst typisch in dichten Büscheln am selben Holz; der Häubling steht meist einzeln bis gesellig am Boden, nicht büschelig aus Holz.","Hut des Stockschwämmchens trocknet typisch zweifarbig (hygrophaner Wasser-Saum) ab; der Häubling-Hut ist gleichmäßiger ocker-zimtbraun und kaum zweifarbig gezont."}','Entscheidend ist der Stiel unterhalb des Rings: braun abstehend-schuppig (Stockschwämmchen) gegen glatt bis silbrig-längsfaserig (Häubling). Die Hutfarben sind bei beiden honig- bis zimtbraun und NICHT trennend.','Stockschwämmchen riecht angenehm pilzig-aromatisch; der Häubling ist geruchlich unauffällig bis leicht mehlig — Geruch ist KEIN sicheres Trennmerkmal.','Stockschwämmchen büschelig auf morschem Laub-/Nadelholz (Stümpfe, Totholz); Conocybe filaris terrestrisch auf Rasen, Wiesen, Holzhäcksel, Kompost und Nadelstreu am Boden — Wuchsort (Holz vs. Boden) ist ein wichtiges Indiz, aber allein nicht beweisend.','Beide rostbraun bis zimtbraun — als Trennmerkmal UNBRAUCHBAR. Daher zwingend die Stiel-Schuppung unter dem Ring prüfen.','Stockschwämmchen NUR sammeln, wenn der Stiel unter dem Ring eindeutig braun beschuppt/genattert ist UND der Pilz büschelig auf Holz wächst. Bei glattem/silbrigfaserigem Stiel oder Bodenwuchs auf Rasen sofort verwerfen — Lebensgefahr durch Amatoxine. Im Zweifel zur Pilzkontrolle (VAPKO).','GiftnotrufZentrale (gizbonn.de), 123pilze, DGfM, healing-mushrooms.net (Pholiotina rugosa)'),
('kuehneromyces_mutabilis','galerina_marginata','sehr_hoch_lebensgefahr','{"Stiel unterhalb des Rings: Stockschwämmchen schuppig/bereift, Gifthäubling glatt-seidig","Gifthäubling enthält tödliche Amatoxine"}','Beide honigbraun, hygrophan, büschelig auf Holz — optisch sehr ähnlich; einzig der Stiel unter der Ringzone unterscheidet (schuppig vs. glatt).','beide pilzig, keine sichere Geruchsunterscheidung','beide an totem Holz/Stümpfen, oft gemischt','beide rostbraun','TÖDLICH. Für Anfänger tabu. Nur mit komplettem Stiel ernten und jeden einzelnen Pilz prüfen — im Zweifel zur VAPKO-Kontrolle.','VAPKO / Tox Info Suisse / awl.ch'),
('kuehneromyces_mutabilis','gymnopilus_junonius','mittel','{"Gymnopilus junonius wird sehr gross (Hut 5–15 cm) und wächst in dichten Büscheln; Stockschwämmchen bleibt klein (Hut 2–6 cm).","Geschmack: G. junonius extrem bitter; Stockschwämmchen mild.","Hutoberfläche: Stockschwämmchen hat zweifarbigen, hygrophanen Hut mit durchscheinend gerieftem Rand; G. junonius gleichmässig orange-rostgelb, feinschuppig.","Stiel: Stockschwämmchen unter dem Ring deutlich braun-schuppig/genattert; G. junonius faserig ohne Natterung.","Achtung: Beide haben rostbraunes Sporenpulver – das Sporenpulver trennt hier NICHT, deshalb Grösse/Bitterkeit prüfen."}','G. junonius ist deutlich grösser, gleichmässig orange und feinschuppig; das Stockschwämmchen ist klein mit hygrophanem zweifarbigem Hut und braun-schuppigem Stiel unter dem Ring.','Stockschwämmchen angenehm pilzig; G. junonius mehlig-ranzig, dazu extrem bitterer Geschmack.','Beide büschelig an Holz/Stümpfen; G. junonius an Laub- und Nadelholz-Stümpfen sowie an Stammbasen, Stockschwämmchen meist an Laubholzstümpfen.','Beide rostbraun – die Sporenfarbe trennt diese beiden NICHT. WICHTIG: Das eigentliche tödliche Stockschwämmchen-Risiko ist der Gifthäubling (Galerina marginata), der ebenfalls rostbraun absport – ein separates, lebensgefährliches Verwechslungsthema.','Bitterer Geschmack (Geschmacksprobe ausspucken) und auffällige Grösse = Flämmling = wegwerfen. Stockschwämmchen nur sammeln, wenn die Bestimmung absolut sicher ist – das tödliche Gifthäubling-Risiko ist getrennt zu beachten.','Wikipedia – Beringter Flämmling, 123pilze, pilz-sammler.de'),
('kuehneromyces_mutabilis','hypholoma_fasciculare','mittel','{"Stockschwämmchen: Geschmack mild-nussig; Grünblättriger Schwefelkopf: deutlich und anhaltend BITTER","Stockschwämmchen-Lamellen jung hell, dann zimt- bis rostbraun; Schwefelkopf-Lamellen schwefelgelb, dann grünlich bis grünschwärzlich","Stockschwämmchen hat häutigen Ring + darunter dunkle, abstehende Schüppchen am Stiel; Schwefelkopf hat höchstens eine flüchtige Ringzone, Stiel kahl gelb-rostbraun","Stockschwämmchen-Stiel unterhalb des Rings braun-schuppig genattert; Schwefelkopf-Stiel oben schwefelgelb, nach unten rostbraun, glatt","WICHTIGER als der Schwefelkopf: der TÖDLICHE Gifthäubling (Galerina marginata) wächst ebenfalls büschelig an Totholz, sieht dem Stockschwämmchen sehr ähnlich und ist NICHT bitter - Stockschwämmchen nur ernten, wenn man jeden Fruchtkörper am braun-schuppigen Stiel sicher erkennt"}','Schwefelkopf-Lamellen tragen einen grünlich-schwefelgelben Ton, der dem braunlamelligen Stockschwämmchen fehlt; der braun-schuppig genatterte Stiel unter dem häutigen Ring ist das wichtigste Stockschwämmchen-Merkmal.','Stockschwämmchen riecht angenehm pilzig; der Schwefelkopf ist intensiv bitter. ACHTUNG: Eine Geschmacksprobe trennt NUR den Schwefelkopf ab - der tödliche Gifthäubling ist nicht bitter, eine Kostprobe schützt also NICHT vor ihm.','Beide wachsen büschelig an Totholz/Stümpfen von Laub- und Nadelholz, sodass das Habitat NICHT zur Unterscheidung taugt.','Stockschwämmchen: braunes Sporenpulver (zimt-/rostbraun); Grünblättriger Schwefelkopf: dunkel violett-/purpurbraunes Sporenpulver. Beide sind dunkelsporig - das Sporenpulver trennt sie nur grob, daher zwingend Stiel und Lamellenfarbe prüfen.','Niemals nur auf den bitteren Geschmack vertrauen: Das schützt allein vor dem Schwefelkopf, NICHT vor dem tödlichen, mild schmeckenden Gifthäubling. Stockschwämmchen ausschließlich ernten, wenn JEDER Fruchtkörper den häutigen Ring UND darunter den braun-schuppig genatterten Stiel zeigt UND kein Grünton an den Lamellen sichtbar ist - im Zweifel stehen lassen.','123pilze, GiftnotrufZentrale (GIZ Bonn), DGfM, AWL.ch, Pilzforum.eu'),
('kuehneromyces_mutabilis','hypholoma_lateritium','mittel','{"Stockschwämmchen (essbar) hat einen genatterten/schuppigen Stiel unterhalb der Ringzone, Schwefelköpfe haben höchstens eine flüchtige Ringzone ohne Schuppen","Stockschwämmchen mit hygrophanem, zweifarbig austrocknendem Hut (Wasserfleck-Effekt), Ziegelroter einfarbig ziegelrot","Geschmack Stockschwämmchen mild, Ziegelroter bitter","Sporenpulver Stockschwämmchen tabakbraun/rostbraun, Ziegelroter purpurbraun","Beide wachsen büschelig auf Holz — Wuchsform allein trügt, daher Stielschuppen und Sporenfarbe entscheidend"}','Stockschwämmchen mit beschupptem Stiel und Ringzone, hygrophan ausblassendem Hut; Ziegelroter glatter Stiel ohne Schuppen, einfarbig ziegelrot.','Stockschwämmchen angenehm pilzig und mild, Ziegelroter bitter im Geschmack.','Beide büschelig an Laubholzstümpfen — Habitat trennt nicht, sondern Stielschuppen und Sporenfarbe.','Stockschwämmchen rost-/tabakbraun, Ziegelroter purpurbraun — wichtiges Trennmerkmal.','Stielschuppen unterhalb der Ringzone sind das Schlüsselmerkmal des Stockschwämmchens — fehlen sie, Finger weg. Wichtiger noch: Stockschwämmchen wird mit dem TÖDLICHEN Gifthäubling (Galerina marginata) verwechselt, daher nur bei absoluter Sicherheit sammeln.','123pilze, VAPKO, DGfM'),
('kuehneromyces_mutabilis','pholiota_squarrosa','mittel','{"Sparriger Schüppling hat einen trockenen, sparrig-schuppigen Hut; Stockschwämmchen hat einen glatten bis fein faserigen, hygrophanen Hut mit ausblassendem Rand (zweifarbig)","Schüppling deutlich grösser und robuster, oft 5–12 cm Hut; Stockschwämmchen klein, 3–6 cm","Stockschwämmchen-Stiel unterhalb des Rings dunkelbraun und fein beschuppt/genattert; Schüppling-Stiel grob sparrig beschuppt","Geschmack: Schüppling bitter/unangenehm, Stockschwämmchen mild","Beide rostbraunes Sporenpulver — hier kein Unterscheidungsmerkmal"}','Trockener, grob-sparriger Hut beim Schüppling vs. glatter, hygrophan zweifarbiger Hut mit ausblassendem Rand beim Stockschwämmchen.','Schüppling aufdringlich rettichartig, Stockschwämmchen angenehm würzig-mild.','Beide büschelig an Holz/Stümpfen — Standort nicht trennend.','Beide rostbraun — taugt hier NICHT zur Abgrenzung, daher andere Merkmale zwingend.','Vorsicht: Stockschwämmchen ist selbst Anfänger-Tabu wegen des tödlichen Gifthäublings (Galerina marginata). Schüppling, Stockschwämmchen und Gifthäubling wachsen alle büschelig an Holz — diese Gruppe nur mit Expertenwissen und Sporenabwurf ernten.','123pilze, CVUA Stuttgart, Wikipedia (Gemeines Stockschwämmchen), Pilzbuch-Pilzwelten'),
('kuehneromyces_mutabilis','pholiotina_rugosa','sehr_hoch_lebensgefahr','{"Pholiotina rugosa (= Conocybe filaris) ist ein kleiner brauner Pilz (LBM) mit dünnem, brüchigem Stiel und einem beweglichen, häutigen Ring — enthält tödliche Amatoxine wie der Grüne Knollenblätterpilz","Pholiotina wächst EINZELN bis gesellig auf Erde, Rasen, Wegrändern, Mulch, Holzhäcksel/Komposterde — NICHT büschelig an Stümpfen; Stockschwämmchen wächst dicht büschelig auf morschem Holz/Stümpfen","Stockschwämmchen-Stiel unter dem Ring deutlich dunkelbraun und fein schuppig genattert; Pholiotina-Stiel glatt, blass, ohne Natterung","Stockschwämmchen-Hut hygrophan, zweifarbig mit ausblassendem Rand; Pholiotina-Hut ockerbraun, runzelig, ohne diese Zweifarbigkeit","Pholiotina ist meist viel kleiner und zierlicher als ein typisches Stockschwämmchen"}','Stockschwämmchen büschelig am Holz mit genattertem dunklem Stiel; Pholiotina einzeln/gesellig auf Erde, glatter blasser Stiel, runzeliger Hut.','Stockschwämmchen angenehm würzig; Pholiotina rugosa unauffällig bis leicht ranzig — Geruch ist KEIN sicheres Trennkriterium.','Entscheidend, aber NICHT allein verlassen: Stockschwämmchen büschelig an Holz; Pholiotina rugosa auf Boden/Rasen/Mulch/Häcksel. Da Pholiotina auch auf Holzhäcksel fruchten kann, ist Holznähe allein kein Freibrief — immer mehrere Merkmale prüfen.','Stockschwämmchen rostbraun; Pholiotina rugosa rostbraun bis zimtbraun — Sporenfarbe trennt NICHT, daher Standort, Stiel-Natterung und Habitus entscheidend.','Kleine braune Pilze (LBMs) mit Ring NIE für Stockschwämmchen halten, wenn sie auf Erde/Rasen/Mulch statt büschelig an Holz wachsen — Lebensgefahr durch Amatoxin. Im Notfall Tox Info Suisse 145 anrufen.','DGfM, GiftnotrufZentrale, Wikipedia/healing-mushrooms (Pholiotina rugosa / Conocybe filaris), bayareamushrooms.org (Amatoxin)'),
('lactarius_deliciosus','paxillus_involutus','mittel','{"MILCH-TEST (entscheidend): Edel-Reizker gibt beim Anschnitt reichlich karotten-/orangeroten Milchsaft ab. Der Kahle Krempling gibt KEINE Milch ab – er ist kein Milchpilz. Kein orangeroter Milchsaft = kein Reizker.","Druckverfärbung: Krempling-Lamellen und -Fleisch verfärben sich bei Druck/Verletzung sofort braun bis dunkelrot-/schwarzbraun. Reizker-Fleisch/Milch verfärbt sich nur langsam grünlich (nie braun-schwarz).","Lamellen: Krempling ockergelb → olivbraun, am Stiel herablaufend und leicht vom Hutfleisch ablösbar. Reizker-Lamellen sind orange/safranfarben und nicht ablösbar.","Hutfarbe + Hutrand: Reizker orange bis karottenrot mit dunkleren konzentrischen Ringzonen. Krempling matt gelbbraun bis umberbraun, ohne Orange, mit dauerhaft eingerolltem, filzigem Hutrand (auch im Alter)."}','Edel-Reizker: durchgängig orange bis karottenrot, Hut mit dunkleren konzentrischen Zonen, oft grünliche Flecken im Alter/bei Verletzung, Stiel häufig mit Grübchen. Kahler Krempling: matt gelbbraun bis umberbraun, dauerhaft eingerollter filziger Hutrand, kein Orange, keine konzentrischen Reizker-Zonen.','Edel-Reizker: mild, fruchtig-obstartig. Kahler Krempling: unauffällig, leicht säuerlich; kein typischer Reizker-Duft.','Habitat-Überschneidung möglich: Edel-Reizker ist Mykorrhiza-Partner von Kiefern (z.T. Fichten), eher kalkhaltiger Boden. Kahler Krempling bildet Mykorrhiza mit Kiefer, Fichte, Birke, Buche auf sauren, frischen bis feuchten Böden. Standort ist daher KEIN sicheres Trennmerkmal – nur Milch-Test und Farbe zählen.','Edel-Reizker: cremeweiss bis blass ockergelbliches Sporenpulver. Kahler Krempling: bräunliches (tonbraunes) Sporenpulver – deutlich dunkler. Klare diagnostische Richtung: Krempling immer merklich dunkler.','Schnitt-/Milch-Test ist Pflicht: Wer KEINEN orangeroten Milchsaft am Anschnitt sieht, hat keinen Reizker – stehen lassen. Der Kahle Krempling sondert nie Milch ab und läuft bei Druck braun-schwarz an (Reizker grünt nur langsam). Das Paxillus-Syndrom (immun-hämolytisch) kann nach jahrelangem wiederholtem Verzehr tödlich verlaufen – deshalb niemals ''zum Probieren'' verkosten, selbst gegart nicht.','https://de.wikipedia.org/wiki/Kahler_Krempling · https://de.wikipedia.org/wiki/Edel-Reizker · https://www.pilzbuch-pilzwelten.de/kahler-krempling/paxillus-involutus.html · https://www.pilzbuch-pilzwelten.de/edelreizker/lactarius-deliciosus.html · https://www.pilzfinder.de/pilz/echter.html'),
('lactarius_deterrimus','paxillus_involutus','hoch','{"MILCHPROBE (entscheidend, verifiziert): Fichtenreizker gibt beim Anschneiden orange/karottenrote Milch ab, die in 15-20 Min weinrot wird (später graugrün); der Kahle Krempling gibt KEINE Milch/Flüssigkeit ab — gar keine Milch = NIE essen, wenn man einen Reizker erwartet.","Lamellen-Druckprobe (verifiziert): Krempling-Lamellen verfärben sich auf Druck stark rost- bis schwarzbraun und lassen sich vom Hut ablösen; Reizker-Lamellen sind brüchig, fest mit dem Hut verbunden und werden bei Verletzung dunkelrot/graugrün, nicht rostbraun.","Hutrand & Form: Krempling hat lange filzig-eingerollten Hutrand und glänzend-olivbraunen Hut; Reizker-Hut ist orange mit grünen Flecken, ohne dauerhaft filzigen Rolleinroll.","Sporenpulver (Zusatz, nicht allein verlässlich): Reizker creme bis ocker vs. Krempling ton-/rostbraun — überlappt Richtung Ocker, daher nur ergänzend."}','Fichtenreizker: orangeroter bis orangebräunlicher Hut, im Alter/bei Frost schmutzig grünfleckig, blassorange Lamellen die bei Verletzung dunkelrot bis graugrün anlaufen. Kahler Krempling: gelblich- bis umberbrauner, feucht glänzender Hut, jung mit lange eingerolltem filzigem Hutrand, alt deutlich trichterförmig vertieft; ocker-gelbliche bis oliv-braune, dünn-gedrängte, herablaufende und ablösbare Lamellen, die auf Druck/Berührung STARK rost- bis schwarzbraun verfärben (Reizker-Lamellen werden nicht rostbraun). Beide können trichterförmig-orangebraun wirken -> daher die Verwechslung.','Fichtenreizker: mild, obstig-würzig (Geschmack leicht bitter). Kahler Krempling: säuerlich-unauffällig; Geruch ist KEIN verlässliches Trennmerkmal — Milch- und Lamellen-Druckprobe sind entscheidend.','Überschneidung gegeben: Kahler Krempling ist Mykorrhiza-Partner u.a. der Fichte (auch Kiefer, Birke, Buche, Hainbuche) und wächst im selben sauren Nadel-/Mischwald-Boden, in dem der Fichtenreizker bei Fichte vorkommt. Habitat trennt NICHT zuverlässig.','Sekundäres Merkmal, nicht scharf trennend: Fichtenreizker je nach Quelle creme bis blass-ocker bis ockerbräunlich; Kahler Krempling deutlich ton- bis rostbraun. Die Farben überlappen Richtung Ocker — daher nur als Zusatzbeleg, nicht als Hauptkriterium. Entscheidend bleibt die Milchprobe. Im Zweifel Sporenabwurf nehmen.','Immer die Milchprobe machen: frisch anschneiden und auf Milchaustritt prüfen. Tritt KEINE Milch aus, ist es kein Reizker — der Kahle Krempling ist milchlos und kann über das kumulative Paxillus-Syndrom (hämolytische Anämie, Nierenversagen) auch nach jahrelangem Verzehr lebensbedrohlich werden. Reizker geben dagegen orange/karottenrote Milch ab, die zu weinrot wird. Faustregel: nur Milchlinge mit roter/orange Milch sammeln — nie mit heller/weißer Milch oder ganz ohne Milch.','https://de.wikipedia.org/wiki/Fichten-Reizker · https://de.wikipedia.org/wiki/Kahler_Krempling · https://www.pilzbuch-pilzwelten.de/kahler-krempling/paxillus-involutus.html · https://www.pilzbuch-pilzwelten.de/fichtenreizker/lactarius-deterrimus.html · https://flexikon.doccheck.com/de/Paxillus-Syndrom · https://www.wien.gv.at/gesellschaft/konsumentenschutz/lebensmittel/pilze/giftig/krempling.html'),
('lactarius_rufus','lactarius_helvus','mittel','{"Bruchreizker/Maggipilz (giftig) riecht beim Trocknen intensiv nach Maggi/Liebstöckel — einzigartiges Merkmal; Rotbrauner Milchling geruchlos bis schwach","Maggipilz mit ocker-graubraunem, fein samtigem, oft trockenem Hut und WÄSSRIGER, farbloser Milch; Rotbrauner mit kräftig rotbraunem Hut und weisser Milch","Maggipilz wächst in Moor/Sphagnum unter Kiefer/Birke, Rotbrauner in saurem Nadelwald","Geschmack Rotbrauner brennend scharf (ungeniessbar), Maggipilz mild — daher Geschmack hier kein Schutz"}','Maggipilz blass ocker-graubraun mit wässrig-farbloser Milch; Rotbrauner Milchling kräftig rotbraun mit weisser Milch.','Maggipilz riecht charakteristisch nach Maggi/Liebstöckel (besonders getrocknet); Rotbrauner praktisch geruchlos.','Maggipilz in Mooren/feuchtem Sphagnum, Rotbrauner in trockenerem saurem Nadelwald.','Beide cremefarben — kein Trennmerkmal.','Wässrig-farblose statt weisse Milch plus Maggi-Geruch = Bruchreizker, stehen lassen. Keine Milchlinge mit klarer/wässriger Milch verzehren.','123pilze, SwissFungi, DGfM'),
('lactarius_subdulcis','lactarius_blennius','mittel','{"Graugrüner Milchling (giftig) mit schmierig-schleimigem, grau-olivgrünem Hut, oft mit konzentrischen Flecken; Süsslicher Buchen-Milchling trocken, rotbraun bis zimtfarben","Milch des Graugrünen weiss, an der Luft grau-grün eintrocknend und scharf/brennend; Milch des Süsslichen weiss, mild bis schwach bitterlich, nicht verfärbend","Graugrüner deutlich grösser und robuster, Süsslicher klein und zerbrechlich","Geschmack Graugrüner scharf-kratzend, Süsslicher mild-süsslich (daher der Name)"}','Graugrüner mit schleimigem, grünlich-grauem, fleckigem Hut; Süsslicher mit trockenem, rotbraunem, ungezontem Hut.','Beide unauffällig; entscheidend ist der scharfe Geschmack des Graugrünen gegen den milden des Süsslichen.','Beide unter Buche — Habitat trennt nicht; auf Hutoberfläche (schleimig vs. trocken) und Milchverfärbung achten.','Beide cremefarben bis blass ocker — kein verlässliches Trennmerkmal.','Schleimiger grau-grüner Hut + grünlich eintrocknende, scharfe Milch = giftiger Graugrüner Milchling. Scharfe Milchlinge gehören generell nicht in den Korb.','123pilze, SwissFungi, DGfM'),
('laetiporus_sulphureus','hapalopilus_nidulans','hoch','{"Zimtfarbener Weichporling (giftig): KOH/Kalilauge auf Poren oder Fleisch → sofort kräftig violett/lila (auch an Trockenmaterial). Schwefelporling: keine violette Reaktion. Das ist das sicherste Trennmerkmal.","Farbe Schwefelporling: jung leuchtend schwefelgelb bis orange. Zimtfarbener Weichporling: höchstens jung stumpf ocker-/ledergelb, rasch zimt- bis rosa-/rotbraun — nie das leuchtende Schwefelgelb-Orange des Schwefelporlings.","Zimtfarbener Weichporling ist durch und durch gleichfarbig zimt-/rosabraun (auch Trama) und meist klein (Konsole 3-12 cm, max. ~18 cm); junger Schwefelporling ist innen weisslich-gelb und wird deutlich grösser.","Wuchsort Zimtfarbener Weichporling: meist totes Laubholz, gern Eiche und Hasel; Schwefelporling oft an (auch lebenden) Laub- und Obstbäumen (Eiche, Weide, Robinie, Pflaume, Walnuss).","Gift: Polyporsäure → nach ~12 h Latenz zentralnervöse Störungen, Sehstörungen, Erbrechen, Nieren-/Leberschäden, violetter Urin — der milde Geschmack warnt NICHT, möglicherweise tödlich."}','Schwefelporling ist jung leuchtend schwefelgelb-orange und innen hell; der Zimtfarbene Weichporling ist durchgehend matt ocker-, zimt- bis rosabraun gefärbt und deutlich kleiner (max. ~18 cm).','Geruch ist bei beiden schwach und unzuverlässig; der milde Geschmack des Giftpilzes warnt nicht — daher NIE auf Geruch/Geschmack verlassen, sondern KOH-Test machen.','Zimtfarbener Weichporling meist auf totem Laubholz (Eiche, Hasel); Schwefelporling häufig als Konsolenbüschel an (auch lebenden) Laub- und Obstbäumen (Eiche, Weide, Robinie, Pflaume).','Sporenpulver bei beiden Porlingen weisslich und ohne Sammelpraxis kaum prüfbar — daher KOH-Test statt Sporenpulver verwenden.','Braune/ocker Porlinge nie sammeln, ohne mit Kalilauge (KOH) zu testen: violett/lila = giftiger Zimtfarbener Weichporling, stehen lassen. Nur jung leuchtend schwefelgelb-orange wachsende Schwefelporlinge an Laubholz, gegart und nur der weiche Aussensaum, gelten als essbar.','Wikipedia Zimtfarbener Weichporling, Stadt Wien Konsumentenschutz, fungiversum.de, pilzbuch-pilzwelten.de (Schwefelporling)'),
('lepista_glaucocana','clitocybe_fragrans','mittel','{"Lavendelfarbener Roetelritterling ist deutlich groesser, fleischiger und blass violett-lavendel ueberhaucht; fragrans ist klein, duennfleischig und blass graubraun ohne Violetttoene.","fragrans riecht nach Anis und enthaelt Muscarin; der Lavendel-Roetelritterling riecht angenehm-parfuemiert und ist essbar.","Lamellen des Roetelritterlings ausgebuchtet angewachsen und leicht abschiebbar; fragrans-Lamellen herablaufend.","Sporenpulver trennt: Roetelritterling rosaweisslich, fragrans weiss."}','Grosser, lavendel-violett ueberhauchter Roetelritterling vs. kleiner blass grauer fragrans.','Roetelritterling angenehm parfuemiert; fragrans nach Anis.','Beide spaetherbstlich im Wald; kein zuverlaessiges Trennmerkmal ueber das Habitat.','Lavendel-Roetelritterling rosaweissliches Sporenpulver, fragrans weiss.','Kleine, anisartig riechende, weissporige Trichterlinge wegen Muscarin generell aussortieren.','123pilze (Lavendel-Roetelritterling), pilzbuch-pilzwelten.de'),
('lepista_glaucocana','cortinarius_traganus','hoch','{"Lepista glaucocana ohne Schleier/Cortina; C. traganus mit faseriger Schleierzone am keuligen Stiel.","Sporenpulver: Lepista glaucocana blass rosa-creme, C. traganus rostbraun.","Geruch: Lepista glaucocana mild-angenehm; C. traganus böckig/ziegenartig unangenehm.","Lamellen: C. traganus jung safran-ocker, nie blauviolett, später rostbraun; Lepista glaucocana weisslich bis blass lavendel/lila, leicht abschiebbar."}','Beide blass lila-lavendel, aber C. traganus hat keuligen Stiel mit Schleierzone und ocker-rostbraune Lamellen, Lepista glaucocana hat helle, abschiebbare Lamellen ohne Velum.','Lepista glaucocana riecht mild und angenehm; C. traganus widerlich böckig.','C. traganus in Nadelwald-Streu; Lepista glaucocana in Laub-/Mischwald und Nadelwald an nährstoffreichen Stellen, oft in höheren Lagen.','Lepista glaucocana: blass rosa-cremefarben. C. traganus: rostbraun – Sporenabwurf trennt sicher.','Rostbrauner Sporenabwurf oder Schleierreste am Stiel = Cortinarius = nicht essen. Verlasse dich nie nur auf die Farbe.','123pilze, pilzbuch-pilzwelten.de – Lepista glaucocana / Cortinarius traganus'),
('lepista_nuda','cortinarius_orellanus','sehr_hoch_lebensgefahr','{"Sporenpulver-Abdruck (zuverlaessigster Unterscheider zur gesamten Schleierlings-Gattung): Lepista nuda blass rosa-weisslich vs. Cortinarius orellanus rostbraun. Rostbrauner Abdruck schliesst Lepista nuda aus.","Cortina/Schleier: orellanus hat einen (jung gelblichen) spinnwebartigen Schleier mit rostbraunen Schleierresten am Stiel; Lepista nuda hat keinerlei Velum.","Hutfarbe: orellanus gelb- bis rotbraun/fuchsig (NIE violett), oft leicht gebuckelt; Lepista nuda in der Jugend durchgehend violett.","Lamellenfarbe: orellanus gelb-/zimtbraun, entfernt stehend, ausgebuchtet angeheftet; Lepista nuda violett/violett-rosa und hell bleibend."}','Cortinarius orellanus: gelb-/rotbrauner, leicht gebuckelter, fein schuppig-faseriger Hut, gelb-zimtbraune Lamellen, rostbraune Schleierfasern am Stiel. Lepista nuda: durchgehend violett, glatter gewoelbter Hut ohne Schleier.','Lepista nuda deutlich aromatisch-suesslich (parfuemartig). orellanus riecht schwach rettichartig, ohne suesslichen Duft. Geruch nur als Indiz, nie allein verlaesslich.','orellanus: Laub-/Mischwald bei Eiche und Buche (Mykorrhiza), Sommer bis Spaetherbst, eher selten/waermebeguenstigt. Lepista nuda: naehrstoffreiche Streu, Hecken, Kompost, sehr spaet in der Saison.','Lepista nuda blass rosa-weisslich; Cortinarius orellanus rostbraun. Rostbrauner Abdruck schliesst Lepista nuda aus.','Sporenpulver-Abdruck ist Pflicht: rostbraun = Schleierling, lebensgefaehrlich. Cortinarius orellanus gilt als einer der gefaehrlichsten Pilze Europas (Orellanin, Latenz bis 14 Tage, Nieren- und Leberschaeden). Ein spinnwebartiger Schleier am jungen Pilz oder rostbraune Stielfasern = nie essen. Im geringsten Zweifel verwerfen.','https://pilzbuch.pilzwelten.de/orangefuchsiger-raukopf/cortinarius-orellanus.html · https://www.dgfm-ev.de/pilz-des-jahres/2002-orangefuchsiger-raukopf · https://de.wikipedia.org/wiki/Orangefuchsiger_Raukopf · https://www.fungusfactfriday.com/223-lepista-nuda/ · https://gizbonn.de/giftzentrale-bonn/pilze/giftige-pilze-und-ihre-doppelgaenger/violetter-roetelritterling-lepista-nuda'),
('lepista_nuda','cortinarius_rubellus','sehr_hoch_lebensgefahr','{"Sporenpulver-Abdruck (sicherster Trennungs-Check): Lepista nuda blass rosa-weisslich/cremerosa — JEDER Cortinarius/Raukopf hat ROSTBRAUNES Sporenpulver. Ein rostbrauner Abdruck schliesst den Roetelritterling sicher aus.","Cortina/Schleier: Raukopf hat als Jungpilz einen spinnwebartigen Schleier (Cortina) zwischen Hutrand und Stiel; Schleierreste am Stiel verfaerben rostbraun. Der Roetelritterling hat NIE einen Schleier — keinerlei Velum.","Hutform/Farbe: Cortinarius rubellus rost- bis zimt-/fuchsorange mit spitzem, gebuckeltem Scheitel; Lepista nuda jung durchgehend violett, gewoelbter Hut ohne spitzen Buckel.","Lamellenfarbe: Roetelritterling violett/violett-rosa und hell bleibend; Raukopf zimt-/rostbraun, entfernt stehend, ausgebuchtet angeheftet.","Habitat: Raukopf bei Nadelbaeumen (Fichte) auf saurem, oft moorig-feuchtem Boden im Bergland; Roetelritterling in naehrstoffreicher Laub-/Mischwald-Streu, Hecken, Komposthaufen, spaet in der Saison bis nach Frost."}','Lepista nuda: jung durchgehend violett (Hut, Lamellen, Stiel), gewoelbter glatter Hut ohne spitzen Buckel, kein Schleier. Cortinarius rubellus: rost- bis fuchsorange Hut mit spitzem (gebuckeltem) Scheitel, fein filzig-faserig, zimt-/rostbraune Lamellen, rostbraune Schleierfasern am Stiel.','Lepista nuda riecht aromatisch-suesslich (parfuemartig, an Keks/Orangenbluete erinnernd). Cortinarius rubellus riecht schwach rettichartig, ohne den typischen suesslichen Duft. Geruch ist nur ein Indiz, NIE allein verlaesslich — Sporenpulver + Cortina entscheiden.','Raukopf: saure Nadelwaelder (Fichte/Fichten-Kiefern-Mischwald), moorig-feuchte und Bergland-Standorte, Aug-Okt. Roetelritterling: naehrstoffreiche Laub-/Mischwald-Streu, Hecken, Komposthaufen, sehr spaet in der Saison bis nach den ersten Froesten.','Entscheidend: Lepista nuda = blass rosa-weissliches/cremerosa Sporenpulver. Cortinarius rubellus = rostbraunes Sporenpulver. Rostbrauner Abdruck schliesst Lepista nuda sicher aus.','IMMER einen Sporenpulver-Abdruck nehmen (Hut ueber Nacht auf weisses Papier). Blass rosa-weisslich = moeglicherweise Lepista nuda. Rostbraun ODER ein spinnwebartiger Schleier (Cortina) am jungen Pilz = STOPP, Schleierling — niemals essen. Orellanin-Vergiftung zeigt sich erst nach 3-14 Tagen, dann ist die Niere bereits irreversibel geschaedigt. Im geringsten Zweifel nicht essen.','https://www.pilzbuch-pilzwelten.de/spitzgebuckelter-raukopf/cortinarius-rubellus.html · https://de.wikipedia.org/wiki/Spitzgebuckelter_Raukopf · https://gizbonn.de/giftzentrale-bonn/pilze/giftige-pilze-und-ihre-doppelgaenger/violetter-roetelritterling-lepista-nuda · https://www.fungusfactfriday.com/223-lepista-nuda/ · https://www.awl.ch/pilze/pilz_dateien/cortinarius-rubellus/spitzgebuckelter-raukopf.htm'),
('lepista_nuda','cortinarius_traganus','hoch','{"Lepista nuda hat KEINEN Schleier/Cortina und keine Velumreste am Stiel; C. traganus zeigt eine faserig-schleierige Ringzone (Cortinarius-Merkmal).","Sporenpulver: Lepista nuda rosa-cremefarben, C. traganus rostbraun – Abwurf macht die Verwechslung sicher unterscheidbar.","Geruch: Lepista nuda angenehm parfümiert-aromatisch; C. traganus unangenehm böckig/ziegenartig.","Lamellen: Lepista nuda durchgehend violett bleibend, lassen sich leicht abschieben; C. traganus jung safran-ocker, nie violett, später rostbraun.","Fleisch: Lepista nuda violett durchgefärbt; C. traganus safranbräunlich/ocker im Schnitt."}','Beide jung violett, aber C. traganus hat einen keulig verdickten Stiel mit Schleierzone und nie violette Lamellen, während Lepista nuda durchgehend violette, leicht abschiebbare Lamellen ohne Velum zeigt.','Lepista nuda riecht angenehm aromatisch-parfümiert; C. traganus riecht widerlich böckig/ziegenartig – ein verlässliches Warnzeichen.','C. traganus bevorzugt Nadelwald (v.a. unter Fichten/Tannen in Moos); Lepista nuda wächst eher in Laub-/Mischwald und Komposthaufen, oft in Hexenringen.','Lepista nuda: rosa-cremefarbenes Sporenpulver. C. traganus: rostbraunes Sporenpulver. Sporenabwurf ist das entscheidende Sicherheitsmerkmal.','Bei JEDEM violetten Pilz Sporenabwurf machen: rostbraun = Cortinarius = stehen lassen. Nur rosa-creme Sporenpulver ohne Schleierreste spricht für den essbaren Rötelritterling.','123pilze, pilzbuch-pilzwelten.de (Lepista nuda / Cortinarius traganus), Wikipedia – Violetter Rötelritterling'),
('lepista_nuda','mycena_pura','mittel','{"Mycena pura ist giftig (enthaelt Muscarin, frueher faelschlich als essbar gefuehrt); der Violette Roetelritterling ist nur DURCHGEGART essbar","Mycena pura riecht intensiv und durchdringend nach Rettich; Lepista nuda riecht angenehm wuerzig-parfuemiert, nie nach Rettich","Mycena pura ist klein und duennfleischig (Hut nur bis ca. 4 cm, glasig-helmfoermig, gerieft); Lepista nuda kraeftig fleischig (Hut 5-15 cm, nicht gerieft)","Mycena pura mit duennem, hohlem, zerbrechlichem Stiel; Lepista nuda mit festem, faserig-vollem, oft violettem Stiel","Lepista nuda durchgehend kraeftig violett bis graulila (Hut, Lamellen, Stiel); Mycena pura nur blass lila/rosa und rasch ausbleichend"}','Lepista nuda gross, fleischig, durchgehend kraeftig violett mit ungerieftem Hut; Mycena pura klein, glasig-gerieft, blasslila und schnell ausbleichend.','Mycena pura stark und durchdringend nach Rettich; Lepista nuda angenehm wuerzig-parfuemiert - der Rettichgeruch ist das wichtigste Warnsignal.','Beide im Laub- und Nadelwald auf der Streu; Lepista nuda oft gesellig oder in Hexenringen im Falllaub, Mycena pura einzeln bis gesellig auf Streu und Nadeln.','Lepista nuda rosa- bis blasslila Sporenpulver; Mycena pura weisses Sporenpulver - die Sporenpulverfarbe trennt die beiden eindeutig.','Jeder kleine, duennfleischige, gerieft-glasige Lilapilz mit starkem Rettichgeruch ist verdaechtig - Rettichgeruch + weisses Sporenpulver schliessen den essbaren Roetelritterling sicher aus.','123pilze, Wikipedia (Gemeiner Rettich-Helmling / Lepista nuda), pilzbuch-pilzwelten, DGfM'),
('lycoperdon_perlatum','amanita_phalloides','sehr_hoch_lebensgefahr','{"LÄNGSSCHNITT (der entscheidende Test): Beim Stäubling ist das Innere eine völlig gleichmäßige, rein weiße, marshmallowartige Masse OHNE jede Struktur. Im jungen Knollenblätterpilz-Ei sieht man im Schnitt bereits den vorgeformten Pilz – die angelegten Lamellen und den Stiel als dunklere Silhouette/Schattenriss. Schon ein einziger erkennbarer Lamellen- oder Stielansatz = wegwerfen.","Stielbasis/Volva: Der junge Amanita steckt in einer weißen häutigen Gesamthülle (Velum) und hat an der Basis eine lappige, häutige Knolle/Volva. Der Stäubling hat keine Volva, keinen abgegrenzten Stiel und keine Hülle dieser Art – er sitzt mit einer kurzen sterilen Basis im Boden.","Außenhaut: Flaschenstäubling trägt feine abwischbare Stachel-/Warzenwärzchen, die ein Netzmuster hinterlassen, und ist innen weiß. Das Amanita-Ei ist außen glatt-häutig weiß.","Reife verändert den Stäubling: Sobald das Innere gelblich/olivlich/bräunlich wird (Sporenbildung), ist er nicht mehr essbar – das Amanita-Fleisch bleibt im Schnitt weiß und zeigt die Pilz-Silhouette."}','Von außen kann ein weißes, geschlossenes Knollenblätterpilz-Ei einem jungen weißen Stäubling oberflächlich gleichen. Sicher trennbar erst im Längsschnitt: homogene weiße Masse (Stäubling) vs. vorgeformter Pilz mit Lamellen-/Stiel-Silhouette und Volva (Amanita).','Junger Stäubling geruchlos bis pilzig-mild. Junger Knollenblätterpilz nahezu geruchlos, erst im Alter süßlich-honigartig bis aasartig. Geruch ist im kritischen Ei-Stadium KEIN verlässliches Merkmal.','A. phalloides ist Mykorrhizapilz v.a. bei Eiche und Buche (auch Kastanie), bevorzugt saure Böden; Stäubling ist saprotroph und ubiquitär in allen Waldtypen, Wiesen und Gärten. Standorte überschneiden sich häufig → Standort hilft NICHT zur Unterscheidung, nur der Schnitttest ist sicher.','Beim Stäubling reift im Inneren gelb- bis olivbraunes Sporenpulver (Pilz ist dann nicht mehr essbar). A. phalloides hat weißes Sporenpulver – im Ei-Stadium aber nicht prüfbar, daher für den Sammler irrelevant.','JEDEN kugeligen Stäubling vor dem Verzehr der Länge nach komplett halbieren und das Schnittbild prüfen. Nur essen, wenn das Innere VOLLSTÄNDIG rein weiß und homogen ist – ohne den geringsten Schattenriss von Lamellen, Stiel oder Hut. Ein einziger erkennbarer Pilz-Umriss bedeutet tödliche Amatoxin-Vergiftung (Leberversagen). Im Zweifel zur Pilzkontrollstelle (VAPKO).','https://de.wikipedia.org/wiki/Gr%C3%BCner_Knollenbl%C3%A4tterpilz · https://en.wikipedia.org/wiki/Amanita_phalloides · https://en.wikipedia.org/wiki/Lycoperdon_perlatum · https://www.first-nature.com/fungi/lycoperdon-perlatum.php · https://www.pilzkurse.com/lycoperdon'),
('lycoperdon_perlatum','amanita_verna','sehr_hoch_lebensgefahr','{"Wie alle weißen Knollenblätterpilze (Sektion Phalloideae) ist A. verna im jungen, vom weißen Velum umhüllten Ei-Stadium kugelig und kann mit weißen Stäublingen verwechselt werden. LÄNGSSCHNITT entscheidet: homogene weiße Masse (Stäubling) vs. vorgeformte Lamellen + Stiel im Ei (Amanita).","Stielbasis: A. verna zeigt eine deutlich ausgeprägte, lappige, sackartig-häutige Scheide (Volva) an der Basis – beim Stäubling fehlt jede Volva.","Lamellen bleiben weiß bis cremeweiß (auch reif) – im Ei als helle Silhouette im Schnitt angelegt; der Stäubling hat nie Lamellenansätze.","Außen rein weiß-häutig (Amanita) vs. feinwarzig/stachelig mit abwischbaren Wärzchen (Flaschenstäubling)."}','Äußerlich dem jungen weißen Stäubling sehr ähnlich (rein weiß-häutiges Ei); sicher nur im Querschnitt durch die angelegte Pilz-Struktur (Lamellen+Stiel) und die ausgeprägte Volva zu unterscheiden – nicht an der Außenform.','A. verna jung geruchlos bis schwach; im Alter unangenehm-süßlich. Kein verlässliches Trennmerkmal im Ei-Stadium.','A. verna tritt v.a. im Frühling/Frühsommer auf (Laubwälder, eher kalkhaltige/wärmere Böden); Stäublinge erscheinen eher Sommer–Herbst und sind ubiquitär. Saison/Standort sind Indizien, aber KEIN sicherer Ersatz für den Schnitttest.','A. verna: weißes Sporenpulver. Stäubling: gelb-/olivbraunes Sporenpulver bei Reife (dann nicht mehr essbar). Im Ei-Stadium nicht prüfbar, daher irrelevant für die Bestimmung.','Auch hier: jeden kugeligen weißen Fund halbieren – nur bei vollständig homogenem weißem Inneren ohne Lamellen-/Stiel-Silhouette und ohne Volva essen. Ein angelegter Pilz im Schnitt bedeutet tödliche Amatoxin-Vergiftung. Kontrollstelle (VAPKO) bei jeder Unsicherheit.','https://de.wikipedia.org/wiki/Fr%C3%BChlings-Knollenbl%C3%A4tterpilz · https://www.natur-in-nrw.de/HTML/Pilze/Agaricales/PA-35.html · https://en.wikipedia.org/wiki/Lycoperdon_perlatum · https://www.vapko.ch/de/massnahmen-bei-pilzvergiftungen · https://www.pilzkurse.com/lycoperdon'),
('lycoperdon_perlatum','gemeiner-fliegenpilz-var-alba','sehr_hoch_lebensgefahr','{"Junge Stadien von Amanita virosa werden in Pilz-/Giftdatenbanken ausdrücklich mit Bovisten und Stäublingen verwechselt. Entscheidend ist der LÄNGSSCHNITT: Stäubling = homogene rein weiße Masse; Amanita-Ei = bereits angelegte (weiße, gedrängte) Lamellen und Stiel als Silhouette erkennbar.","Stielbasis: A. virosa hat eine häutige, lappige weiße Scheide (Volva) an der Basis. Der Stäubling hat keine Volva und keinen abgesetzten Stiel.","Außenkontur: Das virosa-Ei ist rein weiß und glatt-häutig; der Flaschenstäubling trägt feine abwischbare Wärzchen/Stacheln.","Da A. virosa komplett weiß ist (Hut, Lamellen, Stiel bleiben weiß), entfällt der Farbhinweis – nur Schnittbild und Volva trennen sicher."}','Von oben/außen kaum vom jungen weißen Stäubling zu trennen, da A. virosa komplett rein weiß ist. Sichere Unterscheidung erst im Querschnitt: vorgeformter weißer Pilz mit gedrängten Lamellen + Volva (Amanita) vs. homogene weiße Masse (Stäubling).','Älterer A. virosa riecht unangenehm süßlich-widerlich; junges Ei aber unauffällig. Geruch im kritischen Ei-Stadium nicht verlässlich.','A. virosa wächst v.a. in feuchten (sauren) Nadel-/Mischwäldern, Mykorrhiza bevorzugt mit Fichte (Funde auch bei Buche/Eiche/Birke dokumentiert), oft in höheren/montanen Lagen – ökologisch teils anders als der ubiquitäre saprotrophe Stäubling, aber Standort ist KEIN sicheres Kriterium.','A. virosa: weißes Sporenpulver. Beim Stäubling reift gelb-/olivbraunes Sporenpulver (= dann nicht mehr essbar). Im Ei-Stadium nicht prüfbar, daher für die Bestimmung irrelevant.','Weil das weiße Knollenblätterpilz-Ei rein weiß ist und einem weißen Stäubling besonders ähnelt, gilt umso strenger: vollständig halbieren, und NUR bei absolut homogenem weißem Innenfleisch ohne jede Lamellen-/Stiel-Silhouette und ohne Volva essen. Jeder Pilz-Umriss = Lebensgefahr (Amatoxine, Leberversagen). Im Zweifel zur Pilzkontrollstelle (VAPKO).','https://de.wikipedia.org/wiki/Kegelh%C3%BCtiger_Knollenbl%C3%A4tterpilz · https://123pilzsuche.de/daten/details/KegelhuetigerKnollenblaetterpilz.htm · https://www.first-nature.com/fungi/amanita-virosa.php · https://www.vetpharm.uzh.ch/giftdb/pflanzen/0013_bot.htm · https://www.pilzkurse.com/lycoperdon'),
('lycoperdon_perlatum','scleroderma_citrinum','mittel','{"Schnitt-Test ist entscheidend: Flaschenstaeubling jung innen rein weiss und homogen-weich; Kartoffelbovist schon jung mit graustichigem, dann violettschwarz marmoriertem, hartem Inneren.","Kartoffelbovist hat eine dicke (bis 5 mm), zaehe, harte Aussenschale mit grober, schorfig-felderiger Oberflaeche; Staeubling hat duenne, weiche Haut mit feinen pyramidenfoermigen Stacheln/Warzen, die spaeter abfallen.","Kartoffelbovist riecht unangenehm metallisch/gummiartig; Flaschenstaeubling jung unauffaellig mild-pilzig.","Kartoffelbovist sitzt fast stiellos knollig am Boden; Flaschenstaeubling hat einen deutlich abgesetzten, schlanken sterilen Stielteil (Birnen-/Flaschenform)."}','Kartoffelbovist gelbbraun, hart, grob schorfig-felderig, ohne echten abgesetzten Stiel; Flaschenstaeubling weiss-grau mit feinen pyramidalen Stacheln und deutlich abgesetztem Stielteil.','Kartoffelbovist unangenehm metallisch-gummiartig; Flaschenstaeubling jung mild-pilzig, unauffaellig.','Kartoffelbovist auf saurem, magerem Waldboden, mykorrhizal an Baeumen (Eiche, Buche, Birke); Flaschenstaeubling auf Wald- und Wiesenboeden in Nadel- und Laubwald, an Wegraendern.','Reifebestimmung statt Abwurf: Kartoffelbovist hat schon bei halbreifen Stuecken braunschwarze Sporenmasse im Inneren; junger Flaschenstaeubling im Schnitt noch komplett weiss ohne dunkle Sporenmasse.','JEDEN runden Bovist VOR dem Essen laengs komplett durchschneiden: Ist das Innere nicht durchgehend rein weiss und homogen (dunkel marmoriert, graustichig oder hartschalig), wegwerfen - das ist der giftige Kartoffelbovist.','123pilze, DGfM, toxinfo.org, pilzbuch-pilzwelten.de, GiftnotrufZentrale'),
('lycoperdon_perlatum','scleroderma_verrucosum','mittel','{"Der Duennschalige Kartoffelbovist hat - anders als der Dickschalige - einen deutlich ausgepraegten, gefurchten, sterilen Stielansatz mit Myzelstraengen, wodurch er dem gestielten Flaschenstaeubling aeusserlich aehnlicher und damit besonders verwechselbar ist.","Schnittfleisch des Kartoffelbovists wird schon jung graustichig bis dunkel marmoriert; Flaschenstaeubling jung rein weiss und homogen.","Kartoffelbovist-Schale lederzaeh, fein braunwarzig; Staeubling-Haut weich mit feinen, abfallenden pyramidalen Stacheln.","Kartoffelbovist riecht metallisch-unangenehm; junger Staeubling mild-pilzig."}','Duennschaliger Kartoffelbovist gelbbraun, feinwarzig, mit deutlich gefurchtem sterilem Stielansatz; Flaschenstaeubling weiss-grau mit feinen Stacheln und glattem, abgesetztem Stielteil.','Kartoffelbovist metallisch-unangenehm; Flaschenstaeubling jung mild-pilzig.','Duennschaliger Kartoffelbovist auf sandigen Boeden in Heide, Laub- und Nadelwald, oft an Wegraendern; Flaschenstaeubling in Waeldern und auf Wiesen.','Kartoffelbovist im Schnitt frueh dunkelbraun-sporig; junger Staeubling noch weisses Fleisch ohne dunkle Sporenmasse.','Jeden kugeligen Pilz laengs aufschneiden: dunkles, marmoriertes oder violettschwarzes Inneres heisst Kartoffelbovist - nie essen. Nur durchgehend rein weisses, homogenes Inneres ist sicher.','123pilze, DGfM, wien.gv.at Konsumentenschutz, mushroom-toxin.de, GiftnotrufZentrale'),
('macrolepiota_mastoidea','lepiota_brunneoincarnata','sehr_hoch_lebensgefahr','{"Zitzen-Riesenschirmling: Hut 6-12 cm mit markanter spitzer Zitze in der Mitte; Fleischrötlicher Schirmling: nur 2-5 cm","Zitzen-Riesenschirmling: verschiebbarer Ring; Giftschirmling: flüchtige, nicht verschiebbare faserige Ringzone","Zitzen-Riesenschirmling: Stiel höchstens fein/zart genattert (schwächer als beim Parasol); Giftschirmling: Stiel ungenattert, mit fleischbraunen Schuppengürteln","Zitzen-Riesenschirmling-Hut fein hellbraun beschuppt auf weisslichem Grund; Giftschirmling-Hut fleischrosa-braun, in konzentrische Schuppen aufgelöst","Fleischrötlicher Schirmling enthält tödliche Amatoxine; der Zitzen-Riesenschirmling ist essbar - weil der Grössenunterschied hier kleiner ist, ist diese Verwechslung besonders heikel"}','Der Zitzen-Riesenschirmling zeigt eine ausgeprägte spitze Mittelzitze und verschiebbaren Ring; der tödliche Schirmling bleibt deutlich kleiner mit fleischrosa-brauner Erscheinung und ungenattertem, schuppig gegürteltem Stiel.','Beide unauffällig bis leicht süsslich - Geruch trennt sie NICHT, niemals darauf verlassen.','Beide an grasigen Waldrändern, Wiesen und Parks - starke Überschneidung, daher nur über Grösse, spitze Zitze, Stielmerkmale und verschiebbaren Ring sicher trennbar.','Beide mit weissem Sporenpulver - kein Trennmerkmal.','Da der Grössenunterschied hier kleiner ist, gilt erst recht: nur Schirmlinge mit klar verschiebbarem Ring, spitzer Mittelzitze und Hut deutlich über 8 cm akzeptieren; im Zweifel jeden kleinen Schirmling stehen lassen.','123pilze, VAPKO, DGfM, GiftnotrufZentrale, Wikipedia (Zitzen-Riesenschirmling)'),
('marasmius_oreades','clitocybe_dealbata','hoch','{"Lamellen: Feldtrichterling gedrängt, am Stiel angewachsen bis kurz HERABLAUFEND — Nelkenschwindling weit entfernt stehend, ausgebuchtet angeheftet, NICHT herablaufend","Hut: Feldtrichterling kreidig-bleiweiss bis cremegelb, glatt/bereift, flach bis niedergedrückt — Nelkenschwindling lederfarben mit stumpfem Buckel, hygrophan","Stiel: Nelkenschwindling zäh-biegsam, knorpelig-faserig — Feldtrichterling faseriger und brüchiger","Reviving-Test: Nelkenschwindling lebt nach Trocknung wieder auf — Feldtrichterling nicht"}','Feldtrichterling: kleiner, kreidig-bleiweisser bis cremegelber, oft niedergedrückter Hut mit gedrängten herablaufenden Lamellen. Nelkenschwindling: lederbraun-gelber Hut mit Buckel, weit stehende Lamellen, deutlich zäherer Stiel.','Nelkenschwindling angenehm würzig (Gewürznelke/Bittermandel) — von ~25% genetisch nicht wahrnehmbar, daher kein Allein-Merkmal. Feldtrichterling mehlig bis geruchlos.','Wie C. rivulosa ein typischer Wiesen-/Rasenpilz an grasbewachsenen Stellen, ggf. in Hexenringen — exakt im Lebensraum des Nelkenschwindlings. Standort taugt nicht zur Unterscheidung.','Beide mit WEISSEM Sporenpulver — kein Trennmerkmal. Entscheidend bleiben Lamellenstellung und der zähe Stiel.','Muscarin wirkt schon in kleinen Mengen (Schweiss-, Speichel-, Tränenfluss nach 15-30 Min). Nie sammeln, wenn die Lamellen gedrängt am Stiel herablaufen — der essbare Nelkenschwindling hat IMMER weit stehende, nicht herablaufende Lamellen und einen zähen, biegsamen Stiel. Der Nelkengeruch ist nur eine Zusatz-Bestätigung.','https://en.wikipedia.org/wiki/Marasmius_oreades · https://en.wikipedia.org/wiki/Clitocybe_dealbata · https://www.pilzbuch-pilzwelten.de/nelkenschwindling/marasmius-oreades.html'),
('marasmius_oreades','clitocybe_phyllophila','hoch','{"Nelkenschwindling: Lamellen weit stehend, blass, NICHT herablaufend, Stiel zäh-biegsam (lässt sich verdrehen ohne zu brechen) — Bleiweißer Trichterling: Lamellen gedrängt und schwach herablaufend, Stiel brüchig.","Nelkenschwindling riecht würzig-süßlich (Nelke/Bittermandel); Bleiweißer Trichterling muffig-süßlich/parfümiert.","Weiße Trichterlinge (Clitocybe phyllophila und besonders die Wiesenarten C. rivulosa/dealbata) sind muscarinverdächtig/giftig — sie sind die klassische gefährliche Verwechslung weißhütiger Wiesenpilze.","Nelkenschwindling-Hut ledergelb-beige mit stumpfem Mittelbuckel und durchscheinend gerieftem Rand; weiße Trichterlinge glasig weiß bereift, oft niedergedrückt/trichterig.","Sicherheitsregel: Auf grasigen Standorten zusätzlich auf die gefährlicheren weißen Wiesen-Trichterlinge (C. rivulosa/dealbata) achten — nicht nur auf C. phyllophila."}','Nelkenschwindling ledergelb-beige mit Buckel und weit stehenden, nicht herablaufenden Lamellen; weiße Trichterlinge reinweiß-bereift mit gedrängten, (schwach) herablaufenden Lamellen.','Nelkenschwindling angenehm würzig (Nelke/Bittermandel); der Trichterling muffig-süßlich/parfümiert — Geruch allein ist nicht beweisend.','Nelkenschwindling auf Wiesen, Weiden und Rasen (oft in Hexenringen). Clitocybe phyllophila steht vorwiegend in der Laub-/Nadelstreu von Wäldern, Parks und Gärten; die eigentlich gefährlichen WEISSEN WIESEN-Trichterlinge (C. rivulosa/dealbata) teilen dagegen den Rasen-Standort des Nelkenschwindlings.','Nelkenschwindling weiß, Bleiweißer Trichterling ebenfalls weiß/creme — Sporenfarbe trennt hier NICHT. Daher Lamellenstellung (weit/nicht herablaufend) und Stielzähigkeit prüfen.','Auf Wiese/Rasen nur Pilze mit zäh-biegsamem, nicht brechendem Stiel und weit stehenden, NICHT herablaufenden Lamellen nehmen — jeder weiße Trichterling mit herablaufenden Lamellen (egal ob Wald- oder Wiesenart) bleibt konsequent stehen.','pilzkurse.com (Schweiz), pilzbuch-pilzwelten.de, 123pilze, DGfM'),
('marasmius_oreades','clitocybe_rivulosa','hoch','{"Lamellen (DAS Hauptmerkmal): Gifttrichterling hat gedrängt stehende, am Stiel kurz HERABLAUFENDE (dekurrente) Lamellen — Nelkenschwindling hat ENTFERNT (weit) stehende, am Stiel ausgebuchtet angeheftete, NICHT herablaufende Lamellen","Stiel: Nelkenschwindling-Stiel zäh, biegsam, knorpelig-faserig (lässt sich verdrehen ohne zu brechen) — Trichterling-Stiel brüchig","Hut: Trichterling bleiweiss/cremegrau, hygrophan, oft niedergedrückt/trichterig — Nelkenschwindling lederbräunlich-gelb mit stumpfem Buckel","Reviving-Test: Nelkenschwindling-Fruchtkörper leben nach dem Trocknen wieder auf (typisch für Schwindlinge) — Gifttrichterling nicht"}','Nelkenschwindling: bräunlich-gelber Hut mit stumpfem Buckel, weit stehende blasse Lamellen, zäher biegsamer Stiel. Gifttrichterling: bleiweiss-cremegrauer, oft niedergedrückter/trichteriger Hut, gedrängte herablaufende Lamellen.','Nelkenschwindling: angenehm würzig nach Gewürznelken/Bittermandel (Blausäure-Note) — ACHTUNG: ~25% der Menschen können diesen Geruch genetisch bedingt NICHT wahrnehmen, daher kein Allein-Merkmal. Gifttrichterling: mehlig bis geruchlos. Geruch nur als Zusatz-Bestätigung, nie als alleinigen Sicherheitsbeweis nutzen.','Beide wachsen am SELBEN Standort: Wiesen, Weiden, Rasen in Gärten/Parks, beide bilden Hexenringe — keine Trennung über den Standort möglich. Das erhöht die Verwechslungsgefahr massiv.','Beide haben WEISSES Sporenpulver — Sporenabwurf trennt diese beiden NICHT. Entscheidend bleibt die Lamellenstellung (herablaufend vs. weit/ausgebuchtet) und der zähe Stiel.','Goldene Regel auf der Wiese: Lamellen prüfen. Nelkenschwindling hat WEIT auseinanderstehende, NICHT herablaufende Lamellen und einen zähen, biegsamen Stiel. Sind die Lamellen gedrängt und laufen am Stiel herab — stehen lassen (Verdacht auf muscarinhaltigen Gifttrichterling). Der würzige Nelkengeruch ist nur eine Zusatz-Bestätigung (ein Viertel der Menschen riecht ihn nicht).','https://en.wikipedia.org/wiki/Marasmius_oreades · https://en.wikipedia.org/wiki/Clitocybe_rivulosa · https://www.pilzbuch-pilzwelten.de/nelkenschwindling/marasmius-oreades.html · https://www.pilzkurse.com/nelkenschwindling/'),
('marasmius_oreades','gymnopus_peronatus','gering','{"Brennender Rübling: Geschmack scharf-brennend pfeffrig, Lamellen eng stehend, in Wald-Laubstreu, Stielbasis striegelig-filzig","Nelkenschwindling: mild, angenehmer Geruch (würzig, mandelartig/Blausäure-Note), Lamellen breit und ENTFERNT stehend, wächst in Wiesen/Rasen (Hexenringe), zäher biegsamer Stiel","Nelkenschwindling-Hut mit deutlichem stumpfem Buckel, ledergelb-semmelfarben; Brennender Rübling gelbbraun-lederbraun ohne nelkigen Geruch","Brennender Rübling scharf/giftverdächtig-magenreizend – Nelkenschwindling klassischer milder Speisepilz"}','Der Nelkenschwindling hat breit-entfernt stehende Lamellen und einen gebuckelten ledergelben Hut; der Brennende Rübling enger stehende Lamellen und striegelige Stielbasis.','Nelkenschwindling riecht angenehm würzig-mandelartig; der Brennende Rübling riecht unauffällig bis essigartig (beim Reiben) und schmeckt brennend scharf.','Nelkenschwindling wächst auf Wiesen/Rasen in Hexenringen; der Brennende Rübling in Wald-Laub-/Nadelstreu – Standort hilft deutlich beim Trennen.','Beide mit weisslichem Sporenpulver – kein Trennmerkmal.','Wiesenstandort + entfernte Lamellen + Mandelgeruch = Nelkenschwindling; Waldstreu + scharf brennender Geschmack = giftverdächtiger Brennender Rübling. Geschmacksprobe ausspucken.','123pilze.de (Nelkenschwindling/Brennender Rübling), de.wikipedia.org/wiki/Nelkenschwindling, VAPKO, DGfM'),
('marasmius_oreades','inocybe_erubescens','sehr_hoch_lebensgefahr','{"Sporenpulver (ENTSCHEIDEND): Risspilz hat DUNKELBRAUNES Sporenpulver, Lamellen verfärben sich von weiss/creme über olivgrau-rosa zu fleckig-bräunlich — Nelkenschwindling hat WEISSES Sporenpulver und bleibend blasse Lamellen","Rötung: Risspilz rötet ziegelrot (Hut/Stiel/Fleisch, v.a. auf Druck und im Alter) — Nelkenschwindling rötet NICHT","Hut-Oberfläche: Risspilz kegelig-gebuckelt, radialfaserig und aufreissend/rissig (''Risspilz'') — Nelkenschwindling glatt, hygrophan, mit stumpfem Buckel","Geruch: Risspilz spermatisch/obstartig-unangenehm — Nelkenschwindling würzig nach Gewürznelken/Bittermandel"}','Risspilz: kegelig gebuckelter, radial aufgerissener Hut, weisslich und mit Zeit/Druck ziegelrot anlaufend, dunkelnde (olivrosa-bräunliche) Lamellen. Nelkenschwindling: glatter lederfarbener Hut mit stumpfem Buckel, blass bleibende weit stehende Lamellen.','Nelkenschwindling angenehm würzig (Gewürznelke/Bittermandel; von ~25% nicht wahrnehmbar). Ziegelroter Risspilz schwach obstartig, im Alter unangenehm süsslich-spermatisch. Geruch nur als Zusatz, nie allein.','Ziegelroter Risspilz wächst kalkliebend vor allem in Laub-/Mischwäldern, Parkanlagen und unter Gebüsch (Mykorrhiza mit Buche/Linde), teils auch auf Rasenflächen — nicht primär offene Wiese wie der Nelkenschwindling. Standort hilft, ist aber KEIN alleiniges Sicherheitsmerkmal (auch auf Rasen/Parkrasen möglich).','ENTSCHEIDEND und lebensrettend: Risspilz hat dunkelbraunes Sporenpulver — der Nelkenschwindling weisses. Ein Sporenabwurf trennt die beiden eindeutig.','Sporenpulver-Check als Lebensretter: weiss = Nelkenschwindling möglich, braun = NIE essen. Zusätzlich entlarven den tödlichen Risspilz: rissig-radialfaseriger Hut, ziegelrotes Anlaufen (auf Druck) und der spermatische Geruch. Muscarin — tödliche Menge schon ab ~40-500g Frischpilz.','https://de.wikipedia.org/wiki/Inocybe_erubescens · https://www.pilzbuch-pilzwelten.de/ziegelroter-risspilz/inosperma-erubescens.html · https://fundkorb.de/pilze/inocybe-erubescens-ziegelroter-risspilz'),
('marasmius_oreades','inocybe_geophylla','hoch','{"Nelkenschwindling: Lamellen weisslich-creme, dick und entfernt; Erdblättriger Risspilz: Lamellen jung weisslich, bald tonig-/tabakbraun","Nelkenschwindling: Hut ledergelb-hellbraun mit stumpfem Buckel; weisse Form des Risspilzes: rein weiss bis cremefarben, seidig-faserig mit spitzem Buckel","Nelkenschwindling: Stiel zäh-biegsam (lässt sich um den Finger biegen); Risspilz: Stiel brüchig, dünn","Erdblättriger Risspilz enthält viel Muscarin (Schweiss, Speichel, Tränen 15-30 Min nach Verzehr); Nelkenschwindling essbar"}','Die rein weiss-seidige, spitz gebuckelte Hutoberfläche des Erdblättrigen Risspilzes unterscheidet sich vom ledergelb-bräunlichen, stumpf gebuckelten Nelkenschwindling.','Nelkenschwindling: nach Bittermandel; Erdblättriger Risspilz: spermatisch-erdig.','Beide an Wiesen-, Weg- und Waldrändern in kurzem Gras; Habitat trennt nicht, daher Lamellenfarbe, Geruch und Stielkonsistenz prüfen.','Nelkenschwindling: WEISSES Sporenpulver; Erdblättriger Risspilz: tabak-/ockerbraunes Sporenpulver - sicheres Trennmerkmal.','Kleine weisse/hellbraune Wiesenpilze nur essen, wenn das Sporenpulver WEISS bleibt; jeder seidig-weisse Hut mit braunem Sporenstaub und spermatischem Geruch ist ein Risspilz - verwerfen.','123pilze, VAPKO, DGfM, GiftnotrufZentrale'),
('marasmius_oreades','inocybe_rimosa','hoch','{"Nelkenschwindling: Lamellen weisslich-creme, dick, entfernt stehend; Risspilz: Lamellen bald tonig-graubraun, dichter","Nelkenschwindling: Hut hellbraun-ledergelb, glatt mit stumpfem Buckel, zäh-biegsamer Stiel (lässt sich biegen ohne zu brechen); Risspilz: Hut radial AUFGERISSEN, kegelig, Stiel brüchig","Nelkenschwindling riecht angenehm nach Bittermandel; Risspilz riecht spermatisch-erdig","Risspilze enthalten Muscarin - in Menge gefährlich; Nelkenschwindling ist essbar (durchgaren)"}','Der zähe, biegsame Stiel und der glatte ledergelbe Hut des Nelkenschwindlings unterscheiden ihn vom rissig-kegeligen, brüchigen Risspilz.','Nelkenschwindling: angenehm nach Bittermandel; Risspilz: spermatisch-unangenehm.','Beide auf Wiesen und in kurzem Gras; der Nelkenschwindling wächst oft in Hexenringen, aber das Habitat trennt sie nicht zuverlässig.','Nelkenschwindling: WEISSES Sporenpulver; Kegeliger Risspilz: tabak-/graubraunes Sporenpulver - sicheres Trennmerkmal.','Auf der Wiese nur Pilze mit weisslichen Lamellen, weissem Sporenpulver und biegsam-zähem Stiel nehmen; jeder rissige, braunsporige, spermatisch riechende Hut ist ein Giftrisspilz - sofort verwerfen.','123pilze, VAPKO, DGfM, Pilzforum.eu, Stadt Wien Konsumentenschutz'),
('marasmius_oreades','lepiota_cristata','mittel','{"Lepiota cristata ist giftig (Magen-Darm-Stoerungen, in der Gattung gilt jeder kleine Schirmling als amatoxin-verdaechtig); der Nelkenschwindling ist essbar","Lepiota cristata riecht unangenehm scharf nach Leuchtgas/verbranntem Gummi; der Nelkenschwindling riecht angenehm nach Bittermandel/Blausaeure bis suesslich","Lepiota cristata hat einen (vergaenglichen) Ring und einen bruechigen Stiel; der Nelkenschwindling hat KEINEN Ring und einen zaehen, biegsamen Stiel","Lepiota cristata: weisslicher Hut mit rotbraunen, konzentrisch gestellten Schuppen und dunklem Scheibchen in der Mitte; Nelkenschwindling: glatter ocker- bis semmelfarbener Buckelhut ohne Schuppen","Lepiota cristata mit dicht stehenden, freien, weissen Lamellen; Nelkenschwindling mit dicken, weit stehenden, ausgebuchtet angewachsenen Lamellen"}','Lepiota cristata weisslicher Hut mit rotbraunem konzentrischem Schuppenkranz, dunklem Zentrum und Stielring; Nelkenschwindling glatter ockerfarbener Buckelhut ohne Schuppen und ohne Ring.','Lepiota cristata stechend unangenehm nach Leuchtgas/verbranntem Gummi; Nelkenschwindling angenehm nach Bittermandel/Blausaeure - der Leuchtgasgeruch ist ein klares Warnsignal.','Beide an grasigen Stellen, Wegraendern, in Parks und auf Wiesen - derselbe Lebensraum beguenstigt die Verwechslung.','Beide weisses (bei Lepiota cristata gelegentlich minimal cremefarbenes) Sporenpulver - kein verlaessliches Trennmerkmal.','Kleine Schirmlinge mit Ring auf Wiesen grundsaetzlich stehen lassen; der ringlose, zaehe, verdrehbare Stiel ist das einzige verlaessliche Merkmal des Nelkenschwindlings - fehlt er, nicht sammeln.','123pilze (Stink-Schirmling), pilzbuch-pilzwelten, Wikipedia Stink-Schirmling, DGfM'),
('marasmius_oreades','lepiota_helveola','sehr_hoch_lebensgefahr','{"Lepiota helveola ist TOEDLICH giftig (Amatoxine -> Leberversagen); der Nelkenschwindling ist ein guter Speisepilz - die Verwechslung kann toedlich enden","Nelkenschwindling hat einen auffallend zaehen, biegsam-elastischen, vollen Stiel (laesst sich verdrehen ohne zu brechen); kleine Giftschirmlinge haben einen zerbrechlichen, leicht brechenden Stiel","Lepiota helveola besitzt einen (oft vergaenglichen) haeutigen Ring am Stiel; der Nelkenschwindling hat NIE einen Ring","Nelkenschwindling hat dicke, weit stehende, am Stiel ausgebuchtet angewachsene, cremefarbene Lamellen; Lepiota helveola dicht stehende, freie, weisse Lamellen","Lepiota helveola: feinschuppiger fleischrosa bis braunroetlicher Hut mit dunklerem Zentrum; Nelkenschwindling: glatter ocker- bis semmelfarbener Hut mit stumpfem Buckel"}','Nelkenschwindling glatter ockerfarbener Buckelhut, ringloser zaeher Stiel, dicke weit stehende Lamellen; Lepiota helveola feinschuppiger fleischroetlicher Hut mit Stielring und dicht stehenden freien Lamellen.','Nelkenschwindling riecht angenehm nach Blausaeure/Bittermandel bis suesslich (HCN + Benzaldehyd, von ca. einem Viertel der Menschen nicht wahrnehmbar); kleine Giftschirmlinge riechen unauffaellig bis leicht unangenehm - der Geruch ist KEIN sicheres Trennmerkmal.','Beide auf Wiesen, Rasen, Weiden und in Parks - identischer Lebensraum, genau das macht die Verwechslung so gefaehrlich.','Nelkenschwindling weisses Sporenpulver, Lepiota helveola ebenfalls weiss - kein Trennmerkmal; auf Ring, freie Lamellen und bruechigen Stiel achten.','Kleine Schirmlinge (Lepiota) mit Hut unter ca. 8 cm NIE essen - mehrere Arten sind toedlich. Auf der Wiese keinen kleinen, geringten, bruechigen Pilz sammeln; im Zweifel komplett stehen lassen.','123pilze (Fleischroetlicher Schirmling), Wikipedia Lepiota helveola, DGfM, GiftnotrufZentrale (Notruf Schweiz 145)'),
('marasmius_oreades','panaeolina_foenisecii','mittel','{"Nelkenschwindling: zaeher, biegsamer Stiel, der sich verdrehen laesst ohne zu brechen; Heuduengerling hat bruechigen, hohlen Stiel.","Nelkenschwindling: Lamellen weisslich-cremefarben, frei, breit/entfernt stehend; Heuduengerling hat fleckig-graubraune, gesprenkelte (marmorierte) Lamellen durch ungleich reifende Sporen.","Nelkenschwindling: heller ledergelb-semmelfarbener Hut mit Buckel, hygrophan; Heuduengerling kleiner, dunkler graubraun, ohne klaren Buckel.","Sporenpulver Nelkenschwindling weiss, Heuduengerling dunkel purpurbraun-schwaerzlich — der entscheidende sichere Trennschritt.","Nelkenschwindling riecht oft nach Bittermandel/Blausaeure oder wuerzig; Heuduengerling nahezu geruchlos."}','Nelkenschwindling hat entfernt stehende, weisse, freie Lamellen und einen gebuckelten ledergelben Hut; der Heuduengerling zeigt eng-fleckig marmorierte, dunkelbraune Lamellen.','Nelkenschwindling: oft charakteristischer Bittermandel-/Marzipan- oder Wuerzgeruch (nicht immer deutlich ausgepraegt). Heuduengerling: nahezu geruchlos.','Beide wachsen auf Wiesen und Rasen; der Heuduengerling bevorzugt geduengte, frisch gemaehte Rasen, der Nelkenschwindling oft in Hexenringen auf magereren Wiesen — Habitat trennt sie NICHT zuverlaessig.','Nelkenschwindling: weisses Sporenpulver. Heuduengerling: dunkel purpur-/schwaerzlichbraunes Sporenpulver — sicherstes Unterscheidungsmerkmal.','Im Rasen wachsende kleine Braunkappen IMMER aussporen lassen — weisses Sporenpulver = moeglicher Nelkenschwindling, dunkelbraunes = Duengerling, dann nie essen. Den Geruch nie allein als Beweis nehmen.','123pilze, DGfM, VAPKO, MykoWeb'),
('marasmius_oreades','panaeolus_cinctulus','mittel','{"Nelkenschwindling: zaeher, elastischer Stiel; Panaeolus cinctulus hat duenneren, bruechigeren, hohlen Stiel.","Nelkenschwindling: weisse, breit-frei stehende Lamellen; Panaeolus cinctulus hat creme bis grau und zuletzt schwarz werdende, gescheckte Lamellen.","Hut des Nelkenschwindlings ledergelb mit Buckel, hygrophan; Panaeolus cinctulus dunkler rotbraun (feucht) mit oft dunklerem, geguerteltem Hutrand, beim Abtrocknen cremeweiss aufhellend.","Sporenpulver Nelkenschwindling weiss, Panaeolus cinctulus tiefschwarz — eindeutige Trennung.","Panaeolus cinctulus waechst bevorzugt auf Mist, Kompost und stark geduengten Rasen; enthaelt Psilocybin (blauende Druckstellen moeglich)."}','Panaeolus cinctulus zeigt grau bis schwarz werdende, gescheckte Lamellen und einen feucht rotbraunen, oft geguertelten Hutrand; der Nelkenschwindling bleibt einfarbig ledergelb mit weissen Lamellen.','Nelkenschwindling oft nach Bittermandel/wuerzig; Panaeolus cinctulus unauffaellig pilzig.','Panaeolus cinctulus waechst auf Mist, Kompost und geduengtem Rasen, der Nelkenschwindling in Hexenringen auf Wiesen/Rasen — Ueberschneidung auf geduengten Rasenflaechen.','Nelkenschwindling weiss, Panaeolus cinctulus tiefschwarz.','Kleine Rasen-/Mistpilze mit grauen, schwarz werdenden Lamellen nie sammeln — schwarzes Sporenpulver schliesst den essbaren Nelkenschwindling sicher aus.','123pilze, DGfM, VAPKO, DoubleBlind'),
('marone','flockenstieliger_hexenpilz','gering','{"Beide Speisepilze Hexenpilz blaut SCHNELLER","Hexenpilz rote Pünktchen Stiel"}','Marone: braun leichtes Blauen. Hexenpilz: braun schnell starkes Blauen rote Punkte.','—','Beide Wald','—','Beide essbar. Hexenpilz MUSS gekocht werden 15+ min.','VAPKO Schweiz'),
('marone','tricholoma_ustale','gering','{"Entscheidend: Marone (essbar) hat ROEHREN/Poren unter dem Hut, der Brandige Ritterling hat LAMELLEN - sofort unterscheidbar durch Blick auf die Hutunterseite.","Marone ist ein Roehrling (Boletales) mit dickem Stiel und gelblichen, auf Druck blauenden Roehren; ustale ist ein Blaetterpilz.","Aehnlichkeit besteht nur aus der Ferne ueber den braunen, bei Feuchte schmierigen Hut - so kann der ustale-Hut von oben an eine Marone erinnern.","Marone-Fleisch schmeckt mild-nussig, ustale bitterlich.","Roehren lassen sich bei der Marone als Schicht abziehen - bei Ritterlingen unmoeglich (echte Lamellen)."}','Marone hat Roehren/Schwamm unter dem Hut, der Brandige Ritterling Lamellen - die Hutunterseite klaert die Verwechslung sofort.','Marone mild-pilzig, ustale schwach mehlig - kein primaeres Trennmerkmal.','Marone bei Fichte/Kiefer auf saurem Boden, ustale vorwiegend im Laubwald (Buche/Eiche).','Marone olivbraunes Sporenpulver (Roehrling), ustale weisses Sporenpulver (Blaetterpilz) - eindeutig verschieden.','Immer die Hutunterseite pruefen: Roehren = Roehrling, Lamellen = Blaetterpilz. Ein Lamellenpilz mit braunem Schmierhut ist nie eine Marone.','123pilze, pilzbuch-pilzwelten.de, VAPKO'),
('mitrophora_semilibera','gyromitra_gigas','hoch','{"Halbfreie Morchel: kleiner glockig-kegeliger, deutlich gewabter Hut, der nur etwa zur unteren Hälfte am langen, hohlen, weisslichen Stiel angewachsen ist (Hutrand frei abstehend)","Riesenlorchel: massiger, hirnartig gewundener Hut ohne Waben, kurzer dicker Stiel, innen von mehreren Hohlräumen durchzogen","Halbfreie Morchel in Hut und Stiel durchgehend hohl; Lorchel-Stiel kammrig/von Hohlräumen durchzogen","WICHTIG: Halbfreie Morchel nur gut gegart geniessbar (roh unverträglich). Riesenlorchel selbst enthält kaum Gyromitrin, ist aber von der tödlichen Frühjahrslorchel kaum zu trennen – darum jeden gehirnartigen Fund meiden"}','Halbfreie Morchel zeigt einen kleinen gewabten Glockenhut mit frei abstehendem Rand auf langem schlankem Stiel; die Riesenlorchel einen grossen wulstigen Gehirn-Hut auf kurzem dickem Stiel.','Kein zuverlässiges Geruchs-Trennmerkmal.','Beide Frühlingspilze; Halbfreie Morchel auf kalkreichen Böden/Auwald, Riesenlorchel als Holzsaprobiont an morschen Stümpfen – Habitat trennt nicht sicher.','Beide mit hellem Sporenpulver (Schlauchpilze) – kein Trennmerkmal.','Auf Waben (Morchel) vs. gehirnartige Windungen (Lorchel) achten und immer längs aufschneiden. Frühlings-''Morchel'' nur sammeln, wenn sie eindeutig wabig und innen ein durchgehender Hohlraum ist; gewundene Lorcheln liegen lassen.','123pilze.de (Halbfreie Morchel/Riesenlorchel), de.wikipedia.org/wiki/Riesen-Lorchel, VAPKO'),
('mitrophora_semilibera','helvella_crispa','mittel','{"Halbfreie Morchel: gewabter glockig-kegeliger Hut (echte Kammern), Hut und langer Stiel komplett hohl, blass weisslich-ocker","Herbstlorchel: sattel-/lappig gewundener, mehrlappiger Hut OHNE Waben, weisslich-creme, Stiel tief längsgefurcht/rippig und gekammert (nicht ein glatter Hohlraum)","Herbstlorchel enthält Gyromitrin → roh giftig; nicht als unbedenklichen Speisepilz behandeln","Erscheinungszeit: Halbfreie Morchel im Frühling, Herbstlorchel v.a. Sommer–Spätherbst (Juli–November)"}','Halbfreie Morchel hat einen wabig-gegrubten Glockenhut; die Herbstlorchel einen wabenlosen, sattelförmig gefalteten Lappenhut auf rippig-kammrigem Stiel.','Beide unauffällig pilzig – kein verlässliches Trennmerkmal.','Halbfreie Morchel im Frühjahr (Auwald/kalkhaltig); Herbstlorchel v.a. Sommer–Herbst in Laub-/Mischwald an Wegrändern und Waldrändern – Jahreszeit hilft trennen.','Beide Ascomyceten mit hellem, creme-weisslichem Sporenpulver – kein Trennmerkmal.','Wabig = Morchel-Kandidat; sattel-/lappenförmig ohne Waben = Lorchel = liegen lassen. Lorcheln nicht als Speisepilz behandeln.','123pilze.de (Herbstlorchel), de.wikipedia.org/wiki/Herbst-Lorchel, VAPKO, DGfM'),
('morchelchampignon','gyromitra_gigas','hoch','{"Speise-Morchel: Hut wabig-grubig mit echten Kammern; Hut UND Stiel bilden EINEN durchgehenden Hohlraum von der Stielbasis bis zur Hutspitze (Längsschnitt zeigt gemeinsamen Hohlkörper)","Riesenlorchel: Hut hirnartig-gewunden, wulstig-gefaltet (KEINE wabigen Gruben); Stiel innen von mehreren Hohlräumen/Kammern durchzogen, nicht ein einziger glatter Hohlraum","WICHTIG: Die Gefahr ist NICHT, dass Gyromitra gigas selbst stark giftig ist (sie enthält nach neuerer Forschung kaum bis kein Gyromitrin), sondern dass sie von der TÖDLICHEN Frühjahrslorchel (Gyromitra esculenta) kaum sicher zu trennen ist – darum gilt jeder hirnartig-gewundene Lorchel-Fund als zu meiden","Hutrand der Morchel ist am Stiel angewachsen; Lorchel-Hut ist wulstig aufgeblasen und hängt teils frei über","Morchel-Wabenwände gleichmässig gerippt; Lorchel-Oberfläche unregelmässig walnusskern-/gehirnartig gefurcht"}','Speise-Morchel hat eine regelmässig wabig-gegrubte Hutoberfläche, die Riesenlorchel eine unregelmässig hirn-/walnussartig gewundene, wulstig aufgeblähte Oberfläche ohne echte Waben.','Beide eher unauffällig pilzig; Geruch trennt sie NICHT zuverlässig.','Speise-Morchel im Frühling auf kalkreichen Böden; Riesenlorchel ein Frühlings-Holzsaprobiont an morschen Stümpfen, vergrabenem Holz und Rindenmulch (oft Nadelholz). Erscheinungszeit überlappt – Habitat trennt nicht sicher.','Beide Schlauchpilze (Asci) mit blassem, cremefarbenem Sporenpulver – nicht zur Unterscheidung geeignet.','Längs durchschneiden: Echte Morchel ist EIN durchgehender Hohlraum von der Spitze bis zur Stielbasis und wabig. Alles Hirnartig-Gewundene mit gekammertem/von Hohlräumen durchzogenem Stiel liegen lassen – nicht weil dieser Fund sicher tödlich ist, sondern weil man tödliche Lorchel-Arten nicht zuverlässig ausschliessen kann. Lorcheln nie roh. Im Zweifel: Tox Info Suisse 145.','123pilze.de (Riesenlorchel/Speisemorchel), de.wikipedia.org/wiki/Riesen-Lorchel, Dirks et al. (Gyromitra-gigas-Komplex, Gyromitrin-Verteilung), VAPKO, DGfM, Tox Info Suisse'),
('morchelchampignon','helvella_crispa','mittel','{"Speise-Morchel: rundlich-eiförmiger, wabig-gegrubter Hut; Hut und Stiel bilden einen durchgehenden Hohlraum","Herbstlorchel: weisslicher, sattel-/lappenförmig gefalteter Hut ohne Waben; Stiel tief längsrippig-gefurcht mit Hohlkammern","Herbstlorchel ist gyromitrinhaltig/roh giftig, kein unbedenklicher Speisepilz; Morchel nur gegart essbar (roh unverträglich)","Morchel-Oberfläche besteht aus klaren Waben; Lorchel-Oberfläche aus glatten gewundenen Lappen"}','Die Speise-Morchel zeigt eine echte Wabenstruktur; die Herbstlorchel einen wabenlosen, weissen, sattelartig gelappten Hut und einen markant gerippt-gekammerten Stiel.','Kein zuverlässiges Geruchs-Trennmerkmal.','Speise-Morchel v.a. Frühling auf kalkreichen Böden; Herbstlorchel v.a. Sommer–Herbst an Waldwegen/Waldrändern in Laub-/Mischwald – Jahreszeit trennt meist.','Beide mit hellem Sporenpulver – kein praktisches Trennmerkmal.','Nur wabige Hüte mit innen durchgehendem Hohlraum als Morchel anerkennen. Weisse Sattel-/Lappenformen mit gefurchtem Kammerstiel sind Lorcheln – nicht essen.','123pilze.de (Herbstlorchel/Speisemorchel), de.wikipedia.org/wiki/Herbst-Lorchel, VAPKO'),
('morchelchampignon','verpa_bohemica','mittel','{"Bei der Speisemorchel ist der Hut über die ganze Länge mit dem Stiel verwachsen (komplett hohle Einheit); bei der Verpel hängt das Käppchen glockenförmig frei und ist nur ganz oben an der Stielspitze angewachsen","Speisemorchel-Hut zeigt tiefe, wabig-grubige Vertiefungen; Verpa bohemica hat nur längs-/quergerunzelte, gehirnartige Falten ohne echte Waben","Längsschnitt entscheidet: Speisemorchel durchgehend hohl von Hut bis Stielbasis; Verpel-Stiel ist innen wattig-flockig gefüllt/gekammert","Beide nur gut durchgegart und nicht roh essen — Verpa bohemica ist roh und ungenügend gekocht magen-darm-giftig"}','Speisemorchel: tief wabiger, vollständig mit dem Stiel verwachsener Hut; Verpel: glatt-runzeliges, frei herabhängendes Fingerhut-Käppchen.','Beide unauffällig pilzig-angenehm — der Geruch hilft hier NICHT zur Trennung, nur Bau und Schnitt.','Beide im Frühling; Verpa bohemica oft etwas früher unter Eschen/Pappeln in Auwäldern.',NULL,'Immer längs aufschneiden: ist das Käppchen nur an der Spitze angewachsen und hängt sonst frei, ist es KEINE echte Morchel — und niemals roh verzehren.','123pilze (Böhmische Verpel), pilzbuch-pilzwelten.de, Pilzkurse.com Schweiz'),
('morchella_elata','fliegenpilz-grosspilz','sehr_hoch_lebensgefahr','{"Spitzmorchel: wabig-grubiger Hut, Hut+Stiel komplett hohl","Frühjahrslorchel: hirnartig gewunden, Stiel gekammert (nicht hohl), Gyromitrin (hochgiftig)"}','Morchel wabig/gleichmässig vs. Lorchel gehirnartig-unregelmässig.','beide unspezifisch','beide Frühling, Brandstellen/Auwald/Nadelwald','kein Lamellensporenpulver (Schlauchpilze)','Frühjahrslorchel ist hochgiftig (potenziell tödlich). Längsschnitt: durchgehend hohl (Morchel) vs. wattig-kammerig (Lorchel).','awl.ch / giz-nord.de'),
('morchella_elata','gyromitra_gigas','hoch','{"Spitzmorchel: Hut kegelig-zugespitzt mit längs ausgerichteten, scharf abgegrenzten Waben/Kammern; Hut und Stiel bilden einen durchgehenden Hohlraum","Riesenlorchel: Hut rundlich-knollig, hirnartig gewunden, KEINE kegelige Spitze und keine echten Waben","Riesenlorchel-Stiel innen von mehreren Hohlräumen durchzogen; Spitzmorchel-Stiel ein durchgehender Hohlraum","WICHTIG: Gyromitra gigas selbst enthält nach neuerer Forschung kaum bis kein Gyromitrin – kritisch ist die Verwechselbarkeit mit der tödlichen Frühjahrslorchel (G. esculenta); deshalb alle Lorchel-Funde meiden"}','Spitzmorchel ist hoch-kegelig mit länglichen, leiterartig angeordneten dunklen Rippen; Riesenlorchel ist gedrungen-rundlich und gehirnartig gefaltet.','Geruch beider Arten unspezifisch pilzig – kein Trennmerkmal.','Spitzmorchel im Frühling auf gestörten/kalkreichen Böden und Rindenmulch; Riesenlorchel im Frühling als Holzsaprobiont an morschen Stümpfen/vergrabenem Holz – Überschneidung im Habitat möglich.','Beide Ascomyceten mit hellem Sporenstaub – kein praktisches Trennmerkmal.','Nur kegelige Hüte mit echten Waben UND einem durchgehenden Hohlraum (Längsschnitt) als Morchel akzeptieren. Gehirnartig gewunden mit von Hohlräumen durchzogenem Stiel = Lorchel = liegen lassen, weil tödliche Lorchel-Arten nicht sicher auszuschliessen sind.','123pilze.de (Spitzmorchel/Riesenlorchel), de.wikipedia.org/wiki/Riesen-Lorchel, pilzkurse.com, VAPKO, DGfM'),
('morchella_elata','verpa_bohemica','mittel','{"Spitzmorchel hat einen kegelig-spitzen, längs gerippten und mit dem Stiel komplett verwachsenen Hut mit echten Wabenkammern; Verpa bohemica trägt ein rundliches, nur an der Spitze angewachsenes, frei hängendes Käppchen","Spitzmorchel ist über die ganze Höhe hohl (Hut + Stiel eine Kammer); Verpel-Stiel innen wattig-watteflockig gefüllt","Hutoberfläche der Spitzmorchel netzartig-wabig mit längsverlaufenden Rippen; Verpel nur unregelmässig gehirnartig gerunzelt","Verpa bohemica roh/ungenügend gekocht magen-darm-giftig — wie alle Morcheln nur gut durchgegart geniessen"}','Spitzmorchel: spitzkegeliger, voll verwachsener Wabenhut; Verpel: stumpf-rundliches, frei herabhängendes runzeliges Käppchen.',NULL,'Spitzmorchel an Holzhäckseln/Brandstellen/in Gärten; Verpa bohemica eher in feuchten Auwäldern unter Esche/Pappel.',NULL,'Längsschnitt-Regel: nur wenn der Hut auf ganzer Länge mit dem Stiel verwächst und durchgehend hohl ist, liegt eine echte Morchel vor.','123pilze, Fungiversum.de, Entoloma.de (Verpa bohemica)'),
('paralepista_flaccida','ampulloclitocybe_clavipes','mittel','{"Fuchsiger Trichterling: tief trichterig vertiefter, fuchsig orange-rotbrauner (stark hygrophaner) Hut und schlanker, NICHT keulig verdickter Stiel; clavipes mit weissgrau-graubraunem Hut und keulig aufgeblasener Stielbasis.","Fuchsiger oft bueschelig/reihig in Laubstreu und Nadelmulch wachsend; clavipes eher einzeln bis gesellig.","Lamellen beim Fuchsigen sehr dicht stehend, gegabelt und weit herablaufend, weisslich bis ockergelblich; clavipes-Lamellen weisslich, weit herablaufend.","clavipes mit Alkohol giftig (Coprin-Syndrom); der Fuchsige ist gegart essbar (groessere Mengen koennen schwer verdaulich sein)."}','Fuchsig orange-rotbrauner, stark trichteriger Hut und schlanker Stiel beim Fuchsigen vs. weissgrau-graubrauner Hut und keulig geschwollene Stielbasis bei clavipes.','Fuchsiger Trichterling unauffaellig bis leicht suesslich; clavipes schwach obstartig.','Fuchsiger oft in dicker Nadel-/Laubstreu bueschelig; clavipes in Misch- und Nadelwaeldern.','Beide cremeweissliches Sporenpulver; nicht zuverlaessig trennend.','Stielbasis pruefen: keulig-schwammig aufgeblasen deutet auf clavipes, nicht in den Korb, nie mit Alkohol.','pilzbuch-pilzwelten.de (Fuchsiger Trichterling), 123pilze'),
('parasol','amanita_pantherina','sehr_hoch_lebensgefahr','{"Parasol-Ring BEWEGLICH Panther-Ring fest","Parasol natterzelter Stiel Panther weiss-glatt","Panther hat Knolle in 2-3 Wülsten"}','Parasol: hellbrauner Hut natterzelter Stiel. Panther: braun mit weissen Tupfen weisser Stiel mit Knollen.','Parasol: nussig angenehm. Panther: rettichartig.','Parasol: Wiesen Waldrand. Panther: Laubwald.','Beide weiss.','PARASOL-Test: Ring beweglich-verschiebbar Stiel natterzelt. Bei Tupfen NIEMALS essen.','VAPKO Schweiz'),
('parasol','chlorophyllum_brunneum','hoch','{"Parasol: genatterter (schlangenhautartiger) Stiel, verschiebbarer Doppelring, Fleisch rötet NICHT","Gift-Safranschirmling: glatter Stiel, gerandete Knolle, Fleisch/Lamellen verfärben safranrot"}','Stiel-Natterung (Parasol ja) + Rötung (Gift-Safranschirmling ja) + Knolle.','beide unspezifisch','Parasol Wald/Wiese; Gift-Safranschirmling oft Kompost/Garten','beide weiss-creme','Magen-Darm-Gift. Genatterter Stiel + keine Rötung = Parasol; glatter Stiel + safranrote Verfärbung = Finger weg.','de.wikipedia.org / tintling.com'),
('parasol','lepiota_brunneoincarnata','sehr_hoch_lebensgefahr','{"Parasol ist gross: Hut 10-30 cm; Fleischrötlicher Schirmling klein: Hut nur 2-5 cm - GRÖSSE ist das erste Warnsignal","Parasol hat einen DOPPELTEN, frei verschiebbaren Ring am Stiel; der Giftschirmling hat nur eine flüchtige, faserige, NICHT verschiebbare Ringzone","Parasol-Stiel deutlich genattert (schlangenhautartig gebändert); Giftschirmling-Stiel mit fleischbräunlich-faserigen Schuppengürteln, ohne Natterung","Parasol-Hut mit grossen, groben braunen Schuppen auf hellem Grund + Buckel; Giftschirmling-Hut fein fleischbraun-rosa schuppig, klein","Fleischrötlicher Schirmling enthält Amatoxine (wie Knollenblätterpilz) - tödlich, schon eine kleine Menge schädigt die Leber irreversibel"}','Der Parasol ist gross mit deutlich genattertem Stiel und doppeltem verschiebbarem Ring; der tödliche Schirmling bleibt klein (unter 5 cm) mit fleischrosa-brauner, fein schuppiger Hutoberfläche und ungenattertem Stiel.','Parasol riecht mild-nussig; der Giftschirmling süsslich-obstartig - Geruch ist KEIN sicheres Trennmerkmal, niemals darauf verlassen.','Parasol an Waldrändern/Wiesen; der Giftschirmling an warmen, sandig-grasigen Plätzen, Parks und Wegrändern - Überschneidung möglich.','Beide haben WEISSES Sporenpulver - das Sporenpulver trennt sie NICHT, daher zwingend Grösse, Stielnatterung und doppelten verschiebbaren Ring prüfen.','Schirmlinge nur als Parasol akzeptieren, wenn der Hut deutlich über 10 cm misst UND der Stiel genattert ist UND der Ring doppelt und verschiebbar ist - kleine Schirmlinge unter 8-10 cm grundsätzlich NIE essen.','123pilze, VAPKO, DGfM, GiftnotrufZentrale, Wikipedia (Lepiota brunneoincarnata)'),
('pluteus_cervinus','megacollybia_platyphylla','gering','{"Rehbrauner Dachpilz (essbar) hat ROSA Sporenpulver und im Alter rosa Lamellen, frei am Stiel; Breitblättriger Rübling hat WEISSES Sporenpulver und weisse, am Stiel angewachsene Lamellen","Breitblättriger mit auffällig groben weissen Rhizomorphen (Myzelsträngen) am Stielgrund; Dachpilz ohne solche Stränge","Lamellen des Breitblättrigen sehr breit und entfernt stehend; Dachpilz dichter","Dachpilz wächst meist einzeln auf Holz, Breitblättriger an Holz/Wurzeln mit Strängen"}','Dachpilz mit rosa Lamellen (reif) und freier Lamellenanheftung; Breitblättriger mit weissen, breiten, angewachsenen Lamellen und weissen Rhizomorphen am Grund.','Beide unauffällig-pilzig, kein Trennmerkmal.','Beide an/auf morschem Laubholz; der Breitblättrige mit auffälligen weissen Myzelsträngen am Stielfuss.','Dachpilz rosa, Breitblättriger Rübling weiss — DAS entscheidende Trennmerkmal.','Sporenabwurf machen: rosa = Dachpilz, weiss = Breitblättriger Rübling. Der Breitblättrige gilt als giftig/unbekömmlich (Magen-Darm) und gehört nicht in den Korb.','123pilze, DGfM, SwissFungi'),
('pluteus_cervinus','pluteus_salicinus','mittel','{"Rehbrauner Dachpilz: warm rehbrauner bis dunkelbrauner, oft radialfaseriger Hut; Graugruener Dachpilz blasser grau bis graugruenlich/blaeulichgrau, dunkler zur Hutmitte.","Graugruener Dachpilz verfaerbt sich bei Verletzung/Druck oft blaeulich-gruenlich (besonders Stielbasis) — Psilocybin-Indiz; Rehbrauner Dachpilz blaut nicht.","Beide haben freie Lamellen, jung weiss, durch das rosa Sporenpulver fleischrosa werdend — KEIN Unterscheidungsmerkmal.","Graugruener Dachpilz ist meist kleiner und zierlicher als der oft kraeftige Rehbraune Dachpilz; waechst bevorzugt an Weide/Pappel/Erle.","Graugruener Dachpilz enthaelt Psilocybin/Psilocin und ist giftig (psychoaktiv)."}','Beide haben freie, fleischrosa Lamellen auf Totholz; entscheidend ist der grau-gruenliche Farbton und die moegliche blaugruene Verfaerbung an Druck-/Schnittstellen des giftigen Graugruenen Dachpilzes gegenueber dem rehbraunen, nicht blauenden essbaren.','Rehbrauner Dachpilz mild rettich-/erdartig; Graugruener Dachpilz schwach rettichartig — Geruch trennt nicht zuverlaessig.','Beide wachsen auf morschem Laubholz/Totholz; der Graugruene bevorzugt Weiden/Pappeln/Erlen (Auwald), Ueberschneidung mit dem Rehbraunen ist moeglich.','Beide haben rosa Sporenpulver — identisch, daher kein Trennmerkmal; auf Farbe und Blauverfaerbung achten.','Dachpilze mit grau-gruenlichem Hut oder blaugruener Verfaerbung an Schnitt-/Druckstellen liegen lassen — psychoaktiv und giftig.','123pilze, DGfM, VAPKO, Wikipedia/First-Nature'),
('ramaria_botrytis','ramaria_formosa','mittel','{"Hahnenkamm-Koralle (Ramaria botrytis): dicker, gedrungener weisslicher Strunk mit blumenkohlartig verzweigten Aesten, deren Spitzen weinrot/purpurrosa gefaerbt sind; Schoene Koralle insgesamt blass orange-lachsrosa mit gelben Astspitzen.","Schoene Koralle verfaerbt sich bei Druck/Verletzung oft braeunlich-weinroetlich; Fleisch der Hahnenkamm-Koralle bleibt weiss bzw. verfaerbt kaum.","Schoene Koralle schmeckt bitter (Geschmacksprobe ausspucken!), Hahnenkamm-Koralle mild.","Schoene Koralle hat duennere, orange-lachsfarbene Aeste mit gelben Spitzen; Hahnenkamm-Koralle einen massiven weissen Basisstrunk und nur an den Astspitzen weinrote Toene.","Schoene Koralle ist Magen-Darm-giftig (Uebelkeit, Erbrechen, Durchfall, Koliken)."}','Hahnenkamm-Koralle: weisser, fleischiger Strunk, Aeste weisslich/buff mit weinrot-rosa Spitzen; Schoene Koralle durchgehend orange-lachsfarben mit gelben Spitzen und ohne dicken weissen Strunk.','Beide mild-pilzig; der Geruch trennt nicht — auf den bitteren Geschmack der Schoenen Koralle achten.','Beide wachsen am Boden im Wald; die Schoene Koralle bevorzugt Laubwald (oft Buche), die Hahnenkamm-Koralle Laub-/Mischwald — Habitat trennt nicht.','Beide ockergelbliches Sporenpulver — kein praktisches Trennmerkmal; auf Farbe, Strunkform, Verfaerbung und Geschmack achten.','Korallen mit orangem Koerper, gelben Spitzen, weinroetlicher Druckverfaerbung oder bitterem Geschmack nie essen — nur Korallen mit reinweissem Fleisch und mildem Geschmack gelten als anfaengergeeignet.','123pilze, DGfM, VAPKO, Wikipedia'),
('rhodocollybia_butyracea','gymnopus_peronatus','gering','{"Brennender Rübling: Geschmack scharf-brennend, Stiel zäh mit striegelig-filziger Basis, Hut matt lederbraun","Butter-Rübling: Geschmack mild, Hut fettig-glatt/''butterig'' schmierig glänzend, hygrophan, Stiel längsrillig-knorpelig ohne striegeligen Filz","Butter-Rübling hat blasses, oft schwach rosalich getöntes Sporenpulver (Rhodocollybia) und weichere Konsistenz; Brennender Rübling cremeweiss-sporig und zäh-lederig","Brennender Rübling scharf/giftverdächtig-magenreizend – Butter-Rübling mild, essbar (geschmacklich gering geschätzt)"}','Butter-Rübling hat einen fettig-glänzenden, hygrophan zoniert verblassenden Hut; der Brennende Rübling einen matten, gleichmässig lederbraunen Hut mit filziger Stielbasis.','Beide unauffällig; der brennend-scharfe Geschmack (Kostprobe) ist das sichere Trennmerkmal.','Beide in Nadel-/Laubwaldstreu, oft truppweise – Habitat trennt nicht.','Butter-Rübling cremefarben, oft mit schwachem rosa Ton; Brennender Rübling weisslich-creme – nur im Sporenabwurf schwach unterscheidbar.','Beissprobe: brennt es scharf, liegen lassen. Beim fettig-schmierigen, mild schmeckenden Hut handelt es sich um den Butter-Rübling – trotzdem nur bei sicherer Bestimmung sammeln.','123pilze.de (Butter-Rübling/Brennender Rübling), de.wikipedia.org, DGfM'),
('roetling','agaricus_xanthodermus','hoch','{"Geruch ist das wichtigste Merkmal: Schaf-Champignon angenehm nach Anis/Marzipan; Karbol-Champignon unangenehm nach Tinte/Karbol/Phenol - verstärkt beim Zerreiben der Stielbasis und beim Erhitzen.","Stielbasis längs anschneiden: Karbol-Champignon verfärbt sich SOFORT intensiv chromgelb, konzentriert am Stielgrund; Schaf-Champignon gilbt am ganzen Fruchtkörper nur schwach und nicht konzentriert am Stielgrund.","Beide haben Ring und Lamellen, die von blass-rosa zu schokobraun reifen, und beide haben dunkelbraunes Sporenpulver - daher trennen NUR Stielbasis-Schnitt (Chromgelb) UND Geruchstest sicher, nicht Lamellen oder Sporenfarbe."}','Karbol-Champignon: Hut weiß bis kalkweiß, jung kugelig/halbkugelig, später abgeflacht, glatt bis feinschuppig; Stielbasis im Längsschnitt SOFORT leuchtend chromgelb. Schaf-Champignon: Hut cremeweiß, seidig-faserig bis leicht schuppig, gewölbt bis flach; gilbt am ganzen Pilz nur schwach und ohne den konzentrierten Chromgelb-Fleck am Stielgrund.','Entscheidendes Merkmal: Schaf-Champignon riecht angenehm nach Anis/Marzipan. Karbol-Champignon riecht unangenehm nach Tinte/Karbol/Phenol (medizinisch-jodig); der Geruch verstärkt sich beim Zerreiben der Stielbasis und besonders beim Erhitzen/Kochen.','Karbol-Champignon: Gärten, Parks, Waldränder, Komposthaufen, ruderale/siedlungsnahe Flächen. Schaf-Champignon: gedüngte Wiesen und Weiden, v.a. Schaf- und Pferdeweiden. Habitat allein trennt NICHT sicher (Überschneidung möglich).','Bei beiden Arten dunkel-schokobraun bis purpurbraun (Gattung Agaricus) - KEIN Trennmerkmal.','Stielbasis längs anschneiden: Färbt sie sich sofort intensiv chromgelb UND riecht der Pilz nach Tinte/Karbol statt nach Anis, liegen lassen - Karbol-Champignon. Faustregel: jeder Champignon mit Karbol-/Tintengeruch oder leuchtend chromgelber Stielbasis = giftig, nicht essen.','https://de.wikipedia.org/wiki/Karbol-Champignon · https://www.t-online.de/leben/essen-und-trinken/essen/id_65112638/anischampignon-achtung-verwechslungsgefahr-mit-giftpilzen.html · https://www.pilzbuch-pilzwelten.de/karbolchampignon/agaricus-xanthodermus.html · https://www.pilzbuch-pilzwelten.de/schafchampignon/agaricus-arvensis.html'),
('roetling','amanita_phalloides','sehr_hoch_lebensgefahr','{"Lamellen: Grüner Knollenblätterpilz hat stets REINWEISSE Lamellen; Champignon-Lamellen sind jung blass-rosa (sehr junge Knöpfe ausnahmsweise creme-weiss) und reifen über graurosa zu schokobraun. Im Knopfstadium Lamellenfarbe nicht allein vertrauen - dann Volva + Sporenabwurf zwingend.","Stielbasis: deutlich abgesetzte Knolle mit häutiger Scheide (Volva) beim Knollenblätterpilz; beim Champignon fehlt die Volva. Stielbasis immer komplett ausgraben.","Hutfarbe NICHT als Hauptmerkmal verwenden: typisch oliv-/gelbgrün, aber als var. alba auch rein weiß - daher immer Lamellen + Volva + Sporenpulver prüfen, nie nur die Farbe.","Sporenpulver weiß (Champignon dunkelbraun) - zuverlässigstes Einzelmerkmal."}','Grüner Knollenblätterpilz: Hut oliv-/gelbgrünlich mit eingewachsenen Radialfasern (weiße Form var. alba auch rein weiß), REINWEISSE Lamellen, knolliger Stielgrund mit häutiger Scheide (Volva). Schaf-Champignon: cremeweißer Hut, Lamellen rosa -> schokobraun, KEINE häutige Scheide.','Schaf-Champignon: angenehmer Anis-/Marzipangeruch. Grüner Knollenblätterpilz: jung süßlich-honigartig, im Alter unangenehm - KEIN Anis.','Amanita phalloides: Mykorrhizapilz vorwiegend bei Eichen und Buchen im Wald. Schaf-Champignon: freistehend auf Wiesen und Weiden ohne Baumbindung. Habitat allein ist KEIN sicheres Merkmal.','ENTSCHEIDEND: Schaf-Champignon dunkel-schokobraun bis purpurbraun; Amanita phalloides REIN WEISS. Weißer Sporenabwurf = niemals essen.','Niemals junge, noch geschlossene weiße ''Champignons'' mit hellen Lamellen sammeln - genau im Knopfstadium sieht der tödliche Knollenblätterpilz dem Champignon am ähnlichsten. Stielbasis komplett ausgraben (Volva vorhanden?) und reinweiße Lamellen sowie weißen Sporenabwurf als absolutes Stopp-Signal werten.','https://de.wikipedia.org/wiki/Gr%C3%BCner_Knollenbl%C3%A4tterpilz · https://www.t-online.de/leben/essen-und-trinken/essen/id_65112638/anischampignon-achtung-verwechslungsgefahr-mit-giftpilzen.html · https://www.pilzbuch-pilzwelten.de/wiesenchampignon/agaricus-campestris.html · https://www.pilzbuch-pilzwelten.de/schafchampignon/agaricus-arvensis.html'),
('roetling','amanita_verna','sehr_hoch_lebensgefahr','{"Lamellen: Amanita verna hat in JEDEM Alter rein weiße Lamellen; Schaf-Champignon hat sie jung blass-rosa (sehr junge Knöpfe koennen creme-weiss sein!), später graurosa bis schokobraun. WICHTIG: Im Knopfstadium ist die Lamellenfarbe allein NICHT sicher - dann zwingend Volva + Sporenabwurf prüfen.","Stielbasis: Amanita verna hat eine deutlich abgesetzte Knolle mit häutiger, sackartiger Scheide (Volva); Champignon hat KEINE Volva. Stielbasis dazu immer komplett ausgraben - die Volva sitzt oft tief in der Erde.","Sporenpulver: Champignon dunkelbraun, Amanita verna rein WEISS - der Sporenabwurf ist das zuverlässigste Einzelmerkmal.","Geruch: Schaf-Champignon nach Anis; Amanita verna ohne Anisgeruch (neutral bis süßlich-honigartig) - fehlender Anisgeruch ist ein Warnsignal, ersetzt aber NIE die Volva-/Sporenprüfung."}','Frühlings-Knollenblätterpilz: reinweißer Hut, REINWEISSE Lamellen (auch im Alter), Stielgrund mit knolliger, häutiger, sackartiger Scheide (Volva), oft tief in der Erde. Schaf-Champignon: cremeweißer Hut, Lamellen reifen rosa -> graurosa -> schokobraun, KEINE Volva, höchstens schwach verdickte Stielbasis.','Schaf-Champignon: angenehmer Anis-/Marzipangeruch. Amanita verna: nahezu geruchlos bis leicht süßlich/honigartig, im Alter unangenehm - KEIN Anis.','Amanita verna: Mykorrhizapilz, wächst im Wald (Laub-/Mischwald), v.a. im Frühjahr, mit Baumbindung. Schaf-Champignon: saprotroph auf offenen Wiesen und Weiden ohne Baumbindung. Achtung: Habitat allein ist KEIN sicheres Merkmal.','ENTSCHEIDEND und 100 % zuverlässig: Schaf-Champignon dunkel-schokobraun bis purpurbraun; Amanita verna REIN WEISS. Bei weißem Sporenabwurf NIEMALS als Champignon essen.','Bei jedem weißen ''Champignon'' IMMER die Stielbasis vollständig ausgraben und freilegen: Findet sich eine knollige häutige Scheide (Volva) ODER bleiben die Lamellen rein weiß - lebensgefährlich, stehen lassen. Im Zweifel Sporenabwurf machen: weiß = Knollenblätterpilz, niemals essen. Junge, geschlossene weiße Knöpfe gar nicht erst sammeln.','https://de.wikipedia.org/wiki/Fr%C3%BChlings-Knollenbl%C3%A4tterpilz · https://www.t-online.de/leben/essen-und-trinken/essen/id_65112638/anischampignon-achtung-verwechslungsgefahr-mit-giftpilzen.html · https://www.pilzbuch-pilzwelten.de/schafchampignon/agaricus-arvensis.html · http://tintling.com/pilzbuch/arten/a/Amanita_verna.html'),
('russula_cyanoxantha','amanita_phalloides','sehr_hoch_lebensgefahr','{"Frauentäubling: biegsam-speckige Lamellen (splittern nicht), KEIN Ring, KEINE Volva","Knollenblätterpilz: Ring + Volva, tödliche Amatoxine"}','Violett-grüne Exemplare optisch verwechselbar; Lamellenprobe (biegsam vs. nicht) + Stielbasis entscheidend.','Täubling mild','beide Laubwald (Buche/Eiche)','beide weiss','TÖDLICH. Stielbasis freilegen: jede Knolle mit häutiger Scheide = Lebensgefahr.','Tox Info Suisse / DGfM'),
('russula_paludosa','russula_queletii','mittel','{"Stachelbeer-Taeubling schmeckt anhaltend EXTREM scharf; Apfeltaeubling ist mild bzw. nur anfangs leicht scharf und wird mild (Taeublingsregel).","Apfeltaeubling hat blutrot/orangerot/kupferroten Hut; Stachelbeer-Taeubling dunkler purpur-violettrot.","Apfeltaeubling-Stiel weiss, oft schwach rosa angehaucht; Stachelbeer-Taeubling-Stiel deutlich violett-purpurrot ueberhaucht.","Stachelbeer-Taeubling riecht fruchtig nach Stachelbeerkompott; Apfeltaeubling unauffaellig.","Beide bei Nadelbaeumen (Fichte/Kiefer) - der Geschmack ist das Sicherheitskriterium."}','Apfeltaeubling leuchtend blut-/orangerot mit fast weissem Stiel; Stachelbeer-Taeubling dunkler purpurviolett mit violett ueberlaufenem Stiel.','Stachelbeer-Taeubling fruchtig nach Stachelbeerkompott; Apfeltaeubling geruchsarm.','Apfeltaeubling oft an feuchten Stellen/Moorraendern bei Kiefer/Fichte; Stachelbeer-Taeubling bevorzugt Fichte auf Kalk.','Apfeltaeubling ockergelbes, Stachelbeer-Taeubling cremegelbes Sporenpulver.','Nur Taeublinge essen, die nach 30 s Kauen vollstaendig mild bleiben - anhaltende Schaerfe heisst giftig.','123pilze, pilzbuch-pilzwelten.de (Stachelbeertaeubling/Apfeltaeubling), AWL.ch'),
('russula_paludosa','russula_sardonia','mittel','{"Zitronenblaettriger Taeubling schmeckt sehr scharf (einer der schaerfsten); Apfeltaeubling wird mild (Taeublingsregel: scharf = giftig).","Zitronenblaettriger Taeubling hat leuchtend ZITRONENGELBE Lamellen; Apfeltaeubling cremeweisse bis ockergelbe Lamellen.","Zitronenblaettriger Taeubling hat purpurviolett-schwaerzlichen Hut und violetten Stiel; Apfeltaeubling blut-/orangeroten Hut mit fast weissem Stiel.","Zitronenblaettriger Taeubling weint bei feuchtem Wetter Tropfen an den Lamellen (''Traenen-Taeubling''); Apfeltaeubling nicht.","Beide bei Kiefer/Fichte - nur Geschmack und Lamellenfarbe trennen sicher."}','Auffaellig zitronengelbe Lamellen und violetter Stiel beim Zitronenblaettrigen; Apfeltaeubling cremefarbene Lamellen und weisser Stiel.','Zitronenblaettriger Taeubling schwach fruchtig; Apfeltaeubling geruchsarm - Geruch trennt kaum, der Geschmack umso mehr.','Beide bei Kiefer auf sauren Boeden - Habitat trennt nicht.','Zitronenblaettriger Taeubling cremefarbenes, Apfeltaeubling ockergelbes Sporenpulver.','Zitronengelbe Lamellen unter violettem Hut plus scharfer Geschmack = giftig stehen lassen, nie mit mildem Apfeltaeubling verwechseln.','123pilze, pilzbuch-pilzwelten.de, Wikipedia (Zitronenblaettriger Taeubling), naturemobile'),
('russula_vesca','amanita_phalloides','sehr_hoch_lebensgefahr','{"Knolle/Volva am Stielgrund: A. phalloides hat IMMER eine häutige, sackartige weisse Scheide (Volva) um eine deutliche Knolle – Täublinge haben NIE eine Volva und keine Knolle. Dies ist das bindende Kriterium, Farbe ist es NICHT.","Stielring: A. phalloides trägt einen hängenden, häutigen, gerieften Ring (Manschette) am oberen Stiel – Täublinge sind ringlos.","Lamellen: Täubling = sprödbrüchige, splitternde, am Stiel angewachsene Lamellen (Sprödblättler); A. phalloides = weiche, biegsame, FREIE (nicht am Stiel angewachsene) Lamellen. Die Geschmacksprobe versagt hier, weil Amatoxine MILD/nussig schmecken!","Hutfarbe als schwacher Hinweis: A. phalloides ist weissgrün/grün/oliv/gelbgrün (selten weiss, var. alba) – die fleischrot/weinrote Farbe von R. vesca passt NICHT dazu, ersetzt aber nie die Stielgrund-Prüfung. Die klassische Farb-Verwechslung besteht mit GRÜNEN Täublingen, nicht mit dem roten Speisetäubling."}','Entscheidend und bindend ist der Stielgrund: bei A. phalloides eine häutige weisse Volva um eine knollige Stielbasis plus ein hängender, gerieflter Ring; freie, weiche Lamellen. R. vesca hat eine gerade auslaufende, knollen- und ringlose Stielbasis und sprödbrüchige, angewachsene Lamellen. Farbe ist KEIN verlässliches Kriterium: phalloides ist meist oliv-/gelbgrün (auch weiss als var. alba); die fleischrote Hutfarbe von vesca ist höchstens ein Hinweis. Die typische Farb-Verwechslung des Knollenblätterpilzes besteht mit GRÜNEN Speisetäublingen, nicht mit dem roten vesca – deshalb immer morphologisch am Stielgrund absichern.','Älterer Knollenblätterpilz riecht süsslich nach Kunsthonig bis unangenehm; Speisetäubling riecht mild/unauffällig. Geruch ist NUR ein Indiz, nie das Sicherheitskriterium.','Beide Mykorrhizapilze bei Laubbäumen (Eiche, Buche, Edelkastanie) – Standort trennt sie NICHT zuverlässig, daher zwingend morphologische Prüfung am Stielgrund.','Beide weiss – Sporenpulver UNTERSCHEIDET diese Arten NICHT und darf nicht zur Entwarnung dienen.','Pilz IMMER ganz mit Stielbasis ausgraben (nicht abschneiden!) und auf Knolle + häutige weisse Volva + Stielring prüfen. Findet sich Volva/Knolle/Ring oder sind die Lamellen weich und frei, ist es KEIN Täubling – Täublingsregel/Geschmacksprobe nicht anwenden, da Amatoxine MILD schmecken und tödlich sind. Farbe ist nie das Kriterium. In der Schweiz: bei jedem Zweifel zur amtlichen VAPKO-Pilzkontrolle.','https://de.wikipedia.org/wiki/Gr%C3%BCner_Knollenbl%C3%A4tterpilz · https://www.pilzbuch-pilzwelten.de/gruener-knollenblaetterpilz/amanita-phalloides.html · https://www.dgfm-ev.de/pilz-des-jahres/2019-gruener-knollenblaetterpilz · https://de.wikipedia.org/wiki/T%C3%A4ublingsregel · https://www.vapko.ch/'),
('russula_vesca','russula_emetica','hoch','{"Geschmack (Täublingsregel, das entscheidende Trennmerkmal): R. vesca ist mild und angenehm nussig; R. emetica schmeckt sofort brennend scharf/pfefferartig. Kleines Stück Hut mit Lamellen kurz kauen, NICHT schlucken, vollständig ausspucken – nur anwenden, wenn der Pilz zweifelsfrei als Täubling erkannt ist (sprödbrüchige Lamellen, kein Ring, keine Volva).","Hutfarbe: R. vesca matt fleisch-/weinrot bis rotbraun, oft fleckig ausblassend; R. emetica leuchtend blut-, kirsch- bis purpurrot, bei Nässe klebrig-glänzend.","Verkürzte Huthaut (Leitmerkmal von R. vesca): der Hutrand steht zurück, sodass Hutfleisch und Lamellenenden zähnchenartig über den Rand hinausragen – fehlt bei R. emetica (Huthaut deckt bis zum Rand und lässt sich weit, oft bis zur Hutmitte, abziehen).","Standort: R. emetica typisch in feuchten Moor- und Nadelwäldern (Fichte, Kiefer, Weisstanne, oft moosig/sauer); R. vesca v.a. in Laub-/Mischwald bei Buche und Eiche."}','R. vesca: matt fleisch- bis weinrot/rotbraun, häufig ausgeblasst und unregelmässig fleckig, Hutrand mit zurückstehender (zu kurzer) Huthaut, sodass die Lamellenkanten zähnchenartig überstehen. R. emetica: einheitlich leuchtend kirsch-/blutrot, bei Feuchte schmierig glänzend, Huthaut deckt bis zum Rand und ist weit (oft bis zur Hutmitte) abziehbar.','Beide weitgehend unauffällig/leicht obstig; der Geruch trennt diese zwei Arten NICHT. Entscheidend ist der Geschmack (mild vs. brennend scharf).','R. emetica: feuchte/saure Moor- und Nadelwälder (Fichte, Kiefer, Weisstanne), oft moosig. R. vesca: Laub- und Mischwald bei Buche und Eiche, eher frische bis trockene Böden.','Beide weiss bis weisslich – Sporenpulver trennt diese zwei Arten NICHT. Nicht zur Unterscheidung verwenden.','Geschmacksprobe nach Täublingsregel: kleines Stück Hut mit Lamellen kauen, ausspucken, nicht schlucken – mild = Speisetäubling, scharf/brennend = Speitäubling (giftig, verwerfen). Die Regel gilt NUR, wenn der Pilz zweifelsfrei als Täubling erkannt ist (sprödbrüchige, splitternde Lamellen, kein Stielring, keine Volva). R. emetica ist nicht tödlich, löst aber tagelange heftige Magen-Darm-Beschwerden aus.','https://www.pilzbuch-pilzwelten.de/speisetaeubling/russula-vesca.html · https://de.wikipedia.org/wiki/Kirschroter_Spei-T%C3%A4ubling · https://de.wikipedia.org/wiki/T%C3%A4ublingsregel · https://www.derkleinegarten.de/pilze-bestimmen/speitaeubling-russula-emetica.html · https://fundkorb.de/pilze/russula-emetica-kirschroter-speit%C3%A4ubling'),
('russula_vesca','russula_nobilis','mittel','{"Buchen-Speitaeubling schmeckt sofort EXTREM scharf/brennend; der Speisetaeubling schmeckt mild-nussig (Taeublingsregel: scharf = giftig).","Beim Speisetaeubling ist die Huthaut typisch zu kurz und laesst den Hutrand frei (''zu kurzer Mantel''); beim Buchen-Speitaeubling deckt sie den Rand.","Buchen-Speitaeubling hat lebhaft zinnoberrote Hutfarbe; Speisetaeubling eher fleischrot, weinrot bis braeunlich, oft fleckig ausgeblasst.","Lamellen des Speisetaeublings im Alter rostfleckig; beim Buchen-Speitaeubling rein weisslich bis blass cremegelb.","Beide haben einen weissen Stiel und wachsen im Buchenwald - nur der Geschmackstest trennt sicher."}','Speisetaeubling mit charakteristisch zurueckgezogener Huthaut (freier Hutrand) und matterem Rotton; Buchen-Speitaeubling leuchtend zinnoberrot mit randdeckender Haut.','Buchen-Speitaeubling riecht suesslich-obstartig; Speisetaeubling fast geruchlos bis schwach nussig.','Beide bei Buche auf eher trockenen Boeden - Habitat trennt nicht.','Beide weissliches Sporenpulver - kaum trennend.','Bei roten Taeublingen IMMER ein Stueckchen Hutrand kauen und ausspucken - brennend scharf bedeutet giftig und gehoert nicht in den Korb.','123pilze, pilzbuch-pilzwelten.de (Buchenspeitaeubling/Speisetaeubling), Wikipedia (Taeublingsregel), DGfM'),
('russula_virescens','amanita_phalloides','sehr_hoch_lebensgefahr','{"Täubling: spröde Lamellen, KEIN Ring, KEINE Knolle/Volva","Knollenblätterpilz: Ring + häutige Volva an knolliger Basis, biegsame Lamellen"}','Grüne Färbung ähnlich, besonders jung; Täubling-Huthaut felderig aufreissend.','Täubling mild/nussig; Knollenblätterpilz honigartig (alt)','beide Laubwald','Täubling weiss, A. phalloides weiss','TÖDLICH. Bei grünen Pilzen IMMER ganzen Pilz ausgraben: fehlen Ring UND Volva? Sonst nicht essen.','Tox Info Suisse / Wikipedia'),
('russula_xerampelina','russula_queletii','mittel','{"Stachelbeer-Taeubling schmeckt EXTREM scharf (einer der schaerfsten Taeublinge); der Heringstaeubling mild (Taeublingsregel: scharf = giftig).","Heringstaeubling riecht typisch nach Hering/Fischlake (besonders in warmer Hand und im Alter); Stachelbeer-Taeubling riecht fruchtig nach Stachelbeerkompott.","Heringstaeubling-Fleisch braeunt/gilbt und gibt mit Eisensulfat eine gruene Reaktion; Stachelbeer-Taeubling nicht.","Stachelbeer-Taeubling hat purpurrot ueberhauchten, violett getoenten Stiel; Heringstaeubling oft rosa-roetlichen, spaeter braeunenden Stiel.","Beide wachsen bei Fichte - Geschmack und Geruch trennen sicher."}','Heringstaeubling braeunt im Fleisch und am Stiel; Stachelbeer-Taeubling bleibt purpurrot-violett ohne Braeunung.','Heringstaeubling nach Fisch/Hering, Stachelbeer-Taeubling fruchtig nach Stachelbeerkompott.','Beide bei Fichte auf eher kalkhaltigem Boden - Habitat trennt nicht.','Heringstaeubling ockergelbes, Stachelbeer-Taeubling cremegelbes Sporenpulver.','Geschmackstest entscheidet: brennend scharf = giftiger Stachelbeer-Taeubling; mild plus Fischgeruch = essbarer Heringstaeubling.','123pilze, pilzbuch-pilzwelten.de (Stachelbeertaeubling/Heringstaeubling), DGfM, Wikipedia'),
('russula_xerampelina','russula_sardonia','mittel','{"Zitronenblaettriger Taeubling schmeckt sehr scharf; Heringstaeubling mild (Taeublingsregel: scharf = giftig).","Heringstaeubling riecht nach Hering/Fischlake und braeunt im Fleisch; Zitronenblaettriger Taeubling riecht schwach fruchtig und braeunt nicht.","Zitronenblaettriger Taeubling hat leuchtend zitronengelbe Lamellen; Heringstaeubling cremeocker, spaeter braeunend.","Heringstaeubling reagiert mit Eisensulfat gruen; Zitronenblaettriger Taeubling nicht gruen.","Beide bei Kiefer/Fichte - Geschmack und Fischgeruch sind die Sicherheitskriterien."}','Zitronenblaettriger Taeubling mit zitronengelben Lamellen und violettem Hut; Heringstaeubling braeunlich-rot mit braeunenden Lamellen und Stiel.','Heringstaeubling deutlich nach Fisch/Hering; Zitronenblaettriger Taeubling schwach fruchtig, nie fischig.','Beide bei Nadelbaeumen (Kiefer/Fichte) - Habitat trennt nicht.','Heringstaeubling ockergelbes, Zitronenblaettriger Taeubling cremefarbenes Sporenpulver.','Mild plus Fischgeruch = essbarer Heringstaeubling; scharf mit zitronengelben Lamellen = giftiger Zitronenblaettriger Taeubling.','123pilze, pilzbuch-pilzwelten.de, DGfM, Wikipedia'),
('schopftintling','amanita_phalloides','mittel','{"Schopf-Tintling eiförmiger Hut schuppig Knollenblätter glatt","Tintling Wiesen Knollenblätter Wald"}','Tintling: weiss-schuppig eiförmig. Knollenblätter: olivgrün glatt.','—','Tintling: Wiesen Wegrand. Knollenblätter: Laubwald.','Tintling: schwarz. Knollenblätter: weiss.','Tintling-Lamellen werden schwarz Knollenblätter NIEMALS.','VAPKO Schweiz'),
('schopftintling','coprinopsis_picacea','mittel','{"Schopftintling: weisser, walzlich-zylindrischer Hut mit aufstehenden weissen Schuppen und beweglichem Ring am Stiel; Spechttintling mit dunkelbraun-schwarzem Hut, der mit weissen, abwischbaren Velumflecken bedeckt ist (Elster-/Spechtmuster), ohne Ring.","Schopftintling jung geruchsneutral und angenehm; Spechttintling riecht unangenehm muffig-teerig.","Spechttintling schlanker, hoeher und zerbrechlicher; der junge Schopftintling kraeftiger/gedrungener.","Spechttintling ist ungeniessbar (muffig-teeriger Geschmack); Schopftintling jung (bei noch weissen Lamellen) ein hervorragender Speisepilz."}','Reinweisser, geschuppter Schopftintling mit Ring vs. schwarzbrauner Spechttintling mit weissen Velumflecken und ohne Ring.','Spechttintling unangenehm muffig-teerig; Schopftintling neutral und angenehm.','Spechttintling bevorzugt humus- und kalkreiche Laub-/Buchenwaelder und Waldwegraender; Schopftintling auf naehrstoffreichen Wiesen, Weg- und Wegraendern, Ruderalflaechen.','Beide schwarzes Sporenpulver (zerfliessend); nicht trennend.','Schwarz-weiss geflecktes, muffig-teerig riechendes Tintlings-Exemplar ohne Stielring grundsaetzlich stehen lassen.','pilzbuch-pilzwelten.de (Spechttintling / Schopftintling), awl.ch'),
('semmelstoppelpilz','austernpilz','gering','{"Stoppel hat STACHELN Austernseitling LAMELLEN","Boden vs Baumstamm"}','Stoppel auf Boden Mischwald. Austern an Baumstamm.','—','Boden vs Baum','—','Beide Anfänger-tauglich.','VAPKO Schweiz'),
('steinpilz','butterpilz','gering','{"Steinpilz glatter Stiel Butterpilz Ring + schleimige Hut"}','Steinpilz weiss-genetzter Stiel kein Ring. Butterpilz schleimige Hut Ring.','—','Beide Nadelwald, Butterpilz Föhre.','—','Butterpilz-Hut-Haut abziehen.','VAPKO Schweiz'),
('steinpilz','caloboletus_calopus','mittel','{"Schoenfuss-Roehrling schmeckt extrem BITTER (auch nach dem Kochen bitter, ungeniessbar) - Steinpilz schmeckt mild-nussig","Schoenfuss-Roehrling blaut bei Verletzung an Fleisch und Roehren rasch blaugruenlich; Steinpilzfleisch bleibt weiss und unveraenderlich (blaut nicht)","Stiel des Schoenfuss-Roehrlings kraeftig rot mit feinem Netz (unten rot, oben gelb); Steinpilzstiel braun-beige mit hellem Netz, NIE rot","Hut des Schoenfuss-Roehrlings lehmgrau/graubraun; Steinpilz warm braun bis kastanienbraun","Roehren/Poren des Steinpilzes weiss bis gelbgruen ohne Blauen; beim Giftpilz gelb und auf Druck blauend"}','Schoenfuss-Roehrling: lehmgrauer Hut, knallroter Netzstiel, blauendes Fleisch. Steinpilz: brauner Hut, beiger Netzstiel, weiss bleibendes Fleisch.','Steinpilz angenehm pilzig; Schoenfuss-Roehrling unauffaellig - der bittere Geschmack entscheidet.','Beide im Nadel-/Laubmischwald; Habitat trennt nicht zuverlaessig.','Beide olivbraunes Sporenpulver - KEIN Unterscheidungsmerkmal.','Geschmacksprobe (winziges Stueck Roehrenschicht auf die Zunge, NICHT schlucken, ausspucken): bitter plus rotes Stielnetz plus Blauen = Schoenfuss-Roehrling (magen-darm-giftig/ungeniessbar), kein Steinpilz.','awl.ch, pilzkurse.com (Schweiz), Wikipedia Schoenfuss-Roehrling, pilzbuch-pilzwelten.de'),
('steinpilz','roehrling_flockenstielig','mittel','{"Schönfuß-Röhrling schmeckt bitter und sein Fleisch BLAUT beim Anschnitt; Steinpilz schmeckt nussig-mild und sein Fleisch bleibt weiss/unverändert (blaut nicht)","Schönfuß hat ein deutlich ROTES Netz/roten Bereich am Stiel; Steinpilz hat ein weisses bis hellbräunliches Netz auf hellem Stiel","Schönfuß-Poren gelb (auf Druck blauend); Steinpilz-Röhren weiss → gelb → olivgrün, ohne zu blauen","Schönfuß-Hut lehmgrau/graubraun matt; Steinpilz-Hut warm hell- bis dunkelbraun, oft speckig glänzend","Geschmackskostprobe: Schönfuß bitter, Steinpilz mild — sicheres Trennkriterium"}','Rotes Stielnetz + blauendes gelbes Porenfeld beim Schönfuß vs. weisses Netz + stabil weisses Fleisch und nicht-blauende Röhren beim Steinpilz.','Beide angenehm pilzig; Geschmackstest entscheidet — Schönfuß bitter, Steinpilz mild-nussig.','Grosse Überlappung in Misch-/Nadelwald — Standort trennt nicht zuverlässig.','Beide olivbraun — kein Unterscheidungsmerkmal.','Merksatz: Blaut das Fleisch/Poren oder ist das Stielnetz rot, ist es kein Steinpilz. Beim Steinpilz bleibt Fleisch weiss und Netz hell — jedes Blauen oder rotes Netz = nicht Steinpilz, nicht in den Korb.','123pilze, Wikipedia (Schönfuß-Röhrling), SwissFungi/AWL.ch'),
('steinpilz','rubroboletus_satanas','hoch','{"Satansroehrling hat ROTE bis orangerote Poren; der Steinpilz hat NIE rote Poren (jung weiss, dann gelblich-oliv).","Satansroehrling-Fleisch blaut beim Anschnitt nur schwach bis maessig; Steinpilz-Fleisch bleibt komplett weiss und verfaerbt sich nicht.","Satansroehrling hat ein deutlich rotes, engmaschiges Stielnetz auf gelbem Grund (spaeter blutrot) am bauchig-knolligen Stiel; Steinpilz hat ein feines weisses bis braeunliches Netz.","Reifer/alter Satansroehrling riecht widerlich nach Aas; Steinpilz riecht angenehm pilzig-nussig.","Beide haben jung einen hellen, weisslich-graugruenen bis kalkweissen Hut - die helle Hutfarbe allein darf NIE zur Bestimmung dienen."}','Entscheidend ist die Porenfarbe: rot/orange beim Satansroehrling, nie beim Steinpilz - plus das rote Stielnetz statt weissem Netz und das schwache Blauen statt gar keiner Verfaerbung.','Alter Satansroehrling stinkt nach Aas/Verwesung, Steinpilz riecht angenehm nussig-pilzig.','Beide in warmen Laubwaeldern auf Kalk unter Eiche/Buche - das Habitat trennt sie nicht zuverlaessig.','Beide olivbraunes Sporenpulver - kein praktisches Trennmerkmal.','Jeden Roehrling mit auch nur ansatzweise roten/orangen Poren grundsaetzlich stehen lassen - ein echter Steinpilz hat NIE rote Poren.','123pilze, AWL.ch (Pilzkurse Schweiz), Wikipedia (Satans-Roehrling), pilzbuch-pilzwelten.de'),
('steinpilz','tylopilus_felleus','gering','{"Steinpilz: feines weisses Netz, weisse/gelbe Röhren, mild","Gallenröhrling: grobes dunkles Netz, rosa Röhren, extrem bitter"}','Röhrenfarbe (weiss/gelb vs. rosa) + Netz (fein-weiss vs. grob-dunkel).','Gallenröhrling extrem bitter (Kostprobe winzig, ausspucken)','beide saure Nadel-/Mischwälder, oft zusammen','Steinpilz oliv, Gallenröhrling rosa','Nicht giftig, aber ein einziger Gallenröhrling verdirbt ein ganzes Gericht. Rosa Röhren + grobes Netz + Bitterkeit entlarven ihn.','awl.ch / de.wikipedia.org'),
('suillellus_luridus','caloboletus_calopus','mittel','{"Schoenfuss-Roehrling schmeckt stark BITTER (ungeniessbar/magen-darm-giftig auch gekocht); Netzstieliger Hexen-Roehrling mild, aber NUR gut durchgegart essbar (roh giftig)","Netzstieliger Hexen-Roehrling hat ROTORANGE Poren und eine roetliche Linie (Batsch-Linie) ueber den Roehren; Schoenfuss-Roehrling gelbe Poren","Hexen-Roehrling-Hut oliv-/lederbraun, oft polsterfoermig; Schoenfuss-Roehrling lehmgrau","Beide blauen stark - aber Hexen-Roehrling mit roten Poren und rotem Netz auf braeunlich-gelbem Stiel, Schoenfuss-Roehrling mit gelben Poren und rot-gelbem Stiel","Geschmack entscheidet: Schoenfuss bitter (raus); Netzstieliger Hexen-Roehrling mild und erst nach ausreichendem Durchgaren essbar"}','Netzstieliger Hexen-Roehrling: rotorange Poren, rotes Stielnetz, Batsch-Linie. Schoenfuss-Roehrling: gelbe Poren, grauer Hut, rot-gelber Netzstiel.','Beide unauffaellig - der Bittergeschmack des Schoenfuss-Roehrlings ist das Trennmerkmal.','Beide bei Laubbaeumen; Netzstieliger Hexen-Roehrling bevorzugt kalkhaltigen Boden. Habitat trennt nicht zuverlaessig.','Beide olivbraunes Sporenpulver - KEIN Unterscheidungsmerkmal.','Poren pruefen UND Geschmacksprobe (ausspucken): gelbe Poren plus bitter = Schoenfuss-Roehrling (raus); rote/orange Poren ohne Bitterkeit = Netzstieliger Hexen-Roehrling - dieser ist roh giftig und nur gut durchgegart essbar, nie roh probieren ausser zur Spuck-Geschmacksprobe.','pilzkurse.com (Schweiz), Wikipedia Schoenfuss-Roehrling, awl.ch, pilzbuch-pilzwelten.de'),
('suillellus_luridus','rubroboletus_legaliae','hoch','{"Le Gals (Rubroboletus legaliae) hat einen blassen, weisslich/grau bis weinrosa-altrosa Hut; Netzstieliger Hexen-Röhrling hat einen ockerbraunen bis ziegelrot-dunkeloliven Hut","Le Gals riecht auffällig würzig nach Liebstöckel/Sellerie/Zichorie; Netzstieliger Hexen-Röhrling riecht neutral pilzig","Le Gals blaut nur schwach/mässig im Fleisch und NICHT in der Huthaut; Netzstieliger Hexen-Röhrling blaut sofort kräftig dunkelblau (auch Huthaut/Fleisch)","Beide haben rote/karminrote Poren und ein Stielnetz — diese Merkmale trennen NICHT; entscheidend sind Hutfarbe, Selleriegeruch und Blau-Intensität","Le Gals ist auch gut erhitzt giftig/unverträglich (schwere Magen-Darm-Störungen gemeldet); Netzstieliger Hexen-Röhrling NUR roh giftig, ausreichend durcherhitzt essbar (auch dann nicht mit Alkohol)"}','Blasser weiss-/graurosa Hut beim Le Gals vs. ocker-/ziegelrot-dunkeloliver Hut beim Netzstieligen Hexen-Röhrling; bei Le Gals KEIN Blauen der Huthaut, beim Hexen-Röhrling starkes Blauen.','Le Gals deutlich nach Sellerie/Liebstöckel; Netzstieliger Hexen-Röhrling geruchlich neutral.','Le Gals selten, wärmeliebend unter alten Eichen/Buchen auf Kalk; Netzstieliger Hexen-Röhrling häufiger in Laub-/Mischwald auf Kalk — Überlappung möglich, Standort trennt nicht sicher.','Beide olivbraunes Sporenpulver — kein Trennmerkmal.','Rotporige Röhrlinge nur als erfahrener Sammler nehmen: blasser/rosa Hut + Selleriegeruch + nur schwaches Blauen = Le-Gals-/Satans-Gruppe, giftig. Die sogenannte Bataille-Linie (rote Linie über den Röhren) ist KEIN sicheres Bestimmungsmerkmal — sie fehlt vielen echten Netzhexen und ist überbewertet. Im Zweifel stehen lassen.','123pilze (Falscher Satansröhrling), Wikipedia (Rubroboletus legaliae / Suillellus luridus), AWL.ch, VAPKO'),
('suillellus_luridus','rubroboletus_satanas','hoch','{"Netzstieliger Hexenroehrling blaut beim Anschnitt SCHNELL und intensiv tiefblau; Satansroehrling blaut nur schwach/verzoegert.","Netzstieliger Hexenroehrling hat einen olivgelben bis grau-braunen Hut; Satansroehrling jung einen hellen, kalkweiss-graugruenen Hut.","Beide haben rote/orangerote Poren UND ein rotes Stielnetz - die rote Porenfarbe trennt sie NICHT, nur Blauen-Geschwindigkeit, Hutfarbe und Geruch.","Satansroehrling riecht im Alter widerlich nach Aas; der Netzstielige Hexenroehrling riecht neutral-pilzig.","Der Netzstielige Hexenroehrling ist roh giftig/unvertraeglich und nur gut durcherhitzt essbar; der Satansroehrling bleibt auch gekocht giftig."}','Heller weisslich-grauer Hut beim Satansroehrling vs. olivgelb-brauner Hut beim Hexenroehrling; Hexenroehrling blaut sofort intensiv, Satansroehrling nur schwach.','Satansroehrling alt nach Aas, Netzstieliger Hexenroehrling neutral-pilzig.','Beide auf Kalk unter Laubbaeumen - kein sicheres Trennmerkmal.','Beide olivbraun - nicht trennend.','Rotporige Roehrlinge nur essen, wenn zweifelsfrei als essbarer Hexenroehrling bestimmt UND gruendlich durcherhitzt - im Zweifel zur Pilzkontrolle (VAPKO).','123pilze, AWL.ch (Vergleich rotporige Roehrlinge), Wikipedia (Netzstieliger Hexen-Roehrling)'),
('tricholoma_cingulatum','tricholoma_scalpturatum','mittel','{"T. cingulatum (essbar): besitzt einen deutlichen, haeutigen RING/Velumzone am Stiel - scalpturatum ist ringlos. Der Ring ist das wichtigste Trennmerkmal zu allen anderen Erdritterlingen.","T. scalpturatum (giftverdaechtig/minderwertig, NICHT sammeln): kein Ring, Lamellen und Fleisch gilben deutlich.","cingulatum lebt in Mykorrhiza mit Weiden (Salix), seltener Birken (Betula) - oft an feuchten Standorten/Auen.","Geruch beider mehlig; cingulatum mild.","Ringzone vorhanden + Weiden-/Birkenbindung = cingulatum; ringlos + gilbend = scalpturatum."}','cingulatum mit Ring/Velumzone am Stiel, scalpturatum ringlos und gilbend.','beide mehlig; cingulatum milder.','cingulatum bei Weiden (oft feucht/Auwald), seltener Birken; scalpturatum breit in Laub-/Misch-/Nadelwald und Parkbestaenden.','Beide weiss - kein Trennmerkmal.','Ein deutlicher Ring am Stiel UND Weiden-/Birkenbindung sprechen fuer cingulatum; fehlt der Ring und das Fleisch gilbt, Finger weg. Bei grauen Erdritterlingen allgemein hoechste Vorsicht (toedlicher Tiger-Ritterling Tricholoma pardinum aehnlich).','123pilze, pilzbuch-pilzwelten.de, Wikipedia (Beringter Erd-Ritterling), DGfM, VAPKO'),
('tricholoma_columbetta','tricholoma_pardinum','hoch','{"Weisser/Seidiger Ritterling ist rein weiss bis seidig glaenzend mit glatter Oberflaeche; Tiger-Ritterling ist grau bis graubraun mit groben dunklen Schuppen auf dem Hut.","Ein wirklich rein weisser, schuppenfreier Hut spricht klar gegen den Tiger-Ritterling; jede graue Toenung oder grobe Schuppe ist ein Warnsignal.","Weisser Ritterling kann am Stiel auf Druck blaugruenlich/rosa verfaerben, bleibt aber insgesamt weiss-seidig; Tiger-Ritterling ist von Grund auf grau gefaerbt und genattert-schuppig.","Tiger-Ritterling loest schweres Magen-Darm-Syndrom aus (Erbrechen/Durchfall nach 15-30 Min) - bei Grau-Toenung oder Schuppen niemals als Weissen Ritterling werten."}','Weisser Ritterling rein weiss-seidig und glatt; Tiger-Ritterling grau mit grobem dunklem Schuppenrasen.','Weisser Ritterling mild bis schwach mehlig; Tiger-Ritterling mehlig/gurkig - der Geruch ist nicht entscheidend, Hutfarbe und Schuppung zaehlen.','Beide in Laub- und Bergwaeldern moeglich; der Standort trennt sie nicht zuverlaessig - Hutfarbe und Schuppung sind ausschlaggebend.','Beide weisses Sporenpulver - kein Unterscheidungsmerkmal.','WICHTIGER noch als der Tiger-Ritterling: rein weisse Ritterlinge koennen mit toedlichen weissen Knollenblaetterpilzen (Amanita) verwechselt werden - immer auf fehlende Knolle/Volva und Manschette pruefen. Nur makellos weisse, schuppenfreie Exemplare ohne Stielknolle gelten als Weisser Ritterling.','123pilze, DGfM, VAPKO, Wikipedia Ritterlinge'),
('tricholoma_columbetta','tricholoma_scalpturatum','mittel','{"T. columbetta (essbar): rein weiss, seidig-glaenzend, Lamellen und Fleisch verfaerben NICHT gelb (hoechstens punktuell blau-/rosagruenlich am Stiel).","T. scalpturatum (giftverdaechtig/minderwertig, NICHT sammeln): grau bis graubraun, gilbt deutlich an Lamellen und Fleisch.","Geruch: columbetta nahezu geruchlos bis schwach pilzig-mild, scalpturatum mehlig.","columbetta hat festes, weisses, unverfaerbendes Fleisch; bei scalpturatum gelbliche Verfaerbung im Schnitt bzw. beim Kratzen.","Hutfarbe als Schnelltest: reinweiss = Richtung columbetta pruefen, grau/gilbend = giftverdaechtiger Erdritterling."}','columbetta reinweiss und seidig ohne Gilben; scalpturatum grau-braun und gilbend.','columbetta nahezu geruchlos/mild, scalpturatum mehlig.','columbetta bevorzugt Laubwald (Buche, Eiche) auf besseren Boeden; scalpturatum in Laub-/Misch-/Nadelwald und Parkanlagen.','Beide weisses Sporenpulver - kein Trennmerkmal.','Farbe und Gilbreaktion sind entscheidend: einen grauen, gilbenden Ritterling nie als weissen Ritterling abtun. Reinweisse Ritterlinge sind ihrerseits mit giftigen weissen Trichterlingen/Risspilzen verwechselbar - nur mit Bestimmungssicherheit sammeln.','123pilze, pilzbuch-pilzwelten.de, SwissFungi, VAPKO'),
('tricholoma_portentosum','tricholoma_equestre','hoch','{"Gruenling (giftig): Lamellen und Stielfleisch auffaellig schwefel- bis zitronengelb; Schwarzfaseriger Ritterling (essbar): Lamellen jung weiss, im Alter hoechstens schwach gelblich-gruen ueberlaufen, nie satt schwefelgelb.","Gruenling-Hut gelblich-olivbraun mit deutlichem gelbem Grundton; Schwarzfaseriger Ritterling silbergrau mit schwarzen radialen Faserstreifen, oft mit lila/gruenlichem Schimmer.","Beide wachsen bei Kiefern auf Sandboden - der Standort ist KEIN Unterscheidungsmerkmal; die Lamellen- und Stielfarbe ist ausschlaggebend.","Gruenling kann bei wiederholtem Verzehr groesserer Mengen (mehrere Mahlzeiten in wenigen Tagen) Rhabdomyolyse (Muskelzerfall) ausloesen - 2001 in Frankreich 12 Faelle, 3 Todesfaelle; daher als giftig eingestuft und in einigen Laendern geschuetzt."}','Gruenling durchgehend gelblich, besonders die Lamellen schwefelgelb; Schwarzfaseriger Ritterling grau mit schwarzen Radialfasern und blassen, jung weissen Lamellen.','Beide mild mehlig bis gurkenartig - der Geruch unterscheidet sie NICHT zuverlaessig.','Beide bei Kiefern/Foehren auf mageren Sandboeden - daher hohe Verwechslungsgefahr; der Standort trennt sie nicht.','Beide weisses Sporenpulver - kein Unterscheidungsmerkmal.','Jeden gelblichen Ritterling mit schwefelgelben Lamellen aus dem Kiefernwald meiden - der Gruenling ist trotz frueherem Speisepilz-Status heute wegen dokumentierter toedlicher Muskelzerfall-Vergiftungen als giftig eingestuft.','DGfM, BfR (Bundesinstitut fuer Risikobewertung), VAPKO, Wikipedia Gruenling, fungiversum.de'),
('tricholoma_portentosum','tricholoma_pardinum','hoch','{"Tiger-Ritterling hat eine grob schuppig-genatterte, filzige Hutoberflaeche mit dunkelgrauen Schuppen auf hellerem Grund; Schwarzfaseriger Ritterling hat eine glatte, radial-faserig gestreifte, bei Naesse schmierige Hutoberflaeche OHNE grobe Schuppen.","Tiger-Ritterling oft kraeftiger/groesser (Hut bis 15 cm) mit dickem Stiel; Schwarzfaseriger Ritterling schlanker mit grau-faserigem Hut, oft mit lila/gruenlichem Ton.","Tiger-Ritterling waechst gern in Bergwaeldern auf Kalk bei Buche/Fichte; Schwarzfaseriger Ritterling typisch bei Kiefern auf saurem Sand.","Tiger-Ritterling verursacht heftiges Magen-Darm-Syndrom (Erbrechen/Durchfall schon nach 15-30 Min), schwere Vergiftungen moeglich; schon eine ausgespuckte Geschmacksprobe kann Beschwerden ausloesen."}','Tiger-Ritterling grob schuppig-genattert/filzig mit Schuppenrasen; Schwarzfaseriger Ritterling glatt mit feinen schwarzen Radialfasern, kein Schuppenrasen.','Beide mehlig/gurkig - der Geruch trennt sie nicht und darf nicht zur Bestimmung verwendet werden.','Tiger-Ritterling bevorzugt Kalk-Bergwaelder bei Buche/Fichte; Schwarzfaseriger Ritterling bei Kiefern auf sauren Sandboeden.','Beide weisses Sporenpulver - kein Unterscheidungsmerkmal.','Graue Ritterlinge mit grob schuppig-genatterter Hutoberflaeche grundsaetzlich stehen lassen - der Tiger-Ritterling ist einer der haeufigsten schweren Pilzvergifter Mitteleuropas.','123pilze, DGfM, VAPKO, pilzbuch-pilzwelten.de, Wikipedia Tiger-Ritterling'),
('tricholoma_portentosum','tricholoma_saponaceum','mittel','{"Seifen-Ritterling (schwach giftig): typischer SEIFEN-/Waschpulver-Geruch - aber NICHT immer vorhanden (oft schwach, nach starkem Regen fast fehlend), daher kein Einzelkriterium.","Seifen-Ritterling: Fleisch verfaerbt sich bei Verletzung haeufig etwas roetlich, besonders im Stielgrund; Geschmack unangenehm bitter-mehlig.","Schneeritterling (essbar): mehlig-milder Geruch, KEINE deutliche Roetung des Fleisches; Hut feucht schmierig mit schwarzen Radialfasern.","Seifen-Ritterling-Hut sehr variabel grau bis grau-/gelbbraun, fein schuppig, matt - OHNE den schmierigen Schleimglanz des portentosum; Stiel oft spindelig/verdreht.","Im Zweifel Schnittprobe am Stielgrund + Geruchsprobe: roetendes Stielfleisch und/oder Seifen-/Waschlaugengeruch sind klare Warnsignale gegen Verzehr."}','portentosum hat einen feucht-schmierigen, radialfaserig-schwarz gestreiften Hut mit allenfalls schwachem Gelbgruenton; saponaceum ist matt, trocken und stark farbvariabel (grau bis grau-/gelbbraun), fein schuppig, und sein Fleisch (v.a. Stielbasis) roetet beim Anschneiden.','Seifen-/Waschlaugengeruch spricht fuer saponaceum, mehlig-mild fuer portentosum. ACHTUNG: der Seifengeruch ist oft schwach oder fehlt (besonders nach Regen) - sein Fehlen ist KEINE Entwarnung.','saponaceum als Symbiosepilz in Misch- und Nadelwald (Aug-Nov); portentosum vor allem bei Kiefer/Fichte auf sandigem Boden - der Standort trennt nicht sicher.','Beide weisses Sporenpulver - kein Unterscheidungsmerkmal.','Stielbasis anschneiden und riechen: roetendes Fleisch und/oder Seifen-/Waschkuechengeruch bedeuten Seifen-Ritterling - nicht essen. Da der Seifengeruch fehlen kann, graue Ritterlinge generell nur bei 100% sicherer Bestimmung sammeln.','123pilze, pilzbuch-pilzwelten.de, DGfM, VAPKO, GiftnotrufZentrale (CH-Notruf 145)'),
('tricholoma_portentosum','tricholoma_scalpturatum','mittel','{"T. portentosum (essbar): Hut graubraun mit deutlich schwarzfaserig-radialer Zeichnung, oft violett-/gelblicher Schimmer; Fleisch und Lamellen verfaerben NICHT gilbend.","T. scalpturatum (giftverdaechtig/minderwertig, NICHT sammeln): Lamellen und Fleisch gilben deutlich (gelbliche Flecken bei Druck, beim Kratzen oder im Alter) - zentrales Trennmerkmal.","Geruch: portentosum mild bis schwach mehlig-gurkig, angenehm; scalpturatum deutlich mehlig.","portentosum waechst typisch spaet im Jahr (Spaetherbst/Frost) bei Kiefer/Fichte; scalpturatum von Mai bis November in Laub-/Misch- und Nadelwald, Parks, Gaerten.","Hutoberflaeche portentosum bei Feuchte schmierig-glaenzend, scalpturatum trocken-feinschuppig/eingewachsen-faserig."}','T. portentosum zeigt schwarze Radialfasern auf grauem Hut ohne Gilben; T. scalpturatum gilbt an Lamellen und Schnittflaeche beim Kratzen/Druck.','portentosum mild und angenehm mehlig-gurkig, scalpturatum aufdringlich mehlig.','portentosum spaetherbstlich bei Nadelbaeumen (Kiefer/Fichte) auf saurem Boden, scalpturatum Mai bis November in Laub-/Misch-/Nadelwald, Parks und Gaerten.','Beide weisses Sporenpulver - das Sporenpulver trennt hier NICHT; ausschliesslich Gilben (scalpturatum) + Hutfarbe + Saison nutzen.','Jeder grau-braune Erdritterling, dessen Lamellen oder Schnittflaeche gilben, ist KEIN Speisepilz - im Zweifel stehen lassen. Graue Erdritterlinge generell nur mit absoluter Bestimmungssicherheit; mehrere giftige bis toedliche Arten (z.B. Tricholoma pardinum) sehen aehnlich aus.','123pilze, pilzbuch-pilzwelten.de, Wikipedia (Gilbender Erd-Ritterling), VAPKO/DGfM'),
('tricholoma_portentosum','tricholoma_terreum','mittel','{"Schwarzfaseriger/Schneeritterling (essbar): Hut grau bis grauweiss mit eingewachsenen schwarzen RADIALFASERN, bei Feuchtigkeit deutlich schmierig-klebrig (Schleimhut), oft schwacher gelbgrünlicher Schimmer an Hutrand/Druckstellen.","Erd-Ritterling (hier als giftig gefuehrt): Hut mausgrau, fein FILZIG-SCHUPPIG (nicht radialfaserig, nie schmierig), trocken und matt, ohne Gelbgruenton.","portentosum-Fleisch/Lamellen koennen einen schwachen gelbgruenlichen Ton zeigen (v.a. an Druck/Schnitt) - NICHT als alleiniges Sicherheitsmerkmal verwenden, da variabel; terreum bleibt rein grau.","portentosum riecht/schmeckt mehlig-mild; terreum praktisch geruchlos und mild.","ACHTUNG Lebensgefahr in der grauen Ritterlings-Gruppe: der toedlich giftige Tiger-Ritterling (T. pardinum) sieht aehnlich aus (mehliger Geruch, grobe ziegelartige Schuppen, kraeftiger Wuchs) - bei jedem Zweifel ALLE grauen Ritterlinge stehen lassen."}','Schneeritterling hat einen feucht-schmierigen (schleimigen) Hut mit eingewachsenen schwarzen Radialfasern und allenfalls schwachem Gelbgruenton; der Erd-Ritterling ist trocken, fein filzig-schuppig und rein mausgrau. Der Schleimhut bei Feuchtigkeit ist das auffaelligste Trennmerkmal.','portentosum mild mehlig; terreum nahezu geruchlos. Ein kraeftig mehliger Geruch bei einem grauen Ritterling ist KEINE Entwarnung - er passt auch zum toedlichen Tiger-Ritterling.','Beide bei Nadelbaeumen (v.a. Kiefer, auch Fichte) auf eher sandigen, kalkarmen Boeden im Herbst; der Standort trennt NICHT zuverlaessig.','Beide weisses Sporenpulver - nicht als Trennmerkmal nutzbar.','Graue Ritterlinge sind ein Anfaenger-Tabu: in dieser Farbgruppe stehen mehrere giftige bis toedliche Arten (inkl. Tiger-Ritterling T. pardinum). Nur sammeln, wenn der schmierige Hut MIT schwarzen Radialfasern eindeutig bestimmt ist und jeder Verdacht auf grobe Schuppen/kraeftigen Wuchs ausgeschlossen wurde - im Zweifel stehen lassen.','123pilze, pilzbuch-pilzwelten.de, DGfM, VAPKO, GiftnotrufZentrale (CH-Notruf 145)'),
('tricholoma_portentosum','tricholoma_ustale','mittel','{"T. ustale (giftig): Hut rotbraun bis kastanienbraun, bei Feuchte schmierig-schleimig; Lamellen werden rasch rostfleckig; Fleisch braeunt, Geschmack bitterlich.","T. portentosum (essbar): Hut grau mit schwarzen Radialfasern (nicht rotbraun), Lamellen grau-weisslich, oft gelblich getoent, ohne Rostflecken.","Geschmack roh: ustale unangenehm bitter, portentosum mild - die Geschmacksprobe (kauen, NICHT schlucken, ausspucken) hilft, ist aber kein alleiniges Kriterium.","Saison/Standort: portentosum vor allem spaeter Herbst bis Frost bei Nadelbaeumen; ustale Hochsommer bis Spaetherbst vorwiegend im Laubwald (Buche/Eiche).","ustale verfaerbt Fleisch braeunlich, portentosum kaum verfaerbend."}','ustale einfarbig rotbraun und schmierig mit rostfleckig werdenden Lamellen; portentosum grau mit schwarzer Radialfaserung.','ustale schwach mehlig, portentosum mild mehlig-gurkig - Geruch trennt hier nur schwach, Farbe entscheidet.','ustale im Laubwald (Buche bevorzugt, auch Eiche); portentosum bei Kiefer/Fichte auf saurem Boden im Spaetherbst.','Beide weisses Sporenpulver - kein Trennmerkmal.','Rotbrauner, schmieriger Hut mit rostfleckigen Lamellen und bitterem Geschmack = giftiger Brandiger Ritterling, nicht sammeln.','123pilze, pilzbuch-pilzwelten.de, Wikipedia (Brandiger Ritterling), VAPKO/DGfM'),
('zigeunerpilz','cortinarius_orellanus','sehr_hoch_lebensgefahr','{"Reifpilz besitzt einen festen haeutigen Stielring mit doppeltem Rand; der Orangefuchsige Raukopf hat KEINEN echten Ring, sondern nur fluechtige Schleierfasern (Cortina).","Reifpilz-Hut ist grau-lila bereift und runzelig; der Raukopf-Hut ist trocken-fasrig bis feinschuppig und einheitlich satt orange-/kupfer-/rostbraun ohne Bereifung.","Raukopf-Stiel ist gleichfarbig bis gelblich und nicht ausgepraegt genattert; Reifpilz-Stiel traegt die haeutige doppelrandige Manschette.","Gift Orellanin ist hitze-/trocknungsbestaendig und fuehrt nach tagelang-wochenlanger Latenz (3-14 Tage) zu toedlichem Nierenversagen — kein Probier-Test und kein Entgiften durch Kochen moeglich."}','Reifpilz: strohgelb-gelbbrauner, grau-weisslich-lila bereifter, laengsrunzeliger Hut mit doppelrandigem haeutigem Ring. Orangefuchsiger Raukopf: satt orange- bis kupfer-/rostbrauner, matt-fasriger bis feinschuppiger, trockener Hut OHNE Bereifung; KEIN echter Ring, nur fluechtige Cortina; Stiel zylindrisch, gleichfarbig oder gelblich, nicht ausgepraegt genattert (anders als rubellus).','Reifpilz: mild. Orangefuchsiger Raukopf: schwach rettichartig.','Reifpilz: Nadel- und (selten) Laubwald, oft saurer sandiger Boden, bei Heidelbeere. Orangefuchsiger Raukopf: waermebeguenstigte Laubwaelder bei Eiche, Buche, Hasel, Esskastanie auf sauren bis basischen Boeden (Juli-Oktober) — typischerweise kein Nadelwald.','Reifpilz: hell zimtbraun/rostgelb. Orangefuchsiger Raukopf: rostbraun. Kein zuverlaessig trennendes Einzelmerkmal.','Reifpilz nur mit eindeutigem festem Ring mit doppeltem Rand verzehren. Ein satt orange-/rostbrauner, trocken-fasriger Hut OHNE Bereifung und ohne echten Ring (nur Schleierfasern) deutet auf den toedlichen Orangefuchsigen Raukopf — Finger weg, ab zur Pilzkontrolle (VAPKO).','https://de.wikipedia.org/wiki/Orangefuchsiger_Raukopf · https://www.dgfm-ev.de/pilz-des-jahres/2002-orangefuchsiger-raukopf · https://de.wikipedia.org/wiki/Reifpilz'),
('zigeunerpilz','cortinarius_rubellus','sehr_hoch_lebensgefahr','{"Reifpilz hat einen festen, haeutigen Stielring mit charakteristischem DOPPELTEM Rand; der Spitzgebuckelte Raukopf hat KEINEN echten Ring, nur fluechtige Schleierfasern (Cortina).","Reifpilz-Hut ist matt grau-weisslich bis lila BEREIFT und laengsrunzelig; der Raukopf hat einen trockenen, fein filzig-fasrigen, rotfuchsig-zimtbraunen Hut mit deutlichem SPITZEM Buckel.","Raukopf-Stiel ist schlank und gelblich GENATTERT (gelbe Velumguertel); Reifpilz-Stiel ist dicker und traegt die haeutige Manschette statt Guertel.","Verzehr nur bei eindeutig vorhandenem doppelrandigem Ring; das Gift Orellanin ist hitze- und trocknungsstabil und verursacht nach 2-21 Tagen Latenz irreversibles Nierenversagen — kein Kochen/Trocknen entgiftet."}','Reifpilz: strohgelber bis gelbbrauner Hut mit grau-weisslich-lila Bereifung (Velum), Oberflaeche charakteristisch laengsrunzelig/gefurcht, deutlich haeutiger Stielring mit doppeltem Rand. Raukopf rubellus: gelb- bis orange- oder rotfuchsig-zimtbrauner, trockener und fein filziger Hut mit spitzem (oder abgerundetem) Buckel, KEIN echter Ring (nur fluechtige Cortina/Schleierreste), Stiel schlank und gelblich genattert (gelbe Velumguertel).','Reifpilz: angenehm/mild. Spitzgebuckelter Raukopf: schwach rettichartig.','Reifpilz: Nadel- und (selten) Laubwald, gern bei Heidelbeere auf saurem, sandigem Boden, August-Oktober. Spitzgebuckelter Raukopf: vor allem Nadelwald (Fichtenbestaende), oft in feuchten/moorigen Lagen auf sauren Boeden, bei Heidelbeere — die Habitat-Ueberlappung verschaerft das Risiko.','Reifpilz: hell zimtbraun bis rostgelb. Raukopf rubellus: rostbraun. Sporenfarbe trennt hier NICHT zuverlaessig — niemals als alleiniges Merkmal nutzen.','Such am Stiel den festen haeutigen Ring mit dem charakteristischen DOPPELTEN Rand — fehlt dieser Ring und ist der Stiel stattdessen gelblich genattert mit nur fluechtigen Schleierfasern, ist es kein Reifpilz, sondern moeglicherweise der toedliche Raukopf. Im jungen Zustand im Zweifel IMMER zur Pilzkontrollstelle (VAPKO).','https://www.awl.ch/pilze/pilz_dateien/cortinarius-rubellus/spitzgebuckelter-raukopf.htm · https://de.wikipedia.org/wiki/Spitzgebuckelter_Raukopf · https://de.wikipedia.org/wiki/Reifpilz'),
('zigeunerpilz','cortinarius_semisanguineus','hoch','{"C. semisanguineus hat jung leuchtend blutrote Lamellen – ein klares Warnsignal; der essbare Zigeunerpilz (C. caperatus) hat blass ocker-tonfarbene, NIE rote Lamellen.","Hut: C. caperatus graubraun-ocker mit silbrig-runzeligem ''reifartigem'' Überzug am Scheitel; C. semisanguineus olivocker- bis umberbraun, glatt-faserig.","C. caperatus hat einen häutigen Ring am Stiel; C. semisanguineus nur flüchtige Cortina-Reste, keinen echten Ring.","Beide Cortinarien mit rostbraunem Sporenpulver – die Lamellenfarbe und der Ring sind hier die Schlüssel.","Grösse: C. caperatus kräftig (Hut 5–10 cm); C. semisanguineus klein-zierlich (Hut 2–5 cm)."}','Zigeunerpilz gross, graubraun mit reifartig-runzeligem Hut und häutigem Ring; C. semisanguineus klein, olivbraun mit blutroten Lamellen ohne echten Ring.','Zigeunerpilz mild-angenehm; C. semisanguineus geruchlos bis schwach rettichartig.','Beide in sauren Nadel-/Mischwäldern, oft bei Heidelbeere; daher ist die Lamellenfarbe das entscheidende Trennmerkmal, nicht der Standort.','Beide rostbraun – das Sporenpulver trennt NICHT; entscheidend sind blutrote Lamellen (semisanguineus, giftig) vs. ocker und häutiger Ring (caperatus, essbar).','Lamellen kontrollieren: jede Spur Blutrot = Hautkopf = stehen lassen. Der Zigeunerpilz ist der EINZIGE empfohlene essbare Schleierling – im Zweifel gehört JEDER Cortinarius ungegessen weggeworfen.','123pilze – Blutblättriger Hautkopf (giftig), Wikipedia – Reifpilz, pilzbuch-pilzwelten.de – Cortinarius caperatus / semisanguineus'),
('zigeunerpilz','cortinarius_splendens','sehr_hoch_lebensgefahr','{"Zigeunerpilz (Reifpilz, Cortinarius caperatus): Hut graubräunlich/ockerlich mit weißlich-bereiftem Schimmer, NICHT leuchtend gelb — Cortinarius splendens: kräftig schwefel- bis leuchtendgelb in allen Teilen.","Reifpilz hat einen echten häutigen Stielring; der Schöngelbe Klumpfuß hat nur eine flüchtige gelbe Cortina (Spinnwebschleier), KEINEN festen häutigen Ring.","Cortinarius splendens hat eine gerandete gelbe Knolle und gelbes Fleisch; der Reifpilz hat eine schwach knollige Basis ohne leuchtendes Gelb.","Der Schöngelbe Klumpfuß enthält ein nephrotoxisches Gift (Orellanin-Syndrom-Typ, chemisch noch nicht abschließend identifiziert — NICHT zwingend Orellanin selbst) und kann tödliches Nierenversagen mit tage- bis wochenlanger Latenz auslösen.","Reifpilz im sauren Nadel-/Mischwald und Heidelbeerbeständen; C. splendens als Mykorrhizapilz bevorzugt kalkreiche Laubwälder (besonders bei Buche)."}','Leuchtgelb = Warnsignal: jeder durchgehend schwefel-/leuchtendgelbe Schleierling ist tabu — der essbare Reifpilz ist matt grau-ocker-bräunlich mit bereiftem Hut und häutigem Ring.','Reifpilz aromatisch-pilzig; Cortinarius splendens unauffällig bis leicht rettichartig — Geruch trennt NICHT zuverlässig.','Reifpilz in sauren Nadel-/Mischwäldern und Heidelbeerbeständen; Schöngelber Klumpfuß als Mykorrhizapilz in kalkreichen Laubwäldern, typisch bei Buche.','Beide rostbraun — daher KEIN Trennkriterium. Auf Hutfarbe (leuchtgelb!), echten häutigen Ring und gerandete gelbe Knolle achten.','Kein Schleierling (Cortinarius) mit Rost-Sporenpulver für Anfänger — leuchtend gelbe Klumpfüße grundsätzlich stehen lassen. Das Nierengift wirkt erst nach Tagen, eine Vergiftung ist anfangs unbemerkt. Im Zweifel Pilzkontrolle (VAPKO).','123pilze (123pilzsuche.de), DGfM Vergiftungssyndrome, gifte.de, mycopedia.ch, Wikipedia (Leuchtendgelber Klumpfuß)')
